--for PO totals and values for each revision of the PO
FUNCTION get_po_rev_amts(poheaderid IN NUMBER) RETURN po_rev_amt_tbl PIPELINED IS
  CURSOR c_revs IS
    SELECT *
      FROM (
        SELECT pha.revision_num,
               pha.currency_code,
               pha.po_header_id,
               poarc.maxrev
          FROM po_headers_archive_all pha,
               (SELECT max(phaa.revision_num) maxrev FROM po_headers_archive_all phaa WHERE phaa.po_header_id = poheaderid) poarc
         WHERE pha.revision_num >= GREATEST(0, poarc.maxrev - 20 + 1) and pha.po_header_id = poheaderid
         ORDER BY pha.revision_num DESC
      ) revs WHERE revs.revision_num >= GREATEST(0, revs.maxrev - 20 + 1) and revs.po_header_id = poheaderid
   ORDER BY revs.revision_num; -- final result ASC

  l_rec po_rev_amt_rec;
BEGIN
  FOR rev IN c_revs LOOP
    -- Precision/currency info
    fnd_currency.get_info(rev.currency_code, l_rec.precision, l_rec.ext_precision, l_rec.min_acct_unit);

    -- Net total: example pattern for "STANDARD"; If you need blanket/contract, customize here
    SELECT NVL(SUM(
             ROUND(NVL((plaa.quantity * plaa.unit_price), plaa.amount), l_rec.precision))
           ,0)
      INTO l_rec.net_total
      FROM po_lines_archive_all plaa
     WHERE plaa.po_header_id = rev.po_header_id
       AND plaa.revision_num = rev.revision_num;

    -- Tax total (simplified; can expand per your detailed business rules)
    SELECT NVL(SUM(
             ROUND(
               pla_dist.nonrecoverable_tax *
                CASE
                  WHEN NVL(pla_dist.quantity_ordered,0) = 0 THEN
                    CASE WHEN NVL(pla_dist.amount_ordered,0)=0 THEN 0
                         ELSE (NVL(pla_dist.amount_ordered,0)-NVL(pla_dist.amount_cancelled,0))
                              / pla_dist.amount_ordered
                    END
                  ELSE (NVL(pla_dist.quantity_ordered,0)-NVL(pla_dist.quantity_cancelled,0))
                       / pla_dist.quantity_ordered
                END,
               l_rec.precision))
           ,0)
      INTO l_rec.tax
      FROM po_distributions_archive_all pla_dist
     WHERE pla_dist.po_header_id = rev.po_header_id
       AND pla_dist.revision_num = rev.revision_num;

    l_rec.revision_num := rev.revision_num;
    l_rec.currency_code := rev.currency_code;
    l_rec.total := l_rec.net_total + l_rec.tax;

    PIPE ROW (l_rec);
  END LOOP;
  RETURN;
END get_po_rev_amts;

--change the following get_doc_amts to be only for REQS
--use above get_po_rev_amts for PO since we need totals and values for each revision of the PO

FUNCTION get_doc_amts(p_amt_type IN VARCHAR2)
  RETURN NUMBER IS
  l_currency      VARCHAR2(15);
  l_precision     NUMBER(1);
  l_ext_precision NUMBER(2);
  l_min_acct_unit NUMBER;
  l_net_total     NUMBER;
  l_doc_subtype   VARCHAR2(50);
  l_docid         NUMBER;
  l_relid         NUMBER;
  l_code          VARCHAR2(1);
  l_tax           NUMBER;
  l_step          VARCHAR2(5);
BEGIN
  l_step := '10';

-- initialize especially for PA
  l_precision := 0;
  l_ext_precision := 0;
  l_min_acct_unit := 0;
  l_net_total  := 0;
  l_tax := 0;

   print_log ('step 10 - l_precision '||l_precision); 
   print_log ('l_ext_precision '||l_ext_precision); 
   print_log ('l_min_acct_unit '||l_min_acct_unit); 
   print_log ('l_net_total '||l_net_total); 
   print_log ('l_tax '||l_tax); 

  l_doc_subtype := g_sql_tokens('##$$SUBTP$$##');
  l_docid := to_number(g_sql_tokens('##$$DOCID$$##'));

  IF NOT g_doc_amts.exists('NET_TOTAL') THEN
    -- Get currency
    IF g_sql_tokens('##$$TRXTP$$##') IN ('PO','PA','RELEASE') THEN
      l_step := '20';
      BEGIN
        SELECT currency_code INTO l_currency
        FROM po_headers_all 
        WHERE po_header_id = l_docid;
      EXCEPTION WHEN OTHERS THEN 
        l_currency := null;
      END;
    ELSIF g_sql_tokens('##$$TRXTP$$##') IN ('REQUISITION') THEN
      l_step := '30';
      BEGIN
        SELECT max(currency_code) INTO l_currency
        FROM po_requisition_lines_all 
        WHERE requisition_header_id = l_docid;
      EXCEPTION WHEN OTHERS THEN 
        l_currency := null;
      END;
    END IF;

    IF l_currency is null THEN
      l_currency := 'USD';
    END IF;

    l_step := '40';
    fnd_currency.get_info(l_currency, l_precision, l_ext_precision,
      l_min_acct_unit);

    g_doc_amts('PRECISION') := l_precision;
    g_doc_amts('EXT_PRECISION') := l_ext_precision;
    g_doc_amts('MIN_ACCT_UNIT') := l_min_acct_unit;

   print_log ('step 40 - l_precision '||l_precision); 
   print_log ('l_ext_precision '||l_ext_precision); 
   print_log ('l_min_acct_unit '||l_min_acct_unit); 

    -- Get net_total pull code from po_notifications_sv3.get_doc_total
    -- since that uses operating unit striped views
    l_step := '50';
    IF l_doc_subtype IN ('BLANKET', 'CONTRACT') THEN
      SELECT NVL(blanket_total_amount,0) INTO l_net_total
      FROM po_headers_all ph
      WHERE ph.po_header_id = l_docid;
    ELSE
      IF (l_doc_subtype IN ('PLANNED', 'STANDARD')) THEN
        l_code := 'H';
      ELSIF (l_doc_subtype IN ('RELEASE', 'SCHEDULED')) THEN
        l_code := 'R';
      ELSIF (l_doc_subtype IN ('INTERNAL', 'PURCHASE')) THEN
        l_code := 'E';
      END IF;
      IF (l_code <> 'E') THEN  
        IF (l_code = 'H') THEN  
          l_net_total := po_core_s.get_total(l_code, l_docid);
        ELSIF (l_code = 'R') THEN
          l_relid := to_number(g_sql_tokens('##$$RELID$$##'));
          l_net_total := po_core_s.get_total(l_code, l_relid);
        END IF;
-- added this to calculate l_code E requisition net total differently than non-requisition
      ELSIF (l_code = 'E') THEN
           SELECT
             SUM(ROUND( DECODE(prla.QUANTITY, NULL, NVL(prla.AMOUNT, 0), ((NVL(prla.QUANTITY,0) - NVL(prla.QUANTITY_CANCELLED,0)) * NVL(prla.UNIT_PRICE,0)) ) , fndc.precision )) INTO l_net_total
             FROM PO_REQUISITION_LINES_ALL prla, fnd_currencies fndc
             WHERE fndc.currency_code = l_currency
             AND REQUISITION_HEADER_ID = l_docid
             AND NVL(MODIFIED_BY_AGENT_FLAG, 'N') = 'N';
      END IF;  -- end of new code for requisitions 2024-05-23 in Procurement Approval Analyzer version 200.60
    END IF;

    g_doc_amts('NET_TOTAL') := l_net_total;

   print_log ('step 10 - l_precision '||l_precision); 
   print_log ('l_ext_precision '||l_ext_precision); 
   print_log ('l_min_acct_unit '||l_min_acct_unit); 
   print_log ('l_net_total '||l_net_total); 
   print_log ('l_tax '||l_tax); 

    IF g_sql_tokens('##$$TRXTP$$##') IN ('PO') THEN    --remove PA from the IN clause because no distributions for PA
      l_step := '60';
      IF l_min_acct_unit > 0 THEN
        l_step := '70';
        SELECT nvl(sum(round(d.nonrecoverable_tax *
                 decode(nvl(d.quantity_ordered,0),
                   0, decode(nvl(d.amount_ordered,0),
                        0, 0,
                        (nvl(d.amount_ordered,0) - nvl(d.amount_cancelled,0)) /
                          d.amount_ordered),
                   (nvl(d.quantity_ordered,0) - nvl(d.quantity_cancelled,0)) /
                     d.quantity_ordered)
                 / l_min_acct_unit) * l_min_acct_unit), 0) tax
        INTO l_tax
        FROM po_distributions d
        WHERE po_header_id = to_number(g_sql_tokens('##$$DOCID$$##'));
      ELSE
        l_step := '80';
        SELECT nvl(sum(round(d.nonrecoverable_tax *
                 decode(nvl(d.quantity_ordered,0),
                   0, decode(nvl(d.amount_ordered,0),
                        0, 0,
                        (nvl(d.amount_ordered,0) - nvl(d.amount_cancelled,0)) /
                          d.amount_ordered),
                   (nvl(d.quantity_ordered,0) - nvl(d.quantity_cancelled,0)) /
                     d.quantity_ordered),
                 l_precision)), 0) tax
        INTO l_tax
        FROM po_distributions_all d
        WHERE po_header_id = to_number(g_sql_tokens('##$$DOCID$$##'));
      END IF;
    ELSIF g_sql_tokens('##$$TRXTP$$##') = 'RELEASE' THEN
      IF l_min_acct_unit > 0 THEN
        l_step := '90';
        SELECT nvl(sum(round(d.nonrecoverable_tax * 
                 decode(nvl(d.quantity_ordered,0),
                   0, decode(nvl(d.amount_ordered,0),
                        0, 0,
                        (nvl(d.amount_ordered,0) - nvl(d.amount_cancelled,0)) /
                          d.amount_ordered),
                   (nvl(d.quantity_ordered,0) - nvl(d.quantity_cancelled,0)) /
                     d.quantity_ordered) /
                    l_min_acct_unit) * l_min_acct_unit), 0) tax
        INTO l_tax
        FROM po_distributions_all d
        WHERE po_release_id =  to_number(g_sql_tokens('##$$RELID$$##'));
      ELSE
        l_step := '100';
        SELECT nvl(sum(round(d.nonrecoverable_tax *
                 decode(nvl(d.quantity_ordered,0),
                   0, decode(nvl(d.amount_ordered,0),
                        0, 0,
                        (nvl(d.amount_ordered,0) - nvl(d.amount_cancelled,0)) /
                          d.amount_ordered),
                   (nvl(d.quantity_ordered,0) - nvl(d.quantity_cancelled,0)) /
                     d.quantity_ordered),
                 l_precision)), 0) tax
      INTO l_tax
      FROM po_distributions_all d
      WHERE po_release_id = to_number(g_sql_tokens('##$$RELID$$##'));
     END IF;
    ELSIF g_sql_tokens('##$$TRXTP$$##') = 'REQUISITION' THEN
      l_step := '110';
      SELECT nvl(sum(nonrecoverable_tax), 0) tax
      INTO l_tax
      FROM po_requisition_lines_all rl,
           po_req_distributions_all rd
      WHERE rl.requisition_header_id = to_number(g_sql_tokens('##$$DOCID$$##'))
      AND   rd.requisition_line_id = rl.requisition_line_id
      AND   nvl(rl.cancel_flag,'N') = 'N'
      AND   nvl(rl.modified_by_agent_flag, 'N') = 'N' ;
    END IF;

    l_step := '120';
    g_doc_amts('TAX') := l_tax;
    g_doc_amts('TOTAL') := g_doc_amts('NET_TOTAL') + g_doc_amts('TAX');


   print_log ('step 120 - l_precision '||l_precision); 
   print_log ('l_ext_precision '||l_ext_precision); 
   print_log ('l_min_acct_unit '||l_min_acct_unit); 
   print_log ('l_net_total '||l_net_total); 
   print_log ('l_tax '||l_tax); 

  END IF;
  l_step := '130';
  RETURN(g_doc_amts(p_amt_type));

EXCEPTION WHEN OTHERS THEN
  print_log('Error in get_doc_amts:'||l_step||': '||sqlerrm);
  raise;
END get_doc_amts;

-----------------------------------------------------------
-- Function to check the version of a package body
-- against a specific provided version
-- Input params:
--    - package name
--    - version to compare against
-- return 1 if higher, 0 if the same, -1 if lower
-----------------------------------------------------------

FUNCTION chk_pkg_body_version(p_package_name IN VARCHAR2, p_expected_version IN VARCHAR2) 
   RETURN NUMBER IS

   l_step VARCHAR2(2);
   l_package_version VARCHAR2 (100);
   l_expected_version VARCHAR2 (100);
   l_pkg_ver_seg     NUMBER;
   l_expect_ver_seg  NUMBER;
   l_next_pos1 NUMBER;
   l_next_pos2 NUMBER;
   
   CURSOR c_package_version (p_package_name VARCHAR2) IS
     SELECT rtrim(ltrim(substr(ds.text, instr(ltrim(rtrim(ds.text)), ' 1', 1), (instr(ltrim(rtrim(ds.text)), ' 20') - instr(ltrim(rtrim(ds.text)), ' 1', 1))))) 
      FROM dba_source ds, dba_objects do
      WHERE upper(ds.name) = p_package_name
      AND ds.line = 2
      AND ds.name = do.object_name
      AND ds.type = do.object_type
      AND do.object_type = 'PACKAGE BODY';
   
BEGIN
   l_step := '10';
   l_expected_version := p_expected_version;
   
   OPEN c_package_version(p_package_name);
      FETCH c_package_version INTO l_package_version;
   CLOSE c_package_version;
      
   l_step := '20';
   loop
      
      l_step := '30';
      l_next_pos1 := to_number(nvl(instr(l_package_version, '.'), 0));
      
      if (l_next_pos1 != 0) then 
         l_pkg_ver_seg := to_number(substr (l_package_version, 1, l_next_pos1));
         l_package_version := substr (l_package_version, l_next_pos1+1);
      else    
         l_pkg_ver_seg := l_package_version;
      end if;
      
      l_next_pos2 := to_number(nvl(instr(l_expected_version, '.'), 0));
      if (l_next_pos2 != 0) then 
         l_expect_ver_seg := to_number(substr (l_expected_version, 1, l_next_pos2));
         l_expected_version := substr(l_expected_version, l_next_pos2+1);
      else
          l_expect_ver_seg := l_expected_version;
      end if;    
          
      l_step := '40';
      if ((l_pkg_ver_seg > l_expect_ver_seg) or 
          ((l_pkg_ver_seg = l_expect_ver_seg) and (l_next_pos2 = 0) and (l_next_pos1 > 0))) then
          print_log ('Current version is greater.');
          return 1;
      elsif ((l_pkg_ver_seg < l_expect_ver_seg) or 
           ((l_pkg_ver_seg = l_expect_ver_seg) and (l_next_pos1 = 0) and (l_next_pos2 > 0))) then
          print_log ('Current version is lower.');
          return -1;
      end if;
      
     exit when ((l_pkg_ver_seg is null) or (l_expect_ver_seg is null) or (l_next_pos1 = 0) or (l_next_pos2 = 0));
   end loop;
   
   l_step := '50';
   print_log ('Versions are equal.');   
   RETURN 0;
   
EXCEPTION WHEN OTHERS THEN
  print_log('Error in chk_pkg_body_version:'||l_step||': '||sqlerrm);
  return -1;  
END chk_pkg_body_version;


-----------------------------------------------------------
-- Function to compare two versions of a file
-- Input params:
--    - version1, version2
-- returns:
--    -  1 if version1 is higher than version2
--    -  0 if versions are equal
--    - -1 if version1 is lowen than version2
-----------------------------------------------------------

FUNCTION compare_versions(p_version1 VARCHAR2, p_version2 VARCHAR2) 
   RETURN NUMBER IS

   l_step VARCHAR2(10);
   l_version1 VARCHAR2 (100);
   l_version2 VARCHAR2 (100);
   l_ver1_seg  NUMBER;
   l_ver2_seg  NUMBER;
   l_next_pos1 NUMBER;
   l_next_pos2 NUMBER;
   l_index_count NUMBER;

BEGIN
   l_version1 := p_version1;
   l_version2 := p_version2;
   l_step := '10';
   l_index_count := 1;

   loop
      l_step := '20' || to_char(l_index_count);
      l_next_pos1 := to_number(nvl(instr(l_version1, '.'), 0));
      
      if (l_next_pos1 != 0) then 
         l_ver1_seg := to_number(substr (l_version1, 1, l_next_pos1));
         l_version1 := substr (l_version1, l_next_pos1+1);
      else    
         l_ver1_seg := l_version1;
      end if;
      
      l_next_pos2 := to_number(nvl(instr(l_version2, '.'), 0));
      if (l_next_pos2 != 0) then 
         l_ver2_seg := to_number(substr (l_version2, 1, l_next_pos2));
         l_version2 := substr(l_version2, l_next_pos2+1);
      else
          l_ver2_seg := l_version2;
      end if;    
          
      l_step := '40';
      if ((l_ver1_seg > l_ver2_seg) or 
          ((l_ver1_seg = l_ver2_seg) and (l_next_pos2 = 0) and (l_next_pos1 > 0))) then
          return 1;
      elsif ((l_ver1_seg < l_ver2_seg) or 
           ((l_ver1_seg = l_ver2_seg) and (l_next_pos1 = 0) and (l_next_pos2 > 0))) then
          return -1;
      end if;
      
     exit when ((l_ver1_seg is null) or (l_ver2_seg is null) or (l_next_pos1 = 0) or (l_next_pos2 = 0));
     l_index_count := l_index_count + 1;
   end loop;
   
   l_step := '50';
   RETURN 0;
     
 
EXCEPTION WHEN OTHERS THEN
  print_log('Error in compare_versions:'||l_step||': '||sqlerrm);
  return -1;  
END compare_versions;

-----------------------------------------------------------
-- Function to check the maximum version of a file
-- Input params:
--    - filename
-- returns the maximum version found in ad_file_versions
-----------------------------------------------------------

FUNCTION max_file_version(p_filename VARCHAR2) 
    RETURN VARCHAR2 IS

    l_step VARCHAR2(2);
    l_temp_version VARCHAR2(200);
    l_max_version VARCHAR2(200);
    
    CURSOR c_file_version1 IS 
      SELECT av.version
        FROM ad_files af,
             ad_file_versions av
       WHERE af.file_id= av.file_id
         AND lower(af.filename) = p_filename
         AND af.subdir like '%US%';
         
    CURSOR c_file_version2 IS 
      SELECT av.version
        FROM ad_files af,
             ad_file_versions av
       WHERE af.file_id= av.file_id
         AND lower(af.filename) = p_filename
         AND af.subdir like 'patch/115/odf';
         
BEGIN
     l_step := '10';
     l_max_version := '1';
     IF (regexp_like(p_filename, '.odf')) THEN
         OPEN c_file_version2;
         l_step := '20';
         LOOP
             FETCH c_file_version2 into l_temp_version;
             EXIT WHEN c_file_version2%NOTFOUND;
      
             IF (compare_versions(l_temp_version, l_max_version) = 1) THEN
                 l_max_version := l_temp_version;
             END IF;
         END LOOP;    
         
         l_step := '30';
         CLOSE c_file_version2;
     ELSE     
         OPEN c_file_version1;
         l_step := '20';
         LOOP
             FETCH c_file_version1 into l_temp_version;
             EXIT WHEN c_file_version1%NOTFOUND;
      
             IF (compare_versions(l_temp_version, l_max_version) = 1) THEN
                 l_max_version := l_temp_version;
             END IF;
         END LOOP;    
         
         l_step := '30';
         CLOSE c_file_version1;
     END IF;    
     
     RETURN l_max_version;
 
EXCEPTION WHEN OTHERS THEN 
   RETURN NULL;
   
END max_file_version;   
  

FUNCTION verify_approver(p_empid IN NUMBER) return VARCHAR2 IS
  l_return_status VARCHAR2(1);
  l_return_code   VARCHAR2(25);
  l_exception_msg VARCHAR2(2000);
  l_auth_fail_msg VARCHAR2(2000);
  l_doc_id        NUMBER;
  
  PRAGMA AUTONOMOUS_TRANSACTION;
  
BEGIN
  IF p_empid <> g_curr_empid OR g_curr_empid is null THEN
    IF g_sql_tokens('##$$TRXTP$$##') = 'RELEASE' THEN
      l_doc_id := to_number(g_sql_tokens('##$$RELID$$##'));
    ELSE
      l_doc_id := to_number(g_sql_tokens('##$$DOCID$$##'));
    END IF;
    g_curr_empid := p_empid;
    po_document_action_pvt.verify_authority(
      p_document_id => l_doc_id,
      p_document_type => g_sql_tokens('##$$TRXTP$$##'),
      p_document_subtype => g_sql_tokens('##$$SUBTP$$##'),
      p_employee_id => p_empid,
      x_return_status => l_return_status,
      x_return_code => l_return_code,
      x_exception_msg => l_exception_msg,
      x_auth_failed_msg  => l_auth_fail_msg);
    g_app_results('STATUS') := l_return_status;
    g_app_results('CODE') := l_return_code;
    g_app_results('EXC_MSG') := l_exception_msg;
    g_app_results('FAIL_MSG') := l_auth_fail_msg;
    
    rollback;
   
  END IF;
return null;  -- moved to outside the IF
EXCEPTION WHEN OTHERS THEN
  print_log('Error in verify_approver: '||sqlerrm);
  rollback;
  raise;
  return null;
END verify_approver;


FUNCTION is_extended_req_table RETURN BOOLEAN IS
   l_count  NUMBER;
BEGIN

  Select count(*)
    INTO l_count  
    from all_tab_cols
    where column_name = 'CONFORMED_HEADER_ID'
      and table_name = 'PO_REQUISITION_HEADERS_ALL';
      
  IF l_count > 0 THEN
    RETURN TRUE;
  ELSE 
    RETURN FALSE;
  END IF;  
      
EXCEPTION
   WHEN OTHERS THEN
      print_log('Could not determine if PO_REQUISITION_HEADERS_ALL includes column CONFORMED_HEADER_ID. Error: ' || SQLERRM);
      return false;   
END is_extended_req_table;


-------------------------
-- Recommended Patches
-------------------------

FUNCTION check_rec_patches_1 RETURN VARCHAR2 IS
  /* Signature POA_CHECK_REC_PATCHES */
  l_col_rows   COL_LIST_TBL := col_list_tbl(); -- Row values
  l_rel_rows   COL_LIST_TBL := col_list_tbl(); -- Row release
  l_hdr        VARCHAR_TBL  := varchar_tbl(); -- Column headings
  l_app_date   DATE;         -- Patch applied date
  l_extra_info HASH_TBL_4K;  -- Extra information
  l_step       VARCHAR2(10);
  l_sig        SIGNATURE_REC;
  l_rel        VARCHAR2(3);
  l_rows       NUMBER := 0;

  CURSOR get_app_date(p_ptch VARCHAR2, p_rel VARCHAR2) IS
   SELECT min(Last_Update_Date) as date_applied
    FROM Ad_Bugs Adb
    WHERE Adb.Bug_Number like p_ptch
    AND ad_patch.is_patch_applied(p_rel, -1, adb.bug_number)!='NOT_APPLIED';

BEGIN

    print_log('Processing recommended patches signature: POA_CHECK_REC_PATCHES (check_rec_patches_1) "Recommended Patches" (version 19)');

  -- Column headings
  l_step := '10';
  l_hdr.extend(5);
  l_hdr(1) := 'Patch';
  l_hdr(2) := 'Applied';
  l_hdr(3) := 'Date';
  l_hdr(4) := 'Name';
  l_hdr(5) := 'Note';
  l_col_rows.extend(5);
  l_rel_rows.extend(1);

IF substr(g_rep_info('Apps Version'),1,4) = '12.2' THEN
   l_rel := 'R12';

   l_rows := l_rows + 1;
   l_rel_rows(1)(l_rows) := l_rel;
   l_col_rows(1)(l_rows) := '17947999';
   l_col_rows(2)(l_rows) := 'No';
   l_col_rows(3)(l_rows) := NULL;
   l_col_rows(4)(l_rows) := 'Release 12.2.3 - provides R12.PRC_PF.B.delta.4';
   l_col_rows(5)(l_rows) := '[222339/KB370175]';

   l_rows := l_rows + 1;
   l_rel_rows(1)(l_rows) := l_rel;
   l_col_rows(1)(l_rows) := '17919161';
   l_col_rows(2)(l_rows) := 'No';
   l_col_rows(3)(l_rows) := NULL;
   l_col_rows(4)(l_rows) := '12.2.4 -ORACLE E-BUSINESS SUITE 12.2.4 RELEASE UPDATE PACK';
   l_col_rows(5)(l_rows) := '[1617458.1]';

END IF;

IF substr(g_rep_info('Apps Version'),1,4) = '12.1' THEN
   l_rel := 'R12';

   l_rows := l_rows + 1;
   l_rel_rows(1)(l_rows) := l_rel;
   l_col_rows(1)(l_rows) := '22779630';
   l_col_rows(2)(l_rows) := 'No';
   l_col_rows(3)(l_rows) := NULL;
   l_col_rows(4)(l_rows) := 'Oracle Purchasing Consolidation Patch for 12.1.3 - Apr 2016';
   l_col_rows(5)(l_rows) := '[2129056/KB251678]';

   l_rows := l_rows + 1;
   l_rel_rows(1)(l_rows) := l_rel;
   l_col_rows(1)(l_rows) := '21198991';
   l_col_rows(2)(l_rows) := 'No';
   l_col_rows(3)(l_rows) := NULL;
   l_col_rows(4)(l_rows) := 'Oracle Procurement Rollup patch (March 2015';
   l_col_rows(5)(l_rows) := '[1468883/KB346158]';

   l_rows := l_rows + 1;
   l_rel_rows(1)(l_rows) := l_rel;
   l_col_rows(1)(l_rows) := '13495209';
   l_col_rows(2)(l_rows) := 'No';
   l_col_rows(3)(l_rows) := NULL;
   l_col_rows(4)(l_rows) := 'Accrual Reconciliation Load Run Program Cannot Migrate Write Off Transactions from 11i to R12: errors with ORA-00001: unique constraint (BOM.CST_WRITE_OFFS_U1) violated.';
   l_col_rows(5)(l_rows) := '[1475396/KB782878]';

   l_rows := l_rows + 1;
   l_rel_rows(1)(l_rows) := l_rel;
   l_col_rows(1)(l_rows) := '12923944';
   l_col_rows(2)(l_rows) := 'No';
   l_col_rows(3)(l_rows) := NULL;
   l_col_rows(4)(l_rows) := 'After upgrading to 12.1.3 the PO Document Approval Manager (POXCON) dies immediately after starting it up.';
   l_col_rows(5)(l_rows) := '[1413393/KB792751]';

   l_rows := l_rows + 1;
   l_rel_rows(1)(l_rows) := l_rel;
   l_col_rows(1)(l_rows) := '12677981';
   l_col_rows(2)(l_rows) := 'No';
   l_col_rows(3)(l_rows) := NULL;
   l_col_rows(4)(l_rows) := 'Unable Approve a Purchase Order Due to Tax Error Exception: 023 - An unexpected error has occurred.';
   l_col_rows(5)(l_rows) := '[1281362/KB725738]';

   l_rows := l_rows + 1;
   l_rel_rows(1)(l_rows) := l_rel;
   l_col_rows(1)(l_rows) := '11063775';
   l_col_rows(2)(l_rows) := 'No';
   l_col_rows(3)(l_rows) := NULL;
