PROCEDURE print_error_args(
  p_message      VARCHAR2 DEFAULT '',
  l_step         VARCHAR2 DEFAULT '')
IS
  l_key   VARCHAR2(255);
BEGIN
    print_log(p_message);
    print_log('Error in validate_parameters at step: ' || l_step);
    dbms_output.put_line('***************************************************************');
    dbms_output.put_line('*** WARNING WARNING WARNING WARNING WARNING WARNING WARNING ***');
    dbms_output.put_line('***************************************************************');
    dbms_output.put_line('*** '||p_message);
    dbms_output.put_line('Parameter Values');
    print_out('<div>');
    print_out('<br>'||p_message);
    print_out('<br>Error in validate_parameters at step: ' || l_step);
    print_out('<br><br><b>Parameter Values:</b><br><ul>');
    l_key := g_parameters.first;
    FOR i IN 1..g_parameters.COUNT LOOP
       dbms_output.put_line(to_char(i) || '. ' || g_parameters(i).pname || ': ' || g_parameters(i).pvalue);
       print_out('<li>' || to_char(i) || '. ' || g_parameters(i).pname || ': ' || g_parameters(i).pvalue || '</li>');
    END LOOP;
    dbms_output.put_line('Error in validate_parameters at step: ' || l_step);
    print_out('</ul>');
    print_out('<br><br><b>Execution Details:</b><br><ul>');
    l_key := g_rep_info.first;
    WHILE l_key IS NOT NULL LOOP
       print_out('<li>' || l_key || ': ' || g_rep_info(l_key) || '</li>');
       l_key := g_rep_info.next(l_key);
    END LOOP;
    print_out('</ul>');
    print_out('</div>');
END print_error_args;


--########################################################################################
--     Beginning of specific code of this ANALYZER
--########################################################################################

----------------------------------------------------------------
--- Validate Parameters                                      ---
----------------------------------------------------------------
PROCEDURE validate_parameters(
            p_analysis_mode                IN VARCHAR2    DEFAULT NULL
           ,p_org_id                       IN NUMBER      DEFAULT NULL
           ,p_trx_type                     IN VARCHAR2    DEFAULT NULL
           ,p_trx_num                      IN VARCHAR2    DEFAULT NULL
           ,p_release_num                  IN NUMBER      DEFAULT NULL
           ,p_from_date                    IN DATE        DEFAULT NULL
           ,p_max_output_rows              IN NUMBER      DEFAULT 20
           ,p_debug_mode                   IN VARCHAR2    DEFAULT 'Y')

IS

  l_revision                  VARCHAR2(25);
  l_date_char                 VARCHAR2(30);
  l_instance                  VARCHAR2(255);
  l_apps_version              VARCHAR2(255);
  l_host                      VARCHAR2(255);
  l_full_hostname             VARCHAR2(255);
  l_key                       VARCHAR2(255);
  l_system_function_var       VARCHAR2(2000);
  l_exists_val                VARCHAR2(2000);
  l_index                     NUMBER:=1;
  l_dbversion                 VARCHAR2(255);
  l_db_name                   VARCHAR2(255);
  l_step                      VARCHAR2(10);
  invalid_parameters EXCEPTION;
  invalid_escape EXCEPTION;

----------------------------------------------------------------
-- Analyzer-specific code: Validation Declarations            --
----------------------------------------------------------------
  l_doc_id         NUMBER;
  l_rel_id         NUMBER;
  l_trx_type       VARCHAR2(20);
  l_doc_subtype    VARCHAR2(25);
  l_preparer_id    NUMBER;
  l_agent_id       NUMBER;
  l_app_path_id    NUMBER;
  l_ame_trx_type   PO_DOCUMENT_TYPES_ALL.AME_TRANSACTION_TYPE%TYPE;
  l_ame_app_id     NUMBER;
  l_ame_po_appr_id NUMBER;
  l_ame_trx_id     NUMBER;
  l_ame_po         BOOLEAN := false;
  l_created_by     NUMBER;
  l_from_date      VARCHAR2(25);
  l_item_type      WF_ITEMS.ITEM_TYPE%TYPE;
  l_item_key       WF_ITEMS.ITEM_KEY%TYPE;
  l_run_date       VARCHAR2(30);
  l_date           DATE;
  l_counter        NUMBER;
  l_sql            VARCHAR2(4000);
  l_style_id       NUMBER; 
  l_vrows          NUMBER;

  l_ds_ame_app_id  NUMBER;
  l_ds_ame_trx_type  PO_DOCUMENT_TYPES_ALL.AME_TRANSACTION_TYPE%TYPE;

l_DBbanner   VARCHAR2(255);



FUNCTION get_DOCTYPESHORT
   return VARCHAR2 IS
BEGIN
debug('begin sql token function: DOCTYPESHORT');
  IF (l_trx_type = 'REQUISITION') THEN
      return 'REQ';
  ELSIF (l_trx_type = 'PA') THEN
      return 'PO';
  ELSE
      return l_trx_type;
  END IF;  
debug('end sql token function: DOCTYPESHORT');
END get_DOCTYPESHORT;



BEGIN

  l_step := '1';

  print_log(analyzer_title || ' Log File');
  print_log('***************************************************************');

  -- Create global hash for parameters. Numbers required for the output order
debug('begin populate parameters hash table');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Analysis Mode';
   g_parameters(g_parameters.LAST).pvalue := p_analysis_mode;
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Operating Unit';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_org_id,'NO_MASK');
   IF p_analysis_mode='SINGLE' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Document Type';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_trx_type,'NO_MASK');
   END IF;
   IF p_analysis_mode='SINGLE' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Document Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_trx_num,'NO_MASK');
   END IF;
   IF p_analysis_mode='SINGLE' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Release Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_release_num,'NO_MASK');
   END IF;
   IF p_analysis_mode='ALL' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Documents Created Since';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_from_date,'NO_MASK');
   END IF;
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Maximum Rows to Display';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_max_output_rows,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Debug Mode';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_debug_mode,'NO_MASK');
debug('end populate parameters hash table');



  l_key := g_parameters.first;
  -- Print parameters to the log
  print_log(chr(10)||'Parameter Values before validation:');
  print_log('---------------------------');

  FOR i IN 1..g_parameters.COUNT LOOP
    print_log(to_char(i) || '. ' || g_parameters(i).pname || ': ' || g_parameters(i).pvalue);
  END LOOP;
  print_log('---------------------------');

  BEGIN

    SELECT max(release_name) INTO l_apps_version
    FROM fnd_product_groups;

    begin
        -- Try to get version using new 19c method
        execute immediate 'select instance_name, host_name, version_full, sys_context(''USERENV'',''DB_NAME'') FROM v$instance'
            into l_instance, l_host, l_dbversion, l_db_name;
    exception when others then
        -- Get version using old method
        SELECT instance_name, host_name, version, sys_context('USERENV','DB_NAME')
        INTO l_instance, l_host, l_dbversion, l_db_name
        FROM v$instance;
    end;
    l_host := nvl(l_host, sys_context('USERENV','SERVER_HOST'));
    l_instance := nvl(l_instance, sys_context('USERENV','INSTANCE_NAME'));

  EXCEPTION WHEN OTHERS THEN
    print_log('Error in validate_parameters gathering instance information: '
      ||sqlerrm);
    raise;
  END;

  l_step := '2';
  BEGIN
    SELECT distinct domain
    INTO l_full_hostname
    FROM (SELECT db_domain AS domain
            FROM fnd_databases
          UNION ALL
          SELECT domain AS domain
          FROM fnd_nodes) domains WHERE domains.domain IS NOT NULL and rownum = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
          l_full_hostname := NULL;
        WHEN OTHERS    THEN
          print_log('Error in validate_parameters gathering instance information: '
          ||sqlerrm);
    END;

  l_step := '3';
-- Revision and date values can be populated by RCS
  l_revision := rtrim(replace('$Revision: 200.72  $','$',''));
  l_revision := ltrim(replace(l_revision,'Revision:',''));
  l_date_char := rtrim(replace('$Date: 2026/02/12 18:08:46 $','$',''));
  l_date_char := ltrim(replace(l_date_char,'Date:',''));
  l_date_char := to_char(to_date(l_date_char,'YYYY/MM/DD HH24:MI:SS'),'DD-MON-YYYY');

  l_step := '4';
-- Create global hash for mapping internal result codes (E, W, S, I) to user friendly result codes (error, warning, successful, information)
  g_result('E') := 'error';
  g_result('W') := 'warning';
  g_result('S') := 'success';
  g_result('I') := 'info';

  l_step := '5';
-- Create global hash for report information
-- Do not report host details (EBSAF-274); reverted by EBSAF-293
  g_rep_info('Host') := regexp_substr(l_host, '^[^.]+');
  -- the host name might already be fully qualified, need to check if it includes the domain before appending it
  IF (l_host LIKE '%.%') THEN
       g_rep_info('FullHost') := l_host;
  ELSE
       g_rep_info('FullHost') := l_host || '.' || l_full_hostname;
  END IF;
  l_step := '6';
  g_rep_info('Instance') := l_instance;
  g_rep_info('DB Name') := l_db_name;
  g_rep_info('DB Version') := l_dbversion;
  g_rep_info('Apps Version') := l_apps_version;
  g_rep_info('File Name') := 'po_approval_analyzer.sql';
  g_rep_info('File Version') := l_revision;
  g_rep_info('Framework Version') := RTRIM(g_framework_version, ' ');
  g_rep_info('Execution Date') := to_char(sysdate,'DD-MON-YYYY HH24:MI:SS');
  g_rep_info('Description') := ('The ' || analyzer_title || ' <a href="' || g_cmos_km_url || g_analyzer_doc_id||'" target="_blank">(Note '||g_analyzer_doc_id||')</a> is a self-service health-check script that reviews the overall footprint, analyzes current configurations and settings for the environment and provides feedback and recommendations on best practices. Your application data is not altered in any way when you run this analyzer.');

  l_step := '7';
  IF (g_is_concurrent) THEN
     populate_user_details();
  END IF;

  ------------------------------------------------------------------------------
  -- NOTE: Add code here for validation to the parameters of your diagnostic
  ------------------------------------------------------------------------------
  l_step := '8';


  g_max_output_rows := nvl(p_max_output_rows,20);
  g_debug_mode := nvl(p_debug_mode, 'Y');

debug('begin parameter validation: p_org_id');
IF p_org_id IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter Operating Unit is required.');
   raise invalid_parameters;
END IF;
IF p_org_id IS NOT NULL THEN
BEGIN
SELECT U.ORGANIZATION_ID
INTO l_exists_val
FROM HR_OPERATING_UNITS U
WHERE U.ORGANIZATION_ID = p_org_id
 AND mo_global.is_mo_init_done = 'N' or mo_global.check_access(U.ORGANIZATION_ID) = 'Y'
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: No operating unit organization ID specified.
The org_id parameter is mandatory.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_org_id failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_org_id');

debug('begin parameter validation: p_trx_type');
IF p_analysis_mode='SINGLE' THEN
IF p_trx_type IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter Document Type is required.');
   raise invalid_parameters;
END IF;
IF p_trx_type IS NOT NULL AND p_trx_type NOT IN ( 'PA','PO','RELEASE','REQUISITION') THEN
   print_error('INVALID ARGUMENT: Invalid trx type specified.
Value should be one of PA, PO, REQUISITION, or RELEASE.');
   raise invalid_parameters;
END IF;
END IF;
debug('end parameter validation: p_trx_type');

debug('begin parameter validation: p_trx_num');
IF p_analysis_mode='SINGLE' THEN
IF p_trx_num IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter Document Number is required.');
   raise invalid_parameters;
END IF;
IF p_trx_num IS NOT NULL THEN
BEGIN
SELECT SEGMENT1
INTO l_exists_val
FROM (SELECT SEGMENT1, ORG_ID FROM PO_HEADERS_ALL WHERE P_TRX_TYPE IN ('PO','PA','RELEASE') AND TYPE_LOOKUP_CODE NOT LIKE '%Q%' UNION ALL SELECT SEGMENT1, ORG_ID FROM PO_REQUISITION_HEADERS_ALL WHERE P_TRX_TYPE = 'REQUISITION')
WHERE SEGMENT1 = p_trx_num
 AND ORG_ID = p_org_id
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Invalid trx number specified.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_trx_num failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
END IF;
debug('end parameter validation: p_trx_num');

debug('begin parameter validation: p_release_num');
IF p_analysis_mode='SINGLE' THEN
IF p_release_num IS NOT NULL THEN
BEGIN
SELECT R.RELEASE_NUM
INTO l_exists_val
FROM PO_RELEASES_ALL R, PO_HEADERS_ALL H
WHERE R.RELEASE_NUM = p_release_num
 AND r.po_header_id = h.po_header_id 
and p_trx_type = 'RELEASE' 
and h.segment1 = p_trx_num
and h.org_id = p_org_id
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Invalid release, PO and org_id combination.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_release_num failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
END IF;
debug('end parameter validation: p_release_num');



debug('begin parameter validation: p_debug_mode');
IF p_debug_mode IS NOT NULL AND p_debug_mode NOT IN ( 'N','Y') THEN
   print_error('INVALID ARGUMENT: Debug Mode is invalid.  Valid values are Y or N');
   raise invalid_parameters;
END IF;
debug('end parameter validation: p_debug_mode');



-- Validation to verify analyzer is run on proper e-Business application version
-- In case validation at the beginning is updated/removed, adding validation here also so execution fails

  IF substr(l_apps_version,1,4) NOT IN ('12.0','12.1','12.2') THEN
    print_log('eBusiness Suite version = '||l_apps_version);
    print_log('ERROR: This Analyzer script is compatible for following version(s): 12.0,12.1,12.2');
    raise invalid_parameters;
  END IF;

-- .log enhancements (ER # 140)
  print_log(chr(10)||'Instance Information:');
  print_log('---------------------------');
  -- Do not report host details (EBSAF-274); reverted by EBSAF-293
  print_log('Host: '||g_rep_info('Host'));
  print_log('FullHost: '||g_rep_info('FullHost'));
  print_log('Instance: '||g_rep_info('Instance'));
  print_log('Database name: '||g_rep_info('DB Name'));
  print_log('Database version: '||g_rep_info('DB Version'));
  print_log('Applications version: '||g_rep_info('Apps Version'));
  print_log('Analyzer version: '||g_rep_info('File Version'));
  -- Report call details for troubleshooting (EBSAF-265)
  print_log('Calling method: '||g_rep_info('Calling From') );
  print_log('Calling module: '||g_rep_info('Calling Module') );
  print_log('---------------------------');

  -- Log session details (EBSAF-308)
  l_step := '8.5';
  print_log(chr(10)||'Session Information:');
  print_log('---------------------------');
  print_log('Language Code: '||sys_context('USERENV', 'LANG'));
  print_log('Region: '||sys_context('USERENV', 'NLS_TERRITORY'));
  print_log('Locale: '||sys_context('USERENV', 'LANGUAGE'));
  print_log('Date Format: '||sys_context('USERENV', 'NLS_DATE_FORMAT'));
  -- Get number characters
  select max(value) into l_system_function_var from v$parameter where name = 'nls_numeric_characters';
  print_log('Number Characters: '||l_system_function_var);
  -- Check for language installation
  begin
    execute immediate 'select max(installed_flag) from FND_LANGUAGES where language_code = sys_context(''USERENV'', ''LANG'')' into l_system_function_var;
    if (l_system_function_var is null or l_system_function_var not in ('B', 'I')) then
      print_log('WARNING: FND_LANGUAGES shows the session language is not installed.');
      print_log('Signatures relying on translation information may have incorrect results.');
    end if;
  exception when others then
    print_log('WARNING: Failed to check FND_LANGUAGES if session language is installed.');
  end;
  print_log('---------------------------');

  -- Verify escape character is set properly (EBSAF-265)
  l_step := '9';
  IF regexp_replace('Replace Test', '\s', '*') <>
     regexp_replace('Replace Test', chr(92) || 's', '*') THEN
    print_log('Invalid Escape:  Expected "' || chr(92) || 's' ||'" Received "\s"');
    print_log('Backslash character was not escaped properly during installation or execution.');
    raise invalid_escape;
  END IF;

  l_step := '10';
----------------------------------------------------------------
-- Analyzer-specific code: Additional Validation              --
----------------------------------------------------------------
debug('begin Additional Code: Additional Validation');
  l_step := '29';
  -- reset the document amounts global hash, as it might persist values from a previous analyzer run
  g_doc_amts.DELETE;


  l_step := '30';
  -- Check if customer has AME functionality for PO's
  IF l_apps_version like '12.1.3%' OR l_apps_version like '12.2%' THEN
    BEGIN
      SELECT count(*) INTO l_counter
      FROM dba_tab_columns
      WHERE table_name = 'PO_HEADERS_ALL'
      AND   column_name = 'AME_APPROVAL_ID';
    EXCEPTION WHEN OTHERS THEN
      l_counter := 0;
    END;
    IF l_counter > 0 THEN
      l_ame_po := true;
--      IF p_trx_type = 'PO' THEN
--        g_use_ame := true;
--      END IF;
    END IF;
  END IF;

-----debug----
--IF g_use_ame
--  THEN g_ame := 'Y';
--  ELSE  g_ame := 'N';
--END IF;
--print_log('101  AME: Retrieving the ame_approval_id: '||l_ame_po_appr_id||', ame_trx_type: '||l_ame_trx_type||' and style_id --'||l_style_id||', g_ame: '||g_ame);
---------------

  l_step := '40';
  IF (p_release_num is not null AND
      (p_trx_type <> 'RELEASE' OR p_trx_num is null)) OR
     ((p_release_num is null OR p_trx_num is null) AND
      p_trx_type = 'RELEASE') THEN
    print_error('Invalid combination. For a release the transaction type '||
      'should be RELEASE and the release number and PO number '||
      'must both be provided');
    raise invalid_parameters;
  END IF;

  l_step := '50';
  IF p_release_num is not null THEN
    l_step := '60';
    BEGIN
      SELECT h.po_header_id, r.po_release_id, r.release_type,
             r.wf_item_type, r.wf_item_key, r.created_by, h.style_id, r.agent_id
      INTO   l_doc_id, l_rel_id, l_doc_subtype,
             l_item_type, l_item_key, l_created_by, l_style_id, l_agent_id
      FROM   po_headers_all h, po_releases_all r
      WHERE  h.segment1 = p_trx_num
      AND    h.org_id = p_org_id
      AND    r.org_id = h.org_id
      AND    r.po_header_id = h.po_header_id
      AND    r.release_num = p_release_num;
    EXCEPTION WHEN NO_DATA_FOUND THEN
      print_error('Invalid release, PO and org_id combination	');
      print_error('No release document exists for values '||
        to_char(p_release_num)||'/'||p_trx_num||'/'||to_char(p_org_id));
      raise invalid_parameters;
    END;
  ELSIF p_trx_num is not null THEN
    IF p_trx_type is null OR p_trx_type = 'ANY' THEN
      print_error('You must specify the org_id and transaction type when '||
        'trx_number is specified.');
      raise invalid_parameters;
    ELSIF p_trx_type IN ('PA','PO') THEN
      l_step := '70';
      BEGIN
        IF l_ame_po THEN
          l_step := '70.1';
          l_sql :=
            'SELECT po_header_id, type_lookup_code, created_by,
                    wf_item_type, wf_item_key,
                    ame_approval_id, ame_transaction_type, style_id, agent_id, NVL(global_agreement_flag, ''N'')
             FROM   po_headers_all
             WHERE  segment1 = :1
             AND    ((:2= ''PA'' AND
                      type_lookup_code IN (''BLANKET'',''CONTRACT'')) OR
                     (:3= ''PO'' AND
                      type_lookup_code IN (''STANDARD'',''PLANNED'')))
             AND    org_id = :4
             AND    rownum = 1';
          EXECUTE IMMEDIATE l_sql
            INTO l_doc_id, l_doc_subtype, l_created_by,
                 l_item_type, l_item_key,
                 l_ame_po_appr_id, l_ame_trx_type, l_style_id, l_agent_id, g_global_agreement
            USING IN p_trx_num, IN p_trx_type, IN p_trx_type, IN p_org_id;
            print_log('70  AME: Retrieving the ame_approval_id: '||l_ame_po_appr_id||', ame_trx_type: '||l_ame_trx_type||' and style_id '||l_style_id);

-----debug----
--IF g_use_ame
--  THEN g_ame := 'Y';
--  ELSE  g_ame := 'N';
--END IF;
--print_log('102  AME: Retrieving the ame_approval_id: '||l_ame_po_appr_id||', ame_trx_type: '||l_ame_trx_type||' and style_id --'||l_style_id||', g_ame: '||g_ame);
---------------

        ELSE
          l_step := '70.2';
          l_sql :=
            'SELECT po_header_id, type_lookup_code, created_by,
                    wf_item_type, wf_item_key
             FROM   po_headers_all
             WHERE  segment1 = :1
             AND    ((:2= ''PA'' AND
                      type_lookup_code IN (''BLANKET'',''CONTRACT'')) OR
                     (:3= ''PO'' AND
                      type_lookup_code IN (''STANDARD'',''PLANNED'')))
             AND    org_id = :4
             AND    rownum = 1';
          EXECUTE IMMEDIATE l_sql
            INTO l_doc_id, l_doc_subtype, l_created_by,
                 l_item_type, l_item_key
            USING IN p_trx_num, IN p_trx_type, IN p_trx_type, IN p_org_id;
            print_log('AME: ame_approval_id column is not included in the headers table');
        END IF;
      EXCEPTION WHEN NO_DATA_FOUND THEN
        print_error('Invalid transaction type, number, and org_id combination');
        print_error('No document exists for values '||p_trx_type||
          '/'||p_trx_num||'/'||to_char(p_org_id));
        raise invalid_parameters;
      END;
    ELSIF p_trx_type = 'REQUISITION' THEN
      l_step := '80';
      DECLARE
         l_req_query   VARCHAR2(1000);
      BEGIN
           IF (is_extended_req_table) THEN
            l_step := '82';
               l_req_query := 'SELECT requisition_header_id, type_lookup_code,
                                      created_by, wf_item_type, wf_item_key
                                 FROM po_requisition_headers_all
                                WHERE segment1 = ''' || p_trx_num || '''
                                  AND org_id = ' || p_org_id || '
                                  AND conformed_header_id is null';
           ELSE 
               l_req_query := 'SELECT requisition_header_id, type_lookup_code,
                                      created_by, wf_item_type, wf_item_key
                                 FROM po_requisition_headers_all
                                WHERE segment1 = ''' || p_trx_num || '''
                                  AND org_id = ' || p_org_id;
           END IF;
           EXECUTE IMMEDIATE l_req_query 
                        INTO l_doc_id, l_doc_subtype, l_created_by,
                             l_item_type, l_item_key;
      EXCEPTION WHEN NO_DATA_FOUND THEN
        print_error('Invalid transaction type, number, and org_id combination');
        print_error('No document exists for values '||p_trx_type||
          '/'||p_trx_num||'/'||to_char(p_org_id));
        raise invalid_parameters;
      WHEN OTHERS THEN
        print_error('Exception when trying to retrieve the requisition details: ' || SQLERRM);
        raise invalid_parameters;
      END;
    END IF;
  END IF;
  l_step := '85';

  IF p_trx_type IN ('PA','PO') AND
     l_doc_subtype IN ('CONTRACT','BLANKET') THEN
    l_trx_type := 'PA';
  ELSE
    l_trx_type := p_trx_type;
  END IF;

  l_step := '90';
  IF l_doc_id is not null THEN
  -- Get the preparer employee ID and approval path from actions
    BEGIN
      SELECT employee_id, approval_path_id
      INTO   l_preparer_id, l_app_path_id
      FROM po_action_history
      WHERE object_id = l_doc_id
      AND   object_type_code = l_trx_type
      AND   action_code = 'SUBMIT'
      AND   sequence_num = (
              SELECT max(sequence_num)
              FROM po_action_history
              WHERE object_id = l_doc_id
              AND   object_type_code = l_trx_type
              AND   action_code = 'SUBMIT');
    EXCEPTION 
    WHEN TOO_MANY_ROWS THEN
      print_error('Too many records found in table PO_ACTION_HISTORY for ' || l_trx_type || ' with id ' || l_doc_id || '!
     Could not determine the preparer and approval path correctly. The analyzer output might be incorrect.');     
    WHEN NO_DATA_FOUND THEN
      l_preparer_id := null;
    END;


    -- If not found use the created by on the document header
    l_step := '100';
    IF l_preparer_id is null THEN
      BEGIN
        SELECT employee_id INTO l_preparer_id
        FROM fnd_user
        WHERE user_id = l_created_by;
      EXCEPTION WHEN NO_DATA_FOUND THEN
        l_preparer_id := null;
      END;
    END IF;

    -- Get the approval method
    l_step := '110';
    BEGIN
      SELECT decode(sp.use_positions_flag,
               'Y', 'POSITION',
               'N', 'SUPERVISOR',
               null)
      INTO g_app_method
      FROM financials_system_params_all sp
      WHERE sp.org_id = p_org_id;
    EXCEPTION WHEN NO_DATA_FOUND THEN
      g_app_method := null;
    END;

    -- Get default approval path if not already populated
    l_step := '120';
    IF g_app_method = 'POSITION' AND l_app_path_id is null THEN
      BEGIN
        SELECT default_approval_path_id
        INTO   l_app_path_id
        FROM po_document_types_all
        WHERE org_id = p_org_id
        AND   document_type_code = l_trx_type
        AND   document_subtype = l_doc_subtype;
        print_log('Looking for default approval path id from po_document_types_all: '||l_app_path_id);
      EXCEPTION WHEN NO_DATA_FOUND THEN
        l_app_path_id := null;
      END;
    END IF;

    g_app_path_id := l_app_path_id;

    -- Check if AME is in use for PO and REQUISITION documents
    -- Get the AME application ID for signature queries
    l_step := '130';
--  IF g_use_ame <> true THEN
--    g_use_ame := false;
--  END IF;

-----debug----
--IF g_use_ame
--  THEN g_ame := 'Y';
--  ELSE  g_ame := 'N';
--END IF;
--print_log('103  AME: Retrieving the ame_approval_id: '||l_ame_po_appr_id||', ame_trx_type: '||l_ame_trx_type||' and style_id --'||l_style_id||', g_ame: '||g_ame);
---------------


    IF l_trx_type = 'REQUISITION' THEN
      BEGIN
        SELECT dt.ame_transaction_type, ca.application_id
        INTO l_ame_trx_type, l_ame_app_id
        FROM po_document_types_all dt,
             ame_calling_apps ca
        WHERE dt.org_id = p_org_id
        AND   dt.document_type_code = l_trx_type
        AND   dt.document_subtype = l_doc_subtype
        AND   ca.transaction_type_id = dt.ame_transaction_type
        AND   ca.fnd_application_id = 201
        AND   sysdate BETWEEN ca.start_date AND
                nvl(ca.end_date,sysdate);
      EXCEPTION WHEN NO_DATA_FOUND THEN
        print_log('AME: Could not find data in po_document_types_all for the transaction type and org id selected!');
        l_ame_trx_type := null;
      END;
                
      IF (l_ame_trx_type is not null) THEN
        g_use_ame := true;
        l_ame_trx_id := l_doc_id;
        print_log('AME: Transaction Type is defined as '||l_ame_trx_type||'. AME detected.');

-----debug----
--IF g_use_ame
--  THEN g_ame := 'Y';
--  ELSE  g_ame := 'N';
--END IF;
--print_log('104  AME: Retrieving the ame_approval_id: '||l_ame_po_appr_id||', ame_trx_type: '||l_ame_trx_type||' and style_id --'||l_style_id||', g_ame: '||g_ame);
---------------


      END IF;
    ELSIF (l_trx_type IN ('PA','PO')  ) THEN -- AND l_ame_po_appr_id is not null)
      --g_use_ame := true;
      l_ame_trx_id := l_ame_po_appr_id;


      l_step := '140';
      l_ds_ame_trx_type := null;
      l_ds_ame_app_id := null;

-----debug----
--IF g_use_ame
--  THEN g_ame := 'Y';
--  ELSE  g_ame := 'N';
--END IF;
--print_log('105  AME: Retrieving the ame_approval_id: '||l_ame_po_appr_id||', ame_trx_type: '||l_ame_trx_type||' and style_id --'||l_style_id||', g_ame: '||g_ame);
---------------


      IF l_style_id IS NOT NULL THEN
        BEGIN
-- added to capture when PO approval is AME enabled at document style
          -- add to check that column exists
          SELECT count(1) into l_vrows from dba_tab_columns where TABLE_NAME='PO_DOC_STYLE_HEADERS' and COLUMN_NAME ='AME_TRANSACTION_TYPE';
          IF l_vrows=1 THEN
            BEGIN
              SELECT ds.ame_transaction_type, ca.application_id
              INTO l_ds_ame_trx_type, l_ds_ame_app_id
              FROM po_doc_style_headers ds,
                   ame_calling_apps ca
              WHERE ds.style_id = NVL(l_style_id, 0)
              AND   ca.transaction_type_id = ds.ame_transaction_type
              AND   ca.fnd_application_id = 201
              AND   sysdate BETWEEN ca.start_date AND
                    nvl(ca.end_date,sysdate);

              l_ame_app_id := NVL(l_ame_app_id, l_ds_ame_app_id);
              l_ame_trx_type := NVL(l_ame_trx_type, l_ds_ame_trx_type);

              print_log('AME: Transaction Type is defined at PO Document STYLE '||l_style_id||' as '||l_ds_ame_trx_type||' and ID  as '||l_ds_ame_app_id||'. AME detected.');

              -----debug----
              IF g_use_ame
                THEN g_ame := 'Y';
                ELSE  g_ame := 'N';
              END IF;
              print_log('106  AME: Retrieving the ame_approval_id: '||l_ame_po_appr_id||', ame_trx_type: '||l_ame_trx_type||' and style_id '||l_style_id||', g_ame: '||g_ame);
              ---------------

              EXCEPTION WHEN NO_DATA_FOUND THEN
                print_log('AME: Could not find AME_TRANSACTION_TYPE in po_doc_style_headers for the style and org id specified on the selected PO header!');

            -----debug----
            --IF g_use_ame
            --  THEN g_ame := 'Y';
            --  ELSE  g_ame := 'N';
            --END IF;
            --print_log('107  AME: Retrieving the ame_approval_id: '||l_ame_po_appr_id||', ame_trx_type: '||l_ame_trx_type||' and style_id --'||l_style_id||', g_ame: '||g_ame);
            ---------------

            -- if AME was enabled at the time of PO creation but it is no longer used, we should not print AME information
            --          IF g_use_ame <> true THEN
             --           g_use_ame := false;
            --          END IF;
            END;
          END IF; --END IF l_vrows=1
        END;
       END IF;
-- end of doc style AME check and proceeding to AME Check at doc type which overrides any value at doc style


-----debug----
--IF g_use_ame
--  THEN g_ame := 'Y';
--  ELSE  g_ame := 'N';
--END IF;
--print_log('108  AME: Retrieving the ame_approval_id: '||l_ame_po_appr_id||', ame_trx_type: '||l_ame_trx_type||' and style_id --'||l_style_id||', g_ame: '||g_ame);
---------------


        l_step := '150';
        BEGIN
-- changed to capture the scenario when PO approval was enabled and then disabled for the same PO
          SELECT dt.ame_transaction_type, ca.application_id
          INTO l_ame_trx_type, l_ame_app_id
          FROM po_document_types_all dt,
               ame_calling_apps ca
          WHERE dt.org_id = p_org_id
          AND   dt.document_type_code = l_trx_type
          AND   dt.document_subtype = l_doc_subtype
          AND   ca.transaction_type_id = dt.ame_transaction_type
          AND   ca.fnd_application_id = 201
          AND   sysdate BETWEEN ca.start_date AND
                  nvl(ca.end_date,sysdate);
          print_log('AME: Transaction Type is defined as '||l_ame_trx_type||'. AME detected.');

          IF l_ame_app_id is not null AND l_ame_trx_type is not null THEN
             g_use_ame := true;
			 print_log('1091 g_use_ame true');
          END IF;

          IF l_ame_app_id is null AND l_ame_trx_type is null THEN
            BEGIN
              --l_ame_app_id := null; 
              IF g_use_ame <> true THEN
                 g_use_ame := false;
				 print_log('1092 g_use_ame false');

-----debug----
--IF g_use_ame
--  THEN g_ame := 'Y';
--  ELSE  g_ame := 'N';
--END IF;
--print_log('110  AME: Retrieving the ame_approval_id: '||l_ame_po_appr_id||', ame_trx_type: '||l_ame_trx_type||' and style_id --'||l_style_id||', g_ame: '||g_ame);
---------------

              END IF;
		     IF g_use_ame
		       THEN g_ame := 'Y';
			   ELSE g_ame := 'N';
		     END IF;
            END;
          END IF;


        EXCEPTION WHEN NO_DATA_FOUND THEN
          print_log('AME: Could not find data in po_document_types_all for the transaction type and org id selected!');
          -- if AME was enabled at the time of PO creation but it is no longer used at document type level nor at doc style level, we should not print AME information

-----debug----
IF g_use_ame
  THEN g_ame := 'Y';
  ELSE  g_ame := 'N';
END IF;
print_log('109  AME: Retrieving the ame_approval_id: '||l_ame_po_appr_id||', ame_trx_type: '||l_ame_trx_type||' and style_id '||l_style_id||', g_ame: '||g_ame);
---------------

        END;
      l_step := '160';
      print_log('Step 160: l_ame_app_id '||l_ame_app_id||', l_ame_trx_type '||l_ame_trx_type||', l_ds_ame_app_id '||l_ds_ame_app_id||', l_ds_ame_trx_type '||l_ame_trx_type||', g_ame: '||g_ame);

-----debug----
--IF g_use_ame
--  THEN g_ame := 'Y';
--  ELSE  g_ame := 'N';
--END IF;
--print_log('111  AME: Retrieving the ame_approval_id: '||l_ame_po_appr_id||', ame_trx_type: '||l_ame_trx_type||' and style_id --'||l_style_id||', g_ame: '||g_ame);
---------------


      IF l_ame_app_id is null AND l_ame_trx_type is null 
         AND l_ds_ame_app_id is not null AND l_ds_ame_trx_type is not null and p_trx_type <> 'REQUISITION' THEN
        BEGIN
          l_ame_app_id := l_ds_ame_app_id;
          l_ame_trx_type := l_ds_ame_trx_type;
          g_use_ame := true;

-----debug----
--IF g_use_ame
--  THEN g_ame := 'Y';
--  ELSE  g_ame := 'N';
--END IF;
--print_log('112  AME: Retrieving the ame_approval_id: '||l_ame_po_appr_id||', ame_trx_type: '||l_ame_trx_type||' and style_id --'||l_style_id||', g_ame: '||g_ame);
---------------

        END;
      END IF;


    END IF;
  END IF;

 -- AME not allowed for BLANKET without GLOBAL_AGREEMENT_FLAG = Y, nor for RELEASE nor PLANNED
  IF p_trx_type = 'RELEASE' or 
  (p_trx_type IN ('PA','PO') and 
        (l_doc_subtype = 'PLANNED' or 
               (l_doc_subtype = 'BLANKET' and g_global_agreement <> 'Y')
         )
   )
 THEN
    g_use_ame := false;

-----debug----
--IF g_use_ame
--  THEN g_ame := 'Y';
--  ELSE  g_ame := 'N';
--END IF;
--print_log('113  AME: Retrieving the ame_approval_id: '||l_ame_po_appr_id||', ame_trx_type: '||l_ame_trx_type||' and style_id --'||l_style_id||', g_ame: '||g_ame);
---------------


  END IF;

  -- verify the code level of potables.ldt - if below 120.0.12010000.7, the table does not include column AME_APPROVAL_ID
   IF compare_versions(max_file_version('potable.ldt'), '120.0.12010000.6') <= 0 THEN
      g_pre_12_1_3 := true;
   END IF;

   IF compare_versions(max_file_version('poreq.odf'), '120.31.12020000.3') >= 0 THEN
      g_include_clm := true;
   END IF;

-- If poreq.odf >= 120.31.12020000.15 then NOTIFY_REQUESTER_FLAG column is available in the table po_requisition_headers_all.  
-- IF poreq.odf < 120.31.12020000.15 then NOTIFY_REQUESTER_FLAG column is NOT available
   IF compare_versions(max_file_version('poreq.odf'), '120.31.12020000.14') > 0 THEN
      g_notify_req_flag := 'Column available';
   ELSE
     g_notify_req_flag := 'Column not available';
   END IF;

  -- set session language as US EN to avoid wfstat messages in other languages
   EXECUTE IMMEDIATE 'ALTER SESSION SET NLS_LANGUAGE=''AMERICAN''';   
  -- need to make sure the numeric format is ., otherwise the numeric conversion will not work
   EXECUTE IMMEDIATE 'ALTER SESSION SET NLS_NUMERIC_CHARACTERS = ".,"';

IF g_use_ame
  THEN g_ame := 'Y';
  ELSE  g_ame := 'N';
END IF;
print_log('115  AME: Retrieving the ame_approval_id: '||l_ame_po_appr_id||', ame_trx_type: '||l_ame_trx_type||' and style_id '||l_style_id||', g_ame: '||g_ame);

g_same := 'SAME';
g_instance := l_instance;
g_apps_version := l_apps_version;

--Accomodations for 19C DB
g_db_version :=  l_dbversion;

select CASE 
WHEN g_db_version > '18'                                                                                  
THEN 'banner_full'
Else 'banner'
END into l_DBbanner from dual where rownum=1;

g_DBbanner := l_DBbanner;
--Accomodations for 19C DBdebug('end Additional Code: Additional Validation for 19C DB');




    /* SEEDED EBS BANNER BEGIN */

    -- Premier Support Checks by priority
    select min(error_type) into l_system_function_var from (
        -- Database in Sustaining Support
        select 1 error_type from V$VERSION WHERE banner like '%11.2%' or banner like '%11.1%' or banner like '%10.%'
        union
        -- Application Version 11.5
        select 2 error_type from fnd_product_groups where release_name like '11.5%'
        union
        -- Application Version 12.1
        select 3 error_type from fnd_product_groups where release_name like '12.1%'
        union
        -- Database in Extended Support
        select 4 error_type from V$VERSION WHERE banner like '%12.1%'
        union
        -- Application Version 12.0
        select 5 error_type from fnd_product_groups where release_name like '12.0%'
        union
        -- Application Version 12.2.x outdated
        select 6 error_type from fnd_product_groups where release_name in ('12.2.0' , '12.2.1' , '12.2.2' , '12.2.3' , '12.2.4' , '12.2.5' , '12.2.6')
    );

    -- Set banner message by error type
    case l_system_function_var
        when 1 then
            -- Database in Sustaining Support
            g_banner_severity := 'W';
            g_banner_message := 'The database version running on this instance is in Sustaining Support. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp].<br>Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 2 then
            -- Application Version 11.5
            g_banner_severity := 'W';
            g_banner_message := 'Premier Support for the application version on this instance ended on November 2010. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp].<br> Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 3 then
            -- Application Version 12.1
            g_banner_severity := 'W';
            g_banner_message := 'Premier Support End for the application version on this instance is on December 2021. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp]. <br>Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 4 then
            -- Database in Extended Support
            g_banner_severity := 'W';
            g_banner_message := 'The database version running on this instance is in Extended Support. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp].<br>Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 5 then
            -- Application Version 12.0
            g_banner_severity := 'W';
            g_banner_message := 'Premier Support for the application version on this instance ended on January 2012. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp].<br>Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 6 then
           -- Application Version 12.2.7
           g_banner_severity := 'W';
           g_banner_message := '<b>Effective July 1, 2024, the E-Business Suite 12.2 Error Correction Baseline will be 12.2.7.</b><br>
<br>
<div><div style="display:inline-block; text-align:left; max-width:800px;">Updating the application version to release 12.2.7 or higher will ensure you have access to major product releases.<br>
Refer to:<ul>
<li>[1195034/KB696368] Oracle E-Business Suite Error Correction Support Policy</li>
<li><a href="https://blogs.oracle.com/ebstech/post/update-error-correction-baseline-for-ebs-122" target="_blank">Oracle E-Business Suite Technology Blog</a> Update: Error Correction Baseline for EBS 12.2</li>
</ul>
Customers running E-Business Suite products on the 12.2.3 - 12.2.6 release levels are encouraged to update to current code levels of those products before July 2024 so they can benefit from the simpler and smaller patches that will be available starting in July 2024.<br>
In the event a new issue is reported on a product at a code level below the baseline, Oracle Support will attempt to resolve the issue and engage Development if necessary. Development may determine that the issue can be resolved at the customer code level, or may determine that the only practical way to provide the fix is for the customer to apply the baseline (or later) code in the affected area, and provide the fix at that level.
</div></div>';
        else
            -- No banner required
            g_banner_message := null;
    end case;
    /* SEEDED EBS BANNER END */
debug('end Additional Code: Additional Validation');



  g_parameters.DELETE;

  -- Recreate global hash for parameters after validation (includes the modifiers)
debug('begin populate parameters hash table');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Analysis Mode';
   g_parameters(g_parameters.LAST).pvalue := p_analysis_mode;
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Operating Unit';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_org_id,'NO_MASK');
   IF p_analysis_mode='SINGLE' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Document Type';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_trx_type,'NO_MASK');
   END IF;
   IF p_analysis_mode='SINGLE' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Document Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_trx_num,'NO_MASK');
   END IF;
   IF p_analysis_mode='SINGLE' THEN 
