  print_log('---------------------------');

  -- Create global hash of SQL token values
debug('begin populate sql tokens hash table');
   g_sql_tokens('##$$REL$$##') := g_rep_info('Apps Version');
   g_masked_tokens('##$$REL$$##') := mask_text( g_sql_tokens('##$$REL$$##'), 'NO_MASK');
   g_sql_tokens('##$$DOCNUM$$##') := p_trx_num;
   g_masked_tokens('##$$DOCNUM$$##') := mask_text( g_sql_tokens('##$$DOCNUM$$##'), 'NO_MASK');
   g_sql_tokens('##$$TRXTP$$##') := l_trx_type;
   g_masked_tokens('##$$TRXTP$$##') := mask_text( g_sql_tokens('##$$TRXTP$$##'), 'NO_MASK');
   g_sql_tokens('##$$SUBTP$$##') := l_doc_subtype;
   g_masked_tokens('##$$SUBTP$$##') := mask_text( g_sql_tokens('##$$SUBTP$$##'), 'NO_MASK');
   g_sql_tokens('##$$ORGID$$##') := to_char(p_org_id);
   g_masked_tokens('##$$ORGID$$##') := mask_text( g_sql_tokens('##$$ORGID$$##'), 'NO_MASK');
   g_sql_tokens('##$$DOCID$$##') := nvl(to_char(l_doc_id),'NULL');
   g_masked_tokens('##$$DOCID$$##') := mask_text( g_sql_tokens('##$$DOCID$$##'), 'NO_MASK');
   g_sql_tokens('##$$RELID$$##') := nvl(to_char(l_rel_id),'NULL');
   g_masked_tokens('##$$RELID$$##') := mask_text( g_sql_tokens('##$$RELID$$##'), 'NO_MASK');
   g_sql_tokens('##$$PREPID$$##') := nvl(to_char(l_preparer_id),'NULL');
   g_masked_tokens('##$$PREPID$$##') := mask_text( g_sql_tokens('##$$PREPID$$##'), 'NO_MASK');
   g_sql_tokens('##$$FDATE$$##') := p_from_date;
   g_masked_tokens('##$$FDATE$$##') := mask_text( g_sql_tokens('##$$FDATE$$##'), 'NO_MASK');
   g_sql_tokens('##$$ITMTYPE$$##') := l_item_type;
   g_masked_tokens('##$$ITMTYPE$$##') := mask_text( g_sql_tokens('##$$ITMTYPE$$##'), 'NO_MASK');
   g_sql_tokens('##$$ITMKEY$$##') := l_item_key;
   g_masked_tokens('##$$ITMKEY$$##') := mask_text( g_sql_tokens('##$$ITMKEY$$##'), 'NO_MASK');
   g_sql_tokens('##$$APPATH$$##') := nvl(to_char(l_app_path_id),'NULL');
   g_masked_tokens('##$$APPATH$$##') := mask_text( g_sql_tokens('##$$APPATH$$##'), 'NO_MASK');
   g_sql_tokens('##$$AMETRXTP$$##') := l_ame_trx_type;
   g_masked_tokens('##$$AMETRXTP$$##') := mask_text( g_sql_tokens('##$$AMETRXTP$$##'), 'NO_MASK');
   g_sql_tokens('##$$AMEAPPID$$##') := nvl(to_char(l_ame_app_id),'NULL');
   g_masked_tokens('##$$AMEAPPID$$##') := mask_text( g_sql_tokens('##$$AMEAPPID$$##'), 'NO_MASK');
   g_sql_tokens('##$$AMETRXID$$##') := nvl(to_char(l_ame_trx_id),'NULL');
   g_masked_tokens('##$$AMETRXID$$##') := mask_text( g_sql_tokens('##$$AMETRXID$$##'), 'NO_MASK');
   g_sql_tokens('##$$DOCTYPESHORT$$##') := get_DOCTYPESHORT();
   l_system_function_var := null;
   g_masked_tokens('##$$DOCTYPESHORT$$##') := mask_text( g_sql_tokens('##$$DOCTYPESHORT$$##'), 'NO_MASK');
   g_sql_tokens('##$$STYLE_ID$$##') := nvl(l_style_id, 0);
   g_masked_tokens('##$$STYLE_ID$$##') := mask_text( g_sql_tokens('##$$STYLE_ID$$##'), 'NO_MASK');
   g_sql_tokens('##$$AGENTID$$##') := nvl(to_char(l_agent_id),'NULL');
   g_masked_tokens('##$$AGENTID$$##') := mask_text( g_sql_tokens('##$$AGENTID$$##'), 'NO_MASK');
   g_sql_tokens('##$$LINEID$$##') := null;
   g_masked_tokens('##$$LINEID$$##') := mask_text( g_sql_tokens('##$$LINEID$$##'), 'NO_MASK');
   g_sql_tokens('##$$PERZ_PARAM1$$##') := 'PO';
   g_masked_tokens('##$$PERZ_PARAM1$$##') := mask_text( g_sql_tokens('##$$PERZ_PARAM1$$##'), 'NO_MASK');
   g_sql_tokens('##$$PERZ_PARAM4$$##') := 'null';
   g_masked_tokens('##$$PERZ_PARAM4$$##') := mask_text( g_sql_tokens('##$$PERZ_PARAM4$$##'), 'NO_MASK');
   g_sql_tokens('##$$PERZ_PARAM2$$##') := 'FND/WF';
   g_masked_tokens('##$$PERZ_PARAM2$$##') := mask_text( g_sql_tokens('##$$PERZ_PARAM2$$##'), 'NO_MASK');
   g_sql_tokens('##$$PERZ_PARAM3$$##') := 'null';
   g_masked_tokens('##$$PERZ_PARAM3$$##') := mask_text( g_sql_tokens('##$$PERZ_PARAM3$$##'), 'NO_MASK');
   g_sql_tokens('##$$PERZ_PARAM5$$##') := 'null';
   g_masked_tokens('##$$PERZ_PARAM5$$##') := mask_text( g_sql_tokens('##$$PERZ_PARAM5$$##'), 'NO_MASK');
debug('end populate sql tokens hash table');



  l_key := g_masked_tokens.first;
  -- Print token values to the log

  -- if max rows param is not set and does not have a default, g_max_output_rows might end up being -1. We don't want that.
  IF (g_max_output_rows <= 0) THEN
     print_log ('Max rows was not set and there is no default value for it. Defaulting to 20.');
     g_max_output_rows := 20;
  ELSIF (g_max_output_rows > 100000) THEN
     print_log ('Max rows was set too high. Defaulting to 100000.');
     g_max_output_rows := 100000;
  END IF;

  l_step := '12';
  print_log('SQL Token Values');

  WHILE l_key IS NOT NULL LOOP
    -- Ensure tokens do not contain invalid characters (EBSAF-263)
    g_sql_tokens(l_key) := filter_html(g_sql_tokens(l_key), 'I', 'D' );
    g_masked_tokens(l_key) := filter_html(g_masked_tokens(l_key), 'I', 'D' );

    -- Allow tokens to be masked in log (EBSAF-275)
    print_log(l_key||': '|| g_masked_tokens(l_key));
    l_key := g_masked_tokens.next(l_key);
  END LOOP;

EXCEPTION
  WHEN INVALID_PARAMETERS THEN
    print_error_args('Invalid parameters provided. Process cannot continue.', l_step);
    raise;
  WHEN INVALID_ESCAPE THEN
    print_error('INVALID ESCAPE: Regular expression search results are incorrect.' ||
        ' Calling method "' || g_rep_info('Calling From') || '" module "' || g_rep_info('Calling Module') || '".' );
    raise;
  WHEN OTHERS THEN
    print_error_args('Error validating parameters: '||sqlerrm, l_step);
    raise;
END validate_parameters;


