  add_signature(
      p_sig_repo_id            => '18712',
      p_sig_id                 => 'WFSTAT_CHILD_WF_NOTIFICATIONS',
      p_sig_sql                => 'SELECT wn.notification_id nid, wn.context, wn.group_id, 
wn.status, wn.mail_status MAIL_STATUS, wn.message_type, wn.message_name, 
wn.access_key, wn.priority, 
wn.begin_date, wn.end_date, wn.due_date, 
wn.callback, wn.recipient_role, wn.responder, wn.original_recipient, fndu.employee_id, fndu.person_party_id, 
wn.from_user, wn.to_user,

(CASE
  WHEN (subject like '' Requisition % Change Request (%) for%'')
   THEN concat(REGEXP_SUBSTR(subject, '' Requisition (>?\d+|\w+) Change Request \(.+?\) for ''),''*****'')  
   ELSE (CASE WHEN (subject like ''FYI: Requisition % (%) changed/Cancel by%'')
              THEN concat(REGEXP_SUBSTR(subject, ''FYI\: Requisition (\d|\w)+? \(.+?\) changed\/Cancel by ''),''*****'')  
              ELSE 
              (CASE WHEN (subject like ''Change Requests from % for%'')
                    THEN concat(''Change Requests from ***** for'',REGEXP_SUBSTR(subject, ''\s\w+?\s\d+''))
                    ELSE
                    (CASE WHEN (subject like ''% Requisition % for % (%)'')
                          THEN concat(concat(REGEXP_SUBSTR(subject, ''(\w* Requisition \d+ for\s)''),''*****''), REGEXP_SUBSTR(subject, ''(\((\d+|,)+\.\d+?\s\w+?\)|\((\d+|\.)+\,\d+?\s\w+?\))''))
                          ELSE subject 
                    END)
              END)
        END)
END) subject

