      p_fail_condition         => '[MAIL_STATUS] in [FAILED,ERROR]',
      p_problem_descr          => 'The MAIL_STATUS is FAILED or ERROR for the subject notification',
      p_solution               => 'MAIL_STATUS = FAILED indicates the notification has been generated within the applications (record in wf_notifications) , but the notification is not delivered to email.  You may investigate possible issues with the Workflow Notification Mailer.  Whether ERROR or FAILED Mail Status, verify whether the mailer is up or down, and check if it should be restarted.  Consider using the Workflow Java Mailer Analyzer from [2901874/KB551591] to troubleshoot issues with the notification mailer.',
      p_success_msg            => 'Notifications for the combination of Item Type / Item Key (if any)',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
