debug('begin add_signature: AGIS_WF_ERROR_PROCESS_ACTIVITY_STATUSES');
   l_info('##MASK##ASSIGNED_USER'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '5824',
      p_sig_id                 => 'AGIS_WF_ERROR_PROCESS_ACTIVITY_STATUSES',
      p_sig_sql                => 'select  to_char(ias.begin_date,''DD-MON-RR HH24:MI:SS'') begin_date,
        ap.name||''/''||pa.instance_label Activity,
        ias.activity_status Status,
        ias.activity_result_code Result,
        ias.assigned_user assigned_user,
	ias.notification_id NID,
	ntf.status "Status"
from    wf_item_activity_statuses ias,
        wf_process_activities pa,
        wf_activities ac,
        wf_activities ap,
        wf_items i,
	wf_notifications ntf
where   ias.item_type = i.item_type
and     ias.item_key  = i.item_key
and     ias.process_activity    = pa.instance_id
and     pa.activity_name        = ac.name
and     pa.activity_item_type   = ac.item_type
and     pa.process_name         = ap.name
and     pa.process_item_type    = ap.item_type
and     pa.process_version      = ap.version
and     i.parent_item_type      = ''##$$FK3$$##''
and     i.parent_item_key       = ''##$$FK4$$##''
and     i.begin_date            >= ac.begin_date 
and     i.begin_date            < nvl(ac.end_date, i.begin_date+1)
and     ntf.notification_id(+)  = ias.notification_id
order by ias.begin_date, ias.execution_time',
      p_title                  => 'WFSTAT - Error Process Activity Statuses',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'No Error Process Activity Statuses found for the combination of Item Type / Item Key.',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: AGIS_WF_ERROR_PROCESS_ACTIVITY_STATUSES');



