debug('begin add_signature: POA Workflow Processes Involved Parent');
   l_info('##MASK##OWNER_ROLE'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '2293',
      p_sig_id                 => 'POA Workflow Processes Involved Parent',
      p_sig_sql                => 'SELECT  distinct 
            wfi.item_type,         
			wfi.item_key,
                             item_type "##$$FK3$$##", item_key "##$$FK4$$##",
			wfi.owner_role,
            wfi.begin_date, 
			wfi.end_date ,
            wf_fwkmon.getitemstatus(wfi.item_type, wfi.item_key, wfi.end_date, wfi.root_activity, wfi.root_activity_version) status			
	FROM    PO_CHANGE_REQUESTS poc,         
			WF_ITEMS wfi 
	WHERE   poc.document_type IN (''##$$DOCTYPESHORT$$##'') 
	AND     poc.document_num = ''##$$DOCNUM$$##''   
	AND     ( poc.wf_item_key = wfi.item_key 
	OR        poc.wf_item_key = wfi.parent_item_key ) 
	UNION ALL 
	SELECT  distinct ph.wf_item_type,         
			ph.wf_item_key, 
                             item_type "##$$FK3$$##", item_key "##$$FK4$$##",
			wfi.owner_role,
            wfi.begin_date, wfi.end_date, 
            wf_fwkmon.getitemstatus(wfi.item_type, wfi.item_key, wfi.end_date, wfi.root_activity, wfi.root_activity_version) status			
	FROM    PO_CHANGE_REQUESTS poc1,        
			PO_CHANGE_REQUESTS poc2,        
			PO_HEADERS_ALL ph,
			WF_ITEMS wfi 
	WHERE   poc1.document_header_id = poc2.ref_po_header_id 
	AND     nvl(poc1.po_release_id,-1) = nvl(poc2.ref_po_release_id,-1) 
	AND     poc2.document_num = ''##$$DOCNUM$$##''
	AND     poc2.document_type = ''##$$DOCTYPESHORT$$##'' 
	AND     poc1.document_type = ''PO'' 
	AND     ph.po_header_id = poc1.document_header_id 
	AND     ( poc1.wf_item_key = wfi.item_key 
	OR        poc1.wf_item_key = wfi.parent_item_key ) 
	UNION ALL 
	SELECT  distinct rlh.wf_item_type,          
			rlh.wf_item_key, 
                             item_type "##$$FK3$$##", item_key "##$$FK4$$##",
			wfi.owner_role,
            wfi.begin_date, wfi.end_date, 
            wf_fwkmon.getitemstatus(wfi.item_type, wfi.item_key, wfi.end_date, wfi.root_activity, wfi.root_activity_version) status						
	FROM    PO_CHANGE_REQUESTS poc1,         
			PO_CHANGE_REQUESTS poc2,         
			PO_RELEASES_ALL rlh,
			WF_ITEMS wfi 
	WHERE   poc1.document_header_id = poc2.ref_po_header_id 
	AND     nvl(poc1.po_release_id,-1) = nvl(poc2.ref_po_release_id,-1) 
	AND     poc2.document_num = ''##$$DOCNUM$$##'' 
	AND     poc2.document_type = ''##$$DOCTYPESHORT$$##''
	AND     poc1.document_type = ''RELEASE''
	AND     rlh.po_release_id = poc1.po_release_id
	AND     ( poc1.wf_item_key = wfi.item_key 
	OR        poc1.wf_item_key = wfi.parent_item_key )',
      p_title                  => 'Related Workflow Processes',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'This shows the Workflow Processes related to the pending Change Requests',
      p_solution               => '<ul>
   <li>No action is needed as this is only informational</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL('PO_WF_POCHANGE_WORKFLOWS'),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '27'
      );
   l_info.delete;
debug('end add_signature: POA Workflow Processes Involved Parent');



