debug('begin add_signature: POS_STUCK_CHANGE_REQUEST_PO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '5102',
      p_sig_id                 => 'POS_STUCK_CHANGE_REQUEST_PO',
      p_sig_sql                => 'SELECT CHANGE_REQUEST_GROUP_ID
, CHANGE_REQUEST_ID
, INITIATOR
, ACTION_TYPE
, REQUEST_REASON
, REQUEST_LEVEL
, REQUEST_STATUS
, DOCUMENT_TYPE
, DOCUMENT_HEADER_ID
, DOCUMENT_NUM
, DOCUMENT_REVISION_NUM
, PO_RELEASE_ID
, DOCUMENT_LINE_ID
, DOCUMENT_LINE_LOCATION_ID
, DOCUMENT_DISTRIBUTION_NUMBER
, VALIDATION_ERROR 
, WF_ITEM_TYPE
, WF_ITEM_KEY
, CHANGE_ACTIVE_FLAG
FROM   PO_CHANGE_REQUESTS
WHERE  REQUEST_STATUS IN (''BUYER_APP'',''WAIT_CANCEL_APP'')
       AND INITIATOR = ''SUPPLIER''
       AND DOCUMENT_TYPE = ''PO''
             AND DOCUMENT_HEADER_ID = ##$$DOCID$$##
       AND PO_RELEASE_ID IS NULL',
      p_title                  => 'Purchase Order Change Request Stuck',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The purchase order is stuck in Supplier Change Pending status after buyer approved the changes. ',
      p_solution               => 'see [1487301/KB784117] - Practical Guide To Troubleshoot Requisitions, PO''s or Releases Stuck In Change Request Process ',
      p_success_msg            => 'selecting specific columns instead of selecting them all',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
