debug('begin add_signature: POS_STUCK_CHANGE_REQUEST_REL');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '5103',
      p_sig_id                 => 'POS_STUCK_CHANGE_REQUEST_REL',
      p_sig_sql                => 'SELECT CHANGE_REQUEST_GROUP_ID
       , CHANGE_REQUEST_ID
       , INITIATOR
       , ACTION_TYPE
       , REQUEST_REASON
       , REQUEST_LEVEL
       , REQUEST_STATUS
       , DOCUMENT_TYPE
       , DOCUMENT_HEADER_ID
       , DOCUMENT_NUM
       , DOCUMENT_REVISION_NUM
       , PO_RELEASE_ID
       , DOCUMENT_LINE_ID
       , DOCUMENT_LINE_LOCATION_ID
       , DOCUMENT_DISTRIBUTION_NUMBER
       , VALIDATION_ERROR 
       , WF_ITEM_TYPE
       , WF_ITEM_KEY
       , CHANGE_ACTIVE_FLAG
FROM   PO_CHANGE_REQUESTS
WHERE  REQUEST_STATUS IN (''BUYER_APP'',''WAIT_CANCEL_APP'')
       AND INITIATOR = ''SUPPLIER''
       AND DOCUMENT_TYPE = ''RELEASE''
       AND DOCUMENT_HEADER_ID = ##$$DOCID$$##
AND PO_RELEASE_ID like NVL(''##$$RELID$$##'',''%'')',
      p_title                  => 'Purchase Order Releases Change Request Stuck',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The purchase order release(s) are stuck in Supplier Change Pending status after buyer approved the changes. ',
      p_solution               => 'see [1487301/KB784117] - Practical Guide To Troubleshoot Requisitions, PO''s or Releases Stuck In Change Request Process ',
      p_success_msg            => 'The are no purchase order release(s) stuck in Supplier Change Pending status after buyer approved the changes. ',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '10'
      );
   l_info.delete;
debug('end add_signature: POS_STUCK_CHANGE_REQUEST_REL');



