debug('begin add_signature: WFSTAT_ITEM_ATTRIBUTE_VALUES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '2205',
      p_sig_id                 => 'WFSTAT_ITEM_ATTRIBUTE_VALUES',
      p_sig_sql                => 'select attr_name, value_type, value,
(CASE
WHEN (attr_name in (''SYSADMIN_ERROR_MSG'',''ERROR_MESSAGE'',''ERROR_STACK'',''ERROR_RESULT_CODE'',''AME_EXCEPTION'',''ONLINE_REPORT_ID'',''ONLINE_REPORT_TEXT'',''PLSQL_ERROR_MSG'') and value is not null)
THEN ''Warning''
ELSE ''''
END) Attention
from
--added above 14APR23 to highlight errors
(
SELECT wiav.name attr_name,
           wia.type value_type,
           nvl(
            (CASE 
                WHEN (wiav.name like ''%EMAIL_ADD%'' or wiav.name like ''%DISP%NAME%'' or wiav.name like ''%USER_NAME%'' 
                      or wiav.name like ''PO_WF_EMAIL_PERFORMER%'' or wiav.name like ''%USERNAME%'') 
                   THEN rpad(substr(wiav.text_value, 1, ceil(length(wiav.text_value)*0.25) ), length(wiav.text_value), ''*'')
                ELSE wiav.text_value
             END),
             nvl(to_char(wiav.number_value),
             to_char(wiav.date_value,''DD-MON-YYYY hh24:mi:ss''))) value
    FROM wf_item_attribute_values wiav,
         wf_item_attributes wia
    WHERE wiav.item_type = ''##$$ITMTYPE$$##''
    AND   wiav.item_key = ''##$$ITMKEY$$##''
    AND   wia.item_type(+) = wiav.item_type
    AND   wia.name(+) = wiav.name
    AND   wia.type(+) <> ''EVENT''
)
    ORDER BY attr_name',
      p_title                  => 'WFStat: Item Attribute Values',
      p_fail_condition         => '[ATTENTION] = [Warning]',
      p_problem_descr          => 'Attribute Values have unexpected values',
      p_solution               => 'If rows are returned, review the highlighted values which have unexpected values, as well as the other data values shown.<br>
if no rows are returned, this indicates that Workflow Item Attribute Values are not found for the combination of Item Type / Item Key.<br>',
      p_success_msg            => 'Item Attribute Values for the combination of Item Type / Item Key',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '14'
      );
   l_info.delete;
debug('end add_signature: WFSTAT_ITEM_ATTRIBUTE_VALUES');



debug('begin add_signature: EBS_MFG_APPRVL_AUTOCLOSE_FYI_WF_NOTIFICATION_MAILER');
