debug('begin add_signature: WFSTAT_NOTIFICATION_ACTIVITY');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1771',
      p_sig_id                 => 'WFSTAT_NOTIFICATION_ACTIVITY',
      p_sig_sql                => 'SELECT DISTINCT
    ACT.NAME             NOTIFICATION
  , ACT.RESULT_TYPE      RESULT
  , ACT.MESSAGE          MESSAGE
  , ACT.FUNCTION         PLSQL_FUNCTION
  , decode((select STATUS from all_objects
     where OBJECT_NAME = substr(ACT.FUNCTION,1,instr(ACT.FUNCTION,''.'')-1)
     and OWNER = ''APPS''
     and OBJECT_TYPE = ''PACKAGE BODY''),
    ''VALID'',   ''Y'',
    ''INVALID'', ''N'',
    ''X'') VAL
  , T.DISPLAY_NAME     DISPLAY_NAME 
from WF_ACTIVITIES               ACT
   , WF_ACTIVITIES_TL            T
   , WF_PROCESS_ACTIVITIES       PRO
   , WF_ITEM_ACTIVITY_STATUSES   STA
   , WF_ITEMS                    ITM
where  STA.NOTIFICATION_ID  = ##$$FK1$$##
   and ACT.ITEM_TYPE  = T.ITEM_TYPE
   and ACT.NAME      = T.NAME
   and ACT.VERSION   = T.VERSION
   and T.LANGUAGE  = userenv(''LANG'')
   and STA.PROCESS_ACTIVITY = PRO.INSTANCE_ID
   and ITM.ITEM_TYPE        = STA.ITEM_TYPE
   and ITM.ITEM_KEY         = STA.ITEM_KEY
   and ITM.BEGIN_DATE      >= ACT.BEGIN_DATE
   and ITM.BEGIN_DATE       < nvl(ACT.END_DATE,ITM.BEGIN_DATE+1)
   and ACT.NAME             = PRO.ACTIVITY_NAME
   and ACT.ITEM_TYPE        = PRO.ACTIVITY_ITEM_TYPE
   ',
      p_title                  => 'WFStat: Notification Activities',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Notification activities found for the combination of Item Type / Item Key',
      p_solution               => '',
      p_success_msg            => 'No Notification activities found for the combination of Item Type / Item Key',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: WFSTAT_NOTIFICATION_ACTIVITY');



