debug('begin add_signature: PO_ONLINE_REPORT_TXT_V1');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '9643',
      p_sig_id                 => 'PO_ONLINE_REPORT_TXT_V1',
      p_sig_sql                => 'SELECT ONLINE_REPORT_ID
,      SEQUENCE
,      TEXT_LINE 
,      LINE_NUM
,      SHIPMENT_NUM
,      DISTRIBUTION_NUM
,      TRANSACTION_LEVEL
,      QUANTITY
,      TRANSACTION_ID
,      TRANSACTION_DATE
,      TRANSACTION_TYPE
,      TRANSACTION_UOM
,      TRANSACTION_LOCATION
,      SEGMENT1
,      DISTRIBUTION_TYPE
 from po_online_report_text where online_report_id in 
    (select nvl(wiav.text_value, nvl(to_char(wiav.number_value),to_char(wiav.date_value,''DD-MON-YYYY hh24:mi:ss''))) 
       from    wf_item_attribute_values wiav,
               wf_item_attributes wia,
               po_headers_all poh
      where   wiav.name = ''ONLINE_REPORT_ID''
        AND   wiav.item_type = ''##$$ITMTYPE$$##''
        AND   wiav.item_key = ''##$$ITMKEY$$##''
        and   (wiav.number_value is not null or wiav.text_value is not null or  wiav.date_value is not null )
        and   wia.item_type(+)  = wiav.item_type
        and   wia.name(+)       = wiav.name
        and   wia.type(+)       <> ''EVENT''
        and   poh.wf_item_type = wiav.item_type
        and   poh.wf_item_key = wiav.item_key
        and   poh.authorization_status = ''REJECTED''
        and   poh.approved_flag = ''R'')
 and TEXT_LINE like ''%The accounting date is not in an open encumbrance period%''',
      p_title                  => 'Online Report Text',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The document has failed funds reservation following the approval of the document due to the error:
''The accounting date is not in an open encumbrance period''
',
      p_solution               => 'Please implement the solution from :
[1954018/KB619168] POAPPRV: Status Of PO Is Rejected After The Approval Of The Document',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: PO_ONLINE_REPORT_TXT_V1');



