debug('begin add_signature: WFSTAT_NOTIFICATIONS');
   l_info('##MASK##%RECIPIENT%'):= 'DISPLAY_FIRST_25_PCNT_WORD';
   l_info('##MASK##%RESPONDER%'):= 'DISPLAY_FIRST_25_PCNT_WORD';
   l_info('##MASK##%USER%'):= 'DISPLAY_FIRST_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1770',
      p_sig_id                 => 'WFSTAT_NOTIFICATIONS',
      p_sig_sql                => 'SELECT wn.notification_id nid,
           wn.notification_id "##$$FK1$$##",
           wn.context,
           wn.group_id,
           wn.status,
           wn.mail_status MAIL_STATUS,
           wn.message_type,
           wn.message_name,
           wn.access_key,
           wn.priority,
           wn.begin_date,
           wn.end_date,
           wn.due_date,
           wn.callback,
           wn.recipient_role,
           wn.responder,
           wn.original_recipient, NVL(fndu.employee_id,0) employee_id, NVL(fndu.person_party_id,0) person_party_id,
           wn.from_user,
           wn.to_user,

(CASE
  WHEN (subject like '' Requisition % Change Request (%) for%'')
   THEN concat(REGEXP_SUBSTR(subject, '' Requisition (>?\d+|\w+) Change Request \(.+?\) for ''),''*****'')  
   ELSE (CASE WHEN (subject like ''FYI: Requisition % (%) changed/Cancel by%'')
              THEN concat(REGEXP_SUBSTR(subject, ''FYI\: Requisition (\d|\w)+? \(.+?\) changed\/Cancel by ''),''*****'')  
              ELSE 
              (CASE WHEN (subject like ''Change Requests from % for%'')
                    THEN concat(''Change Requests from ***** for'',REGEXP_SUBSTR(subject, ''\s\w+?\s\d+''))
                    ELSE
                    (CASE WHEN (subject like ''% Requisition % for % (%)'')
                          THEN concat(concat(REGEXP_SUBSTR(subject, ''(\w* Requisition \d+ for\s)''),''*****''), REGEXP_SUBSTR(subject, ''(\((\d+|,)+\.\d+?\s\w+?\)|\((\d+|\.)+\,\d+?\s\w+?\))''))
                          ELSE subject 
                    END)
              END)
        END)
END) subject
           
    FROM wf_notifications wn,
         wf_item_activity_statuses wias, fnd_user fndu
WHERE fndu.user_name(+) = wias.assigned_user
   AND  wn.group_id = wias.notification_id
    AND   wias.item_type = ''##$$ITMTYPE$$##''
    AND   wias.item_key = ''##$$ITMKEY$$##''
',
      p_title                  => 'WFStat: Notifications',
      p_fail_condition         => '[MAIL_STATUS] in [FAILED,ERROR]',
      p_problem_descr          => 'The MAIL_STATUS is FAILED or ERROR for the subject notification',
      p_solution               => 'MAIL_STATUS = FAILED indicates the notification has been generated within the applications (record in wf_notifications) , but the notification is not delivered to email. You may investigate possible issues with the Workflow Notification Mailer. Whether ERROR or FAILED Mail Status, verify whether the mailer is up or down, and check if it should be restarted. Consider using the Workflow Java Mailer Analyzer from [2901874/KB551591] to troubleshoot issues with the notification mailer.',
      p_success_msg            => 'Notifications for the combination of Item Type / Item Key (if any)',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL('WFSTAT_NOTIFICATION_ACTIVITY','WFSTAT_NOTIFICATION_MESSAGES','PO_ONLINE_REPORT_TXT_V1','WFSTAT_NOTIFICATIONS_ATTRIBUTES','WF_NOTIFICATION_USER_COMMENTS','WF_NOTIFICATIONS_REQ_ASSIGNED_TO_YOU_12.2'),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '36'
      );
   l_info.delete;
debug('end add_signature: WFSTAT_NOTIFICATIONS');



debug('begin add_signature: WFSTAT_NOTE1268145.1_R12_1');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1777',
      p_sig_id                 => 'WFSTAT_NOTE1268145.1_R12_1',
      p_sig_sql                => 'SELECT ac.name||'' (''||ac.display_name||'')'' "Activity (Display Name)",
           ias.activity_result_code Result,
           ias.error_name ERROR_NAME,
           ias.error_message ERROR_MESSAGE,
           ias.error_stack ERROR_STACK
    FROM wf_item_activity_statuses ias,
         wf_process_activities pa,
         wf_activities_vl ac,
         wf_activities ap,
         wf_items i,
         wf_items j
WHERE    j.item_type = ''##$$ITMTYPE$$##''
    AND   j.item_key = ''##$$ITMKEY$$##''
    AND   ias.activity_status = ''ERROR''
    AND   ias.process_activity = pa.instance_id
    AND   pa.activity_name = ac.name
    AND   pa.activity_item_type = ac.item_type
    AND   pa.process_name = ap.name
    AND   pa.process_item_type = ap.item_type
    AND   pa.process_version = ap.version
    AND   i.parent_item_key = j.item_key
    AND   j.item_type = ''##$$ITMTYPE$$##''
    AND   i.item_key = ias.item_key
    AND   i.begin_date >= ac.begin_date
    AND   i.begin_date < nvl(ac.end_date, i.begin_date+1)
    AND   ias.error_stack like ''%Wf_Engine_Util.Function_Call(POR_AME_REQ_WF_PVT.Process_Beat_By_First%''
    AND   po_apprvl_analyzer_pkg.chk_pkg_body_version(''POR_AME_REQ_WF_PVT'', ''120.41.12010000.19'') < 0
    ORDER BY ias.begin_date, ias.execution_time',
      p_title                  => 'WFStat: Error ORA-06512',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The following error has occurred during Requisition approval: ORA-06512 in function call to POR_AME_REQ_WF_PVT.Process_Beat_By_First.',
      p_solution               => 'Follow the steps from [1268145/KB596182] to resolve this issue.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('N','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: WFSTAT_NOTE1268145.1_R12_1');



debug('begin add_signature: WFSTAT_Note1277855.1');
   l_info('##SHOW_SQL##'):= 'Y';
