    AND   ias.error_stack like ''%Wf_Engine_Util.Function_Call(PO_REQAPPROVAL_ACTION.RESERVE_DOC%''
    AND   ''12.1'' = substr(''##$$REL$$##'',1,4)
    AND  FND_IREP_LOADER_PRIVATE.compare_versions(substr(substr(als.text,regexp_instr(als.text,'' *[0-9]'',1,1,1)-1), 1, instr(substr(als.text,regexp_instr(als.text,'' *[0-9]'',1,1,1) - 1), '' '',1,1)-1), ''120.32.12010000.28'') = ''<'' 
    AND als.type = ''PACKAGE BODY''
