debug('begin add_signature: CONTRACT_TERMS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '2197',
      p_sig_id                 => 'CONTRACT_TERMS',
      p_sig_sql                => 'select segment1, CONTERMS_EXIST_FLAG cef
