       ,wf_process_activities pa
       ,wf_activities ac
       ,wf_activities ap
       ,wf_items i
       ,wf_item_attribute_values wiav
     where ias.item_type = ''POAPPRV''
       and ias.item_key = ''##$$ITMKEY$$##''
