debug('begin add_signature: Note1905401.1');
   l_info('##MASK##%USER%'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '2201',
      p_sig_id                 => 'Note1905401.1',
      p_sig_sql                => 'select  to_char(ias.begin_date,''DD-MON-RR HH24:MI:SS'') begin_date,
        to_char(ias.end_date,''DD-MON-RR HH24:MI:SS'') end_date,
        ap.name||''/''||pa.instance_label Activity,
        ias.activity_status Status,
        ias.activity_result_code Result,
        ias.assigned_user assigned_user,
        ias.notification_id NID,
        ntf.status "Status",
        ias.action,
        ias.performed_by
    from    wf_item_activity_statuses ias,
            wf_process_activities pa,
            wf_activities ac,
            wf_activities ap,
            wf_items i,
            wf_notifications ntf,
            po_requisition_headers_all prh
    where   ias.item_type = ''##$$ITMTYPE$$##''
    and     ias.item_key  = ''##$$ITMKEY$$##''
    and     ias.process_activity    = pa.instance_id
    and     pa.activity_name        = ac.name
    and     pa.activity_item_type   = ac.item_type
    and     pa.process_name         = ap.name
    and     pa.process_item_type    = ap.item_type
    and     pa.process_version      = ap.version
    and     i.item_type             = ''##$$ITMTYPE$$##''
    and     i.item_key              = ias.item_key
    and     i.begin_date            >= ac.begin_date
    and     i.begin_date            < nvl(ac.end_date, i.begin_date+1)
    and     ntf.notification_id(+)  = ias.notification_id
    and     prh.wf_item_type        = i.item_type
    and     prh.wf_item_key         = i.item_key
    and     prh.authorization_status = ''IN PROCESS''
    and     ap.name                 = ''AME_APPROVAL_LIST_ROUTING''
    and     ias.activity_status     = ''NOTIFIED''
    and     ias.activity_result_code = ''#NULL''
    and    ((''12.1'' = substr(''##$$REL$$##'',1,4)
             and po_apprvl_analyzer_pkg.chk_pkg_body_version(''POR_AME_REQ_WF_PVT'', ''120.41.12010000.9'') >= 0
             and po_apprvl_analyzer_pkg.chk_pkg_body_version(''POR_AME_REQ_WF_PVT'', ''120.41.12010000.11'') < 0)
         or (''12.2'' = substr(''##$$REL$$##'',1,4)
             and po_apprvl_analyzer_pkg.chk_pkg_body_version(''POR_AME_REQ_WF_PVT'', ''120.77.12020000.8'') >= 0
             and po_apprvl_analyzer_pkg.chk_pkg_body_version(''POR_AME_REQ_WF_PVT'', ''120.77.12020000.13'') < 0))',
      p_title                  => 'WFStat: Requisition stuck in "IN PROCESS"',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'This requisition seems to be stuck in "IN PROCESS" status and the next approver might not have received the notification.',
      p_solution               => 'This seems to be a know code issue. Follow the steps from [1905401/KB757868] to resolve the error.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('N','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: Note1905401.1');



