debug('begin add_signature: WFSTAT_GREATER_AMOUNT');
   l_info('##MASK##%RECIPIENT%'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##MASK##%USER%'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##MASK##SUBJECT'):= 'DISPLAY_FIRST_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4577',
      p_sig_id                 => 'WFSTAT_GREATER_AMOUNT',
      p_sig_sql                => 'SELECT wn.notification_id nid,
           wn.notification_id "##$$FK1$$##",
           wn.context,
           wn.group_id,
           wn.status,
           wn.mail_status,
           wn.message_type,
           wn.message_name,
           wn.access_key,
           wn.priority,
           wn.begin_date,
           wn.end_date,
           wn.due_date,
           wn.callback,
           wn.recipient_role,
           wn.responder,
           wn.original_recipient,
           wn.from_user,
           wn.to_user,
           wn.subject
    FROM wf_notifications wn,
         wf_item_activity_statuses wias
    WHERE wn.group_id = wias.notification_id
    AND   wias.item_type = ''POAPPRV''
    AND   wias.item_key  = ''##$$ITMKEY$$##''
    AND   wn.subject like ''Unable To Approve Blanket Purchase Agreement''
    AND EXISTS  
        (SELECT 1
           FROM wf_item_attribute_values wiav,
                wf_item_attributes wia
          WHERE wiav.item_type = ''POAPPRV''
            AND   wiav.item_key = ''##$$ITMKEY$$##''
            AND   wia.item_type(+) = wiav.item_type
            AND   wia.name(+) = wiav.name
            AND   wia.type(+) <> ''EVENT''
            AND   wiav.text_value like ''Amount Released is more than the Amount Agreed'')',
      p_title                  => 'WFSTAT: Amount Issue',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Amount Released is more than the Amount Agreed',
      p_solution               => 'If you try to create a release against one of the BPAs using amount exceeding the agreed amount taking the approved released amount into consideration, the system will not allow this and will show an error message.

On the Purchase Orders screen, "Released" amount is the summation of all the Releases including Approved, Incomplete, In-process.

This is why the "Released" field in Purchase Orders screen is showing a larger amount. ',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: WFSTAT_GREATER_AMOUNT');



