debug('begin add_signature: WFSTAT_NOTE1268145.1_R12_0');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '7317',
      p_sig_id                 => 'WFSTAT_NOTE1268145.1_R12_0',
      p_sig_sql                => 'SELECT ac.name||'' (''||ac.display_name||'')'' "Activity (Display Name)",
           ias.activity_result_code Result,
           ias.error_name ERROR_NAME,
           ias.error_message ERROR_MESSAGE,
           ias.error_stack ERROR_STACK
    FROM wf_item_activity_statuses ias,
         wf_process_activities pa,
         wf_activities_vl ac,
         wf_activities ap,
         wf_items i,
         wf_items j
WHERE    j.item_type = ''##$$ITMTYPE$$##''
    AND   j.item_key = ''##$$ITMKEY$$##''
    AND   ias.activity_status = ''ERROR''
    AND   ias.process_activity = pa.instance_id
    AND   pa.activity_name = ac.name
    AND   pa.activity_item_type = ac.item_type
    AND   pa.process_name = ap.name
    AND   pa.process_item_type = ap.item_type
    AND   pa.process_version = ap.version
    AND   i.parent_item_key = j.item_key
    AND   j.item_type = ''##$$ITMTYPE$$##''
    AND   i.item_key = ias.item_key
    AND   i.begin_date >= ac.begin_date
    AND   i.begin_date < nvl(ac.end_date, i.begin_date+1)
    AND   ias.error_stack like ''%Wf_Engine_Util.Function_Call(POR_AME_REQ_WF_PVT.Process_Beat_By_First%''
    AND   po_apprvl_analyzer_pkg.chk_pkg_body_version(''POR_AME_REQ_WF_PVT'', ''120.39.12000000.9'') < 0
    ORDER BY ias.begin_date, ias.execution_time',
      p_title                  => 'WFStat: Error ORA-06512',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The following error has occurred during Requisition approval: ORA-06512 in function call to POR_AME_REQ_WF_PVT.Process_Beat_By_First.',
      p_solution               => 'Follow the steps from [1268145/KB596182] to resolve this issue.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('N','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: WFSTAT_NOTE1268145.1_R12_0');



