         wf_activities_vl ap,
         wf_items i,
         wf_notifications ntf
    WHERE ias.item_type = ''##$$ITMTYPE$$##''
    AND   ias.item_key = ''##$$ITMKEY$$##''
    AND   ias.process_activity = pa.instance_id
    AND   pa.activity_name = ac.name
    AND   pa.activity_item_type = ac.item_type
    AND   pa.process_name = ap.name
    AND   pa.process_item_type = ap.item_type
    AND   pa.process_version = ap.version
    AND   i.item_type = ''##$$ITMTYPE$$##''
    AND   i.item_key = ias.item_key
    AND   i.begin_date >= ac.begin_date
    AND   i.begin_date < nvl(ac.end_date, i.begin_date+1)
    AND   ntf.notification_id(+) = ias.notification_id
    AND (  
          (UPPER(pa.activity_name) like ''%XX%'' OR UPPER(ap.display_name) like ''%XX%'' OR UPPER(pa.instance_label) like ''%XX%'' OR UPPER(ac.display_name) like ''%XX%'')
          OR
          (UPPER(ap.name) like ''%XX%'' OR UPPER(ap.function) like ''%XX%'' OR UPPER(ac.name) like ''%XX%'' OR UPPER(ac.function) like ''%XX%'' )
        )    
ORDER BY ias.begin_date, ias.execution_time',
      p_title                  => 'Customized PO Approval Workflow Activities',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Customized PO workflow activities have been found (activities that include ''XX'' in their name).',
      p_solution               => 'This PO Approval Workflow has some activities customized. Please consider re-testing the issue with seeded(standard) PO Approval workflow.
Please review : 
Oracle Workflow Customization Policy Clarification [578466/KB340509]	
Global Customer Services Customization Guidelines [122452/KB163518]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: CUSTOMIZED_PO_WF_ACTIVITIES');



