debug('begin add_signature: PO_WF_1987601.1_ATTRIBUTE_FEDERAL_FLAG_DOES_NOT_EXIST_FOR_REQAPPRV');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '15568',
      p_sig_id                 => 'PO_WF_1987601.1_ATTRIBUTE_FEDERAL_FLAG_DOES_NOT_EXIST_FOR_REQAPPRV',
      p_sig_sql                => 'select distinct por.wf_item_type, por.wf_item_key, por.requisition_header_id, por.org_id, por.creation_date, por.last_update_date
from WF_ITEM_ATTRIBUTE_VALUES wiav,
po_requisition_headers_all por
where por.requisition_header_id = ##$$DOCID$$## and por.org_id = ##$$ORGID$$##
and por.authorization_status in (''PRE-APPROVED'',''IN PROCESS'',''INCOMPLETE'')
and por.wf_item_type = wiav.item_type
and por.wf_item_key = wiav.item_key
and por.wf_item_type = ''##$$ITMTYPE$$##''
and not exists (select ''existing FEDERAL_FLAG'' from WF_ITEM_ATTRIBUTE_VALUES wiav1
  where wiav1.item_type = wiav.item_type
  and wiav1.item_key = wiav.item_key
  and wiav1.name = ''FEDERAL_FLAG'')
order by por.requisition_header_id desc',
      p_title                  => 'Attribute FEDERAL_FLAG Does Not Exist for REQAPPRV',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The attribute FEDERAL_FLAG is missing for the requisition approval workflow.  This missing attribute resulted in the following error in the REQAPPRV requisition approval workflow when attempting to approve this Requisition.

   Error ''3103: Attribute ''FEDERAL_FLAG'' does not exist for item'' occurs on Requisition Approval

This error occurs on requisitions which were pending approval when the instance was upgraded to a later release (or a patch was applied which adds this attribute as a required attribute for Requisition Approvals).',
      p_solution               => 'Review [1987601/KB856719].  You have applied a patch that now requires this attribute FEDERAL_FLAG in requisition approval workflow, however the workflow for this requisition does not have that attribute.  This occurs for requisition approval which was already started but not completed (PRE-APPROVED, IN PROCESS, or INCOMPLETE) at the time a patch or upgrade was applied requiring this new attribute in the workflow.  Review the options given in  [1987601/KB856719].  If you require a datafix, you may request a datafix from Support through a Service Request.',
      p_success_msg            => 'The requisition did not encounter the issue described in [1987601/KB856719].',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: PO_WF_1987601.1_ATTRIBUTE_FEDERAL_FLAG_DOES_NOT_EXIST_FOR_REQAPPRV');



