debug('begin add_signature: EBS_MFG_PO_APPRVL_SYSADMIN_ERROR_MSG_ORA_28113_POLICY_PREDICATE_HAS_ERROR');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '27905',
      p_sig_id                 => 'EBS_MFG_PO_APPRVL_SYSADMIN_ERROR_MSG_ORA_28113_POLICY_PREDICATE_HAS_ERROR',
      p_sig_sql                => 'SELECT poreqdoc.document_id, poreqdoc.authorization_status, 
poreqdoc.wf_item_type, poreqdoc.wf_item_key,
           ac.name||'' (''||ac.display_name||'')'' "Activity (Display Name)", ias.process_activity,
           ias.activity_result_code Result,
           ias.error_name ERROR_NAME,
           ias.error_message ERROR_MESSAGE,
           ias.error_stack ERROR_STACK,
wiav.item_type, wiav.item_key, wiav.name attr_name, 
wia.type value_type, 
nvl( 
(CASE 
WHEN (wiav.name like ''%EMAIL_ADD%'' or wiav.name like ''%DISP%NAME%'' or wiav.name like ''%USER_NAME%'' 
or wiav.name like ''PO_WF_EMAIL_PERFORMER%'' or wiav.name like ''%USERNAME%'') 
THEN rpad(substr(wiav.text_value, 1, ceil(length(wiav.text_value)*0.25) ), length(wiav.text_value), ''*'') 
ELSE wiav.text_value 
END), 
nvl(to_char(wiav.number_value), 
to_char(wiav.date_value,''DD-MON-YYYY hh24:mi:ss''))) value 
FROM wf_item_attribute_values wiav, 
wf_item_attributes wia,
         wf_item_activity_statuses ias,
         wf_process_activities pa,
         wf_activities_vl ac,
         wf_activities ap,
         wf_items i,
(
select po_header_id document_id, wf_item_type, wf_item_key, authorization_status
from po_headers_all where authorization_status <> ''APPROVED'' 
and po_header_id = ##$$DOCID$$##
and ''PO'' = ''##$$DOCTYPESHORT$$##''
UNION ALL
select requisition_header_id document_id, wf_item_type, wf_item_key, authorization_status
from po_requisition_headers_all where authorization_status <> ''APPROVED'' 
and requisition_header_id = ##$$DOCID$$##
and ''REQ'' = ''##$$DOCTYPESHORT$$##''
) poreqdoc
WHERE 
ias.item_type = wiav.item_type
AND upper(ac.name) like ''%AUTHORITY%''
  AND   ias.item_key = wiav.item_key
--    AND   ias.activity_status = ''ERROR''
  AND   ias.process_activity = pa.instance_id
  AND   pa.activity_name = ac.name
  AND   pa.activity_item_type = ac.item_type
  AND   pa.process_name = ap.name
  AND   pa.process_item_type = ap.item_type
  AND   pa.process_version = ap.version
  AND   i.item_type = wiav.item_type
  AND   i.item_key = ias.item_key
  AND   i.begin_date >= ac.begin_date
  AND   i.begin_date < nvl(ac.end_date, i.begin_date+1)
    AND   ias.error_message = ''User-Defined Exception''
    AND   ias.error_stack like ''Wf_Engine_Util.Function_Call(PO_REQAPPROVAL_ACTION.VERIFY_AUTHORITY%''
AND wia.name(+) = wiav.name 
AND wia.item_type(+) = wiav.item_type 
AND wia.type(+) <> ''EVENT'' 
AND wiav.text_value like ''po.plsql.PO_DOCUMENT_ACTION_CHECK%.populate_session_gt:20:-28113ORA-28113: policy predicate has error - po.plsql.PO_DOCUMENT_ACTION_CHECK.authority_check:50:populate_session_gt not successful - po.plsql.PO_DOCUMENT_ACTION_PVT.do_action:110:unexpected error in action call%''
AND wiav.name = ''SYSADMIN_ERROR_MSG'' 
AND wiav.item_type = poreqdoc.wf_item_type 
AND wiav.item_key = poreqdoc.wf_item_key',
      p_title                  => 'Requisition or Purchase Order Approval fails with SYSADMIN_ERROR_MSG ... ORA-28113: policy predicate has error',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'PO or Requisition Approval fails and document is stuck "In Process" status with the following error:<br>
ERROR<br>
-----------------------<br>
Activity (Display Name) VERIFY_APPROVER_AUTHORITY (Does Approver Have Authority?)<br>
RESULT #EXCEPTION<br>
ERROR_NAME 1<br>
ERROR_MESSAGE User-Defined Exception<br>
ERROR_STACK Wf_Engine_Util.Function_Call(PO_REQAPPROVAL_ACTION.VERIFY_AUTHORITY, POAPPRV, 3700392-139176, 178042, RUN)<br>
<br>
Workflow SYSADMIN_ERROR_MSG attribute:<br>
po.plsql.PO_DOCUMENT_ACTION_CHECK.populate_session_gt:20:-28113ORA-28113: policy predicate has error - po.plsql.PO_DOCUMENT_ACTION_CHECK.authority_check:50:populate_session_gt not successful - po.plsql.PO_DOCUMENT_ACTION_PVT.do_action:110:unexpected error in action call<br>',
      p_solution               => 'Implement solution from :
Approval Fails at VERIFY_APPROVER_AUTHORITY Activity With SYSADMIN_ERROR_MSG "ORA-28113: policy predicate has error" [2808677/KB695560]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_PO_APPRVL_SYSADMIN_ERROR_MSG_ORA_28113_POLICY_PREDICATE_HAS_ERROR');



