      p_sig_sql                => '(SELECT agi.order_number,
           agi.approval_group_item_id "Item ID",
           decode(agi.parameter_name,
             ''OAM_group_id'', ''AME Group'',
             ''wf_roles_name'', ''WF Role'',
             agi.parameter_name) "Parameter Name",
           rpad(substr(agi.parameter, 1, ceil(length(agi.parameter)*0.6) ), length(agi.parameter), ''*'') parameter, agi.start_date, agi.end_date,
           ''NA'' name, 
           ''NA'' wfr_orig_system, 99999999 wfr_orig_system_id, ''NA'' wfr_status, ''NA'' wfr_start_date,  ''NA'' wfr_expiration_date
    FROM ame_approval_group_items agi
    WHERE agi.parameter_name <> ''wf_roles_name''
    AND agi.approval_group_id = ##$$FK1$$##
    AND   sysdate BETWEEN agi.start_date AND nvl(agi.end_date - (1/86400),sysdate)
UNION ALL
SELECT agi.order_number,
           agi.approval_group_item_id "Item ID",
           decode(agi.parameter_name,
             ''OAM_group_id'', ''AME Group'',
             ''wf_roles_name'', ''WF Role'',
             agi.parameter_name) "Parameter Name",
           rpad(substr(agi.parameter, 1, ceil(length(agi.parameter)*0.6) ), length(agi.parameter), ''*'') parameter, agi.start_date, agi.end_date,
           rpad(substr(wfr.name, 1, ceil(length(wfr.name)*0.60) ), length(wfr.name), ''*'') name,
           wfr.orig_system wfr_orig_system, wfr.orig_system_id wfr_orig_system_id, wfr.status wfr_status, to_char(wfr.start_date, ''DD-MON-YY'') wfr_start_date, to_char(wfr.expiration_date, ''DD-MON-YY'') wfr_expiration_date
    FROM ame_approval_group_items agi, wf_roles wfr
    WHERE agi.parameter_name = ''wf_roles_name'' and wfr.name(+) = agi.parameter
    AND agi.approval_group_id = ##$$FK1$$##
    AND   sysdate BETWEEN agi.start_date AND nvl(agi.end_date - (1/86400),sysdate)
UNION ALL
SELECT agi.order_number,
           agi.approval_group_item_id "Item ID",
