    where agi.approval_group_item_id = ##$$FK1$$## and aag.approval_group_id(+) = agi.parameter and agi.parameter_name = ''OAM_group_id'' 
    AND sysdate BETWEEN aag.start_date AND nvl(aag.end_date - (1/86400),sysdate)
    AND sysdate BETWEEN agi.start_date AND nvl(agi.end_date - (1/86400),sysdate)
