debug('begin add_signature: AME_RULE_ACTIONS');
   l_info('##MASK##APPR_GROUP_DESC'):= 'NO_MASK';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '2284',
      p_sig_id                 => 'AME_RULE_ACTIONS',
      p_sig_sql                => '
select action_id, approval_group_id, approval_group_id "##$$FK1$$##", appr_group_descr_prefix, 
rpad(substr(Appr_Group_Descr_suffix, 1, ceil(length(Appr_Group_Descr_suffix)*0.55) ), length(Appr_Group_Descr_suffix), ''*'') Appr_Group_Descr_suffix
from
(
select act.action_id, agr.approval_group_id, 
rpad(substr(act.descr, 1, ceil(length(act.descr)*0.75) ), length(act.descr), ''*'') Appr_Group_Descr_prefix,
substr(act.Descr,instr(act.Descr, ''Require approval from '',1,1)+22,length(act.Descr)) Appr_Group_Descr_suffix
from ame_approval_groups agr,
(SELECT ame_action_pkg.getDescription(a.action_id) "DESCR", a.action_id
    FROM ame_action_usages au,
         ame_actions a
    WHERE au.rule_id = 52241 --##$$FK1$$##
    AND   a.action_id = au.action_id
    AND   sysdate between a.start_date AND nvl(a.end_date - (1/86400),sysdate)
    AND   (sysdate between au.start_date AND nvl(au.end_date - (1/86400),sysdate) OR
           (au.start_date > sysdate AND
            (au.end_date is null OR au.end_date > au.start_date)))
) act
where substr(act.Descr,instr(act.Descr, ''from '',1,1)+5,length(act.Descr)) = agr.description
)',
