debug('begin add_signature: AME_LINE_RULE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '2285',
      p_sig_id                 => 'AME_LINE_RULE',
      p_sig_sql                => 'select * from
(SELECT ic.name item_class,
          decode(r.rule_type,
                 0, ''Combination'',
                 1, ''List Creation'',
                 2, ''List Creation Exception'',
                 3, ''List Modification'',
                 4, ''Substitution'',
                 5, ''Pre-list'',
                 6, ''Post-list'',
                 7, ''Production'',
           r.rule_type) "Rule Type",
           r.rule_id,
           r.description,
           r.rule_key,
           r.start_date,
           r.end_date,
           nvl(to_char(ru.priority),''Disabled'') "priority",
           decode(ru.approver_category,
             ''A'', ''Action'',
             ''F'', ''FYI'',
             ru.approver_category) "Approver Category"
    FROM ame_rules r,
         ame_rule_usages ru,
         (
           SELECT ic.name, ic.item_class_id,
                  icu.item_class_order_number, icu.item_class_id item_clsid
            FROM ame_item_classes ic,
                 ame_item_class_usages icu                 
            WHERE ic.item_class_id = icu.item_class_id
            AND   icu.application_id = ##$$AMEAPPID$$##
            AND   sysdate BETWEEN ic.start_date AND
                    nvl(ic.end_date - (1/86400),sysdate)
            AND   sysdate BETWEEN icu.start_date AND
                    nvl(icu.end_date - (1/86400),sysdate)
         ) ic
    WHERE r.rule_type BETWEEN 1 and 8
    AND   ic.item_class_id (+) = r.item_class_id
    AND   (r.rule_type IN (3, 4) OR
           ic.item_class_id is not null)
    AND   r.rule_id = ru.rule_id
    AND   ru.item_id =  ##$$AMEAPPID$$##
    AND   (sysdate between r.start_date AND nvl(r.end_date - (1/86400),sysdate) OR
           (r.start_date > sysdate AND
             (r.end_date is null OR r.end_date > r.start_date)))
    AND   (sysdate between ru.start_date AND nvl(ru.end_date - (1/86400),sysdate) OR
           (ru.start_date > sysdate AND
             (ru.end_date is null OR ru.end_date > ru.start_date)))
    ORDER BY ic.item_class_order_number,
    item_clsid,
    r.rule_type, 
    r.rule_id) rules
    where item_class = ''line item''',
      p_title                  => 'AME Line Item Rule',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Line Item Rule detected!',
      p_solution               => 'Oracle Purchasing does not support Line item Rules in AME. Please review the above rule and move the Rule to Header level.<br>
As a workaround, you may consider the following<br>
- Create a Header level rule that uses Line item conditions as described in [1474402/KB435063]<br>
- Create a custom attribute that uses a dynamic query as described in [960944/KB727313]<br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('N','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: AME_LINE_RULE');



