debug('begin add_signature: AME_SETUP_NON_UNIQUE_ON');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4709',
      p_sig_id                 => 'AME_SETUP_NON_UNIQUE_ON',
      p_sig_sql                => 'select ''Non unique Order Numbers for Approval Group Config :: '' || name "Issue with Approval Group", order_number, apgc.voting_regime, rel.release_name
  from apps.AME_APPROVAL_GROUPS apg
       ,apps.AME_APPROVAL_GROUP_CONFIG apgc, (select NVL(release_name,''< 12.1.3'') Release_name from fnd_product_groups where release_name like ''12.2.%'' or release_name = ''12.1.3'') rel
 where apg.approval_group_id = apgc.approval_group_id
   and apgc.application_id = ''##$$FK1$$##''
   and sysdate between apgc.start_date and nvl(apgc.end_date,sysdate + 1)
   and sysdate between apg.start_date and nvl(apg.end_date,sysdate + 1)  
   and order_number in (select order_number 
                           from apps.AME_APPROVAL_GROUP_CONFIG apgc
                          where sysdate between apgc.start_date and nvl(apgc.end_date,sysdate + 1)
                            and apgc.application_id = ''##$$FK1$$##''
                        group by order_number
                          having count(*) > 1)
   and (apgc.voting_regime = ''S''
        or
        rel.release_name = ''< 12.1.3'' ) -- parallelization not allowed for release < 12.1.3',
      p_title                  => 'Non unique Order Numbers for Approval Group Config',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The above approval group configs have non unique order numbers.',
      p_solution               => '<b>Approval Groups</b> have non-unique <b>Order Numbers</b> (intended for use with <b>Parallel</b> approval routing), however, you are <br>
a) using <b>Serial</b> voting regime (not compatible with non-unique Order Numbers)<br>
Action: Update the <b>Order Numbers</b> to be <b>unique</b> when using <b>Serial</b> voting regime<br>
<br>
or<br>
<br>
b) on an older release that does not allow <b>Parallel</b> approvals (so cannot use same <b>Order Numbers</b> for different approval groups)<br>
Action: Update the <b>Order Numbers</b> to be <b>unique</b> since <b>Serial</b> voting regime is the only option allowed for application release < 12.1.3<br>
<br>
Review the following documents which describe approval issues that can occur when using voting regime that is not compatible with the <b>Order Numbering</b> (unique vs non-unique)<br>
<br>
<b>REFERENCE</b><br>
[2632304/KB576450] Trying to Use Serial Mode With AME and Purchase Order Stuck in In Process Status After All Approvers Approve<br>
[550782/KB588735] AME Approvals Fail on ''You do not have the authority to approve this requisition''<br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: AME_SETUP_NON_UNIQUE_ON');



