debug('begin add_signature: AME_SETUP');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4592',
      p_sig_id                 => 'AME_SETUP',
      p_sig_sql                => 'select aca.application_id "##$$FK1$$##",
aca.application_name "Application Name"
from apps.ame_calling_apps aca
where sysdate < nvl(aca.end_date-(1/86400),sysdate+1)
and application_id = ##$$AMEAPPID$$## --in (-270,-269,-271,-272,-273,-274,-275,-275,-275,-276,-599,-598,-600,-767,-746)
and (exists 
    (select 1
    from apps.AME_CONFIG_VARS
    where application_id = aca.application_id
    and sysdate < nvl(end_date,sysdate + 1)
    and variable_name in (''allowAllApproverTypes'',''allowAllItemClassRules'',''allowFyiNotifications'',''productionFunctionality'')
    and variable_value not in (''no'',''none'')
    union
    select 1
    from apps.AME_CONFIG_VARS
    where nvl(application_id, 0) = 0
    and sysdate < nvl(end_date,sysdate + 1)
    and variable_name in (''allowAllApproverTypes'',''allowAllItemClassRules'',''allowFyiNotifications'',''productionFunctionality'')
    and variable_value not in (''no'',''none'')
    and not exists (select null from apps.AME_CONFIG_VARS B
    where application_id = aca.application_id
    and sysdate < nvl(B.end_date,sysdate + 1)
    and variable_name = B.variable_name))
    or exists
    (select 1
       from apps.AME_APPROVAL_GROUPS apg, apps.AME_APPROVAL_GROUP_CONFIG apgc
        where apg.approval_group_id = apgc.approval_group_id
        and apgc.application_id = aca.application_id
        and apgc.voting_regime not in (''S'',''O'')
        and sysdate between apgc.start_date and nvl(apgc.end_date,sysdate + 1)
        and sysdate between apg.start_date and nvl(apg.end_date,sysdate + 1))
    or exists
    (select 1
      from apps.AME_ACTION_TYPE_CONFIG atc
      ,apps.AME_ACTION_TYPES atyp
      where application_id = aca.application_id
      and voting_regime <> ''S''
      and sysdate between atc.start_date and nvl(atc.end_date,sysdate + 1)
      and sysdate between atyp.start_date and nvl(atyp.end_date,sysdate + 1)
      and atc.action_type_id = atyp.action_type_id)
    or exists
    (select 1
       from apps.AME_ACTION_TYPE_CONFIG atc
       ,apps.AME_ACTION_TYPES atyp
       ,apps.AME_ACTION_TYPE_USAGES atu
       where application_id = aca.application_id
       and sysdate between atu.start_date and nvl(atu.end_date,sysdate + 1)
       and sysdate between atc.start_date and nvl(atc.end_date,sysdate + 1)
       and sysdate between atyp.start_date and nvl(atyp.end_date,sysdate + 1)
       and atc.action_type_id = atyp.action_type_id
       and atu.action_type_id = atyp.action_type_id
       and (atu.rule_type, atc.order_number) in (select rule_type,order_number
       from apps.ame_action_type_config B,apps.ame_action_type_usages C
       where B.action_type_id = C.action_type_id
       and application_id = aca.application_id
       and sysdate between C.start_date and nvl(C.end_date,sysdate + 1)
       and sysdate between B.start_date and nvl(B.end_date,sysdate + 1)
       group by rule_type,order_number
       having count(*) > 1))
    or exists  
     (select 1
       from ame_item_classes itc
       where sysdate between itc.start_date and nvl(itc.end_date,sysdate+1)
       and itc.item_class_id in (select itu.item_class_id
       from ame_item_class_usages itu
       where itu.application_id = aca.application_id
       and sysdate between itu.start_date and nvl(itu.end_date,sysdate+1)
       and item_class_sublist_mode <> ''S''))
    or exists 
    (select ''Non unique Order Numbers for Approval Group Config :: '' || name " "
       from apps.AME_APPROVAL_GROUPS apg
       ,apps.AME_APPROVAL_GROUP_CONFIG apgc
       where apg.approval_group_id = apgc.approval_group_id
       and apgc.application_id = aca.application_id
       and sysdate between apgc.start_date and nvl(apgc.end_date,sysdate + 1)
       and sysdate between apg.start_date and nvl(apg.end_date,sysdate + 1)
       and order_number in (select order_number
       from apps.AME_APPROVAL_GROUP_CONFIG apgc
       where sysdate between apgc.start_date and nvl(apgc.end_date,sysdate + 1)
       and apgc.application_id = aca.application_id
       group by order_number
       having count(*) > 1))    
    or exists 
     (select ''Non unique Order Numbers for Items of Approval Group :: '' || name " "
        from apps.AME_APPROVAL_GROUPS apg
        where sysdate between apg.start_date and nvl(apg.end_date,sysdate + 1)
        and apg.approval_group_id in ( select apgi.approval_group_id
        from apps.AME_APPROVAL_GROUP_ITEMS apgi
        ,apps.AME_APPROVAL_GROUP_CONFIG apgc
        where sysdate between apgi.start_date and nvl(apgi.end_date,sysdate + 1)
        and sysdate between apgc.start_date and nvl(apgc.end_date,sysdate + 1)
        and apgc.application_id = aca.application_id
        and apgi.approval_group_id = apgc.approval_group_id
        group by apgi.approval_group_id,apgi.order_number
        having count(*) > 1 ))
    )',
      p_title                  => 'AME Setup',
      p_fail_condition         => 'NRS',
      p_problem_descr          => ' ',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('SUCCESS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL('AME_SETUP_NON_SERIAL_VR','AME_SETUP_NON_UNIQUE_OM','AME_SETUP_NS_OR_ON_VR','AME_SETUP_NON_UNIQUE_ON','AME_SETUP_NON_UNIQUE_ON_ITEMS','AME_SETUP_NON_SERIAL_SUBLIST_MODES'),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '28'
      );
   l_info.delete;
debug('end add_signature: AME_SETUP');



debug('begin add_signature: AME_EXCEPTION_LOG_DATA');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '7359',
      p_sig_id                 => 'AME_EXCEPTION_LOG_DATA',
      p_sig_sql                => 'SELECT LOG_ID, TRANSACTION_ID, PACKAGE_NAME, ROUTINE_NAME, EXCEPTION_NUMBER, EXCEPTION_STRING, SECURITY_GROUP_ID
FROM AME_EXCEPTIONS_LOG WHERE APPLICATION_ID = ''##$$AMEAPPID$$##'' AND TRANSACTION_ID = ''##$$AMETRXID$$##''
ORDER BY LOG_ID desc',
      p_title                  => 'AME Exception Log Data',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Log messages from AME_EXCEPTIONS_LOG ',
      p_solution               => '<p>Exceptions occurred in AME.  This usually indicates the AME setup is not correct or patching may be required.</p>
<p>Review the detailed exception message in EXCEPTION_STRING and research in Oracle Support / Knowledge to find possible solutions.</p>
<p>If you are using version 200.49 or higher of this analyzer, review the two "AME Test Workbench Output..." details shown in the "AME Information" tile of this analyzer output.  These reflect information for Real Transaction Test for this document.  They will show the Rule ID, Conditions, and Approval Groups, as well as the specific Approvers retrieved using your current AME setup.</p>
<p>You can then review, in this same AME Information tile, the AME Rules and AME Approval Groups for the Rule ID and Approval Group(s) identified.  Reviewing these setups in the context of the exception message, you may be able to determine when the setup is not working as expected, and make adjustments accordingly.</p>
</p></p>Review the following document for troubleshooting ideas</p>[1437183/KB627829] - AME : How to Diagnose Issues With the Default Approver List in Purchasing When Using Approvals Management</p></p>
