debug('begin add_signature: EBS_MFG_PO_APPRVL_AME_EXCEPTION_LOG_2790650_1_INVALID_APPROVER');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23592',
      p_sig_id                 => 'EBS_MFG_PO_APPRVL_AME_EXCEPTION_LOG_2790650_1_INVALID_APPROVER',
      p_sig_sql                => 'SELECT LOG_ID, TRANSACTION_ID, PACKAGE_NAME, ROUTINE_NAME, EXCEPTION_NUMBER, EXCEPTION_STRING, SECURITY_GROUP_ID
FROM AME_EXCEPTIONS_LOG 
WHERE 
(
(PACKAGE_NAME = ''ame_approver_type_pkg''  and ROUTINE_NAME = ''getWfRolesNameAndDisplayName'' and EXCEPTION_STRING like ''%The approver identified by the following parameters is invalid%'')
OR
(PACKAGE_NAME = ''ame_engine''  and ROUTINE_NAME = ''fetchRuntimeGroup'' and EXCEPTION_STRING like ''%An invalid approver has been encountered in ame_engine.fetchRuntimeGroup:Parallel Notification Approver Group for all PO. Please remove the invalid approver. Invalid approver originating system PER and originating system ID%'')
OR
(PACKAGE_NAME = ''ame_engine''  and ROUTINE_NAME = ''getRuntimeGroupMembers'' and EXCEPTION_STRING like ''%An invalid approver has been encountered in ame_engine.fetchRuntimeGroup:Parallel Notification Approver Group for all PO. Please remove the invalid approver. Invalid approver originating system PER and originating system ID%'')
)

and APPLICATION_ID = ##$$AMEAPPID$$##
and 
(
(''##$$DOCTYPESHORT$$##'' = ''REQ'' and TRANSACTION_ID = ''##$$DOCID$$##'')
or
(''##$$DOCTYPESHORT$$##'' = ''PO'' and TRANSACTION_ID = ''##$$AMETRXID$$##'')
)
ORDER BY LOG_ID desc',
      p_title                  => 'Invalid Approver at ame_engine.getRuntimeGroupMembers in AME Exception Log',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Log messages from AME_EXCEPTIONS_LOG  show Invalid Approver error occurred in call to ame_approver_type_pkg.getWfRolesNameAndDisplayName, ame_engine.fetchRuntimeGroup, and ame_engine.getRuntimeGroupMembers.',
      p_solution               => '<p>Review the following document for solution details for this issue:</p>
<p>[2790650/KB279236] Unable to Approve Purchase Requisition: Invalid Approver in AME Approver List Setup </p>',
      p_success_msg            => 'There is no AME exception like the one described in [2790650/KB279236].',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_PO_APPRVL_AME_EXCEPTION_LOG_2790650_1_INVALID_APPROVER');



