decode(fsav1.attribute_value, ''Y'', ''Yes'', ''N'', ''No'', fsav1.attribute_value) "Balancing Segment" , decode(fsav2.attribute_value, ''Y'', ''Yes'', ''N'', ''No'', fsav2.attribute_value ) "Cost Center Segment" , 
decode(fsav3.attribute_value, ''Y'', ''Yes'', ''N'', ''No'', fsav3.attribute_value ) "Natural Account Segment" , decode(fsav4.attribute_value, ''Y'', ''Yes'', ''N'', ''No'', fsav4.attribute_value ) "Intercompany Segment" , 
