from fnd_id_flex_structures fifs , fnd_id_flex_structures_tl fifst , fnd_id_flex_segments ifs , fnd_flex_value_sets ffvs , gl_ledgers gll , fnd_segment_attribute_values fsav1 , fnd_segment_attribute_values fsav2 , 
