from po_control_rules pcr, po_position_controls_all ppca, po_control_functions pcf,
per_all_assignments_f paaf, per_all_people_f papf, fnd_user fndu,
   (SELECT count(distinct ifs.segment_name) accountsegcount
    FROM fnd_id_flex_structures fifs , fnd_id_flex_structures_tl fifst , fnd_id_flex_segments ifs , fnd_flex_value_sets ffvs , gl_ledgers gll , fnd_segment_attribute_values fsav1 , 
