debug('begin add_signature: POA_APP_HIER_CHECK6');
   l_info('##MASK##%NAME%'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##MASK##EMAIL%'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '12648',
      p_sig_id                 => 'POA_APP_HIER_CHECK6',
      p_sig_sql                => 'SELECT
   name,
   display_name,
   notification_preference,
   email_address,
   status,
  to_char(start_date, ''DD-MON-RRRR'') start_date,
  to_char(expiration_date, ''DD-MON-RRRR'') expiration_date
FROM
