debug('begin add_signature: EBS_MFG_PO_APPRVL_HIER_CHECK9_EMP_VS_USER_EMAIL');
   l_info('##MASK##%EMAIL_ADDRESS'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##MASK##EMPLOYEE_NAME'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##MASK##USER_NAME'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '24580',
      p_sig_id                 => 'EBS_MFG_PO_APPRVL_HIER_CHECK9_EMP_VS_USER_EMAIL',
      p_sig_sql                => 'SELECT
   rownum num,
   fu.employee_id,
   p1.full_name employee_name,
   fu.user_id,
   fu.user_name,
   fu.email_address user_email_address,
   p1.email_address person_email_address,
   Decode(UPPER(fu.email_address), UPPER(p1.email_address), ''SAME'', ''DIFFERENT'') EMAIL,
  to_char(fu.start_date, ''DD-MON-RRRR'') user_start_date,
  to_char(p1.effective_start_date, ''DD-MON-RRRR'') effective_start_date,
  to_char(fu.end_date, ''DD-MON-RRRR'') user_end_date,
  to_char(p1.effective_end_date, ''DD-MON-RRRR'') effective_end_date
FROM
   fnd_user fu
   ,per_all_people_f p1      
WHERE
   fu.employee_id = ##$$FK1$$##
   AND p1.person_id = fu.employee_id
   AND nvl(p1.effective_start_date, sysdate-1) < sysdate
   AND nvl(p1.effective_END_date, sysdate+1) > sysdate     
   AND   trunc(sysdate) BETWEEN fu.start_date AND nvl(fu.end_date, sysdate+1)',
      p_title                  => 'Employee vs User - Email Address',
      p_fail_condition         => '[EMAIL]<>['||mask_text(g_same, nvl( upper(''), 'NO_MASK') )||']',
      p_problem_descr          => 'The Email Address for the Employee is different than the Email Address for the User.',
      p_solution               => 'Review the email address on the Employee record and the User record, and set them to the correct value.  Reference navigation steps in [1106106/KB706205] for checking the Employee record and the User record.
',
      p_success_msg            => 'Email Address of user is the same as the Email Address of the employee',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_PO_APPRVL_HIER_CHECK9_EMP_VS_USER_EMAIL');



debug('begin add_signature: EBS_MFG_PO_APPRVL_HIER_CHECK11');
   l_info('##MASK##%EMAIL%'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##MASK##%NAME%'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '24008',
      p_sig_id                 => 'EBS_MFG_PO_APPRVL_HIER_CHECK11',
      p_sig_sql                => 'SELECT
   rownum num,
   fu.employee_id,
   p1.person_id,
   p1.full_name employee_name,
   fu.user_id,
   fu.user_name,
   fu.email_address,
   fu.start_date,
   fu.end_date      
FROM
   fnd_user fu
   ,per_all_people_f p1      
WHERE
   fu.employee_id = ##$$FK1$$##
   AND fu.email_address <> ''nobody@localhost'' 
   AND fu.email_address like ''%@%''
   AND p1.email_address = fu.email_address 
   AND nvl(p1.effective_start_date, sysdate-1) < sysdate
   AND nvl(p1.effective_END_date, sysdate+1) > sysdate     
   AND   trunc(sysdate) BETWEEN fu.start_date AND nvl(fu.end_date, sysdate+1)
   order by email_address, employee_name, user_name
',
      p_title                  => 'Email Address Assigned to More Than One Employee or User',
      p_fail_condition         => 'RSGT1',
      p_problem_descr          => 'An approver in the approval list uses an email address that is assigned to more than one employee or user.',
      p_solution               => '<p>Review [2899091/KB239728] Purchase Orders Appproval via Email fails With Workflow Error at SET_FORWARD_TO_FROM_APPROVE Activity, which describes an approval error that can arise when the same email address is used by multiple approvers
<ul>
<li> Review the data here to see the employee_name + user_name combinations using the same email address</li>
<li>Adjust the employee or user setup to ensure this email address is assigned to only one user/employee depending on your business requirements</li>
</ul>
</p>',
      p_success_msg            => 'All approvers are using an email address that is distinct for their employee_name/user_name.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_PO_APPRVL_HIER_CHECK11');



debug('begin add_signature: POA_APP_POS_MULTIPLE_APPR_GROUPS_ASSIGNED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '16863',
      p_sig_id                 => 'POA_APP_POS_MULTIPLE_APPR_GROUPS_ASSIGNED',
      p_sig_sql                => 'SELECT distinct ''Position'' Type, pp.position_id ID, pp.name Name, pc.org_id, 
cg.control_group_name ApprovalGroup
    FROM po_position_controls_all pc,
         per_all_positions pp,
         po_control_groups_all cg,
         po_control_functions cf,
         po_control_rules cr
    WHERE pc.control_group_id = cg.control_group_id
    AND   cr.control_group_id = pc.control_group_id
    AND   pc.control_function_id = cf.control_function_id
    AND   pc.org_id = ##$$ORGID$$##
    AND   pp.position_id = pc.position_id
    AND   pc.position_id = TO_NUMBER(DECODE(''##$$FK2$$##'', '''', -3, NULL, -3, ''##$$FK2$$##''))
    AND   trunc(sysdate) BETWEEN pc.start_date AND nvl(pc.end_date,sysdate+1)
    AND   cf.document_type_code = ''##$$TRXTP$$##''
    AND   cf.document_subtype = ''##$$SUBTP$$##''
    AND   cf.enabled_flag = ''Y''
    AND   cg.enabled_flag = ''Y''
order by pp.name, pc.org_id',
      p_title                  => 'Multiple Approval Groups Assigned to Single Position',
      p_fail_condition         => 'RSGT1',
      p_problem_descr          => 'Multiple Approval Groups assigned to a single Position results in questionable Approval Routing and/or incomplete No Approver Found result',
      p_solution               => 'Review [374263/KB676948] for clarification and recommendations about assigning only one approval group per position',
      p_success_msg            => 'There are not multiple approval groups assigned to this position; only a single approval group is assigned to this position, as recommended in [374263/KB676948].',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: POA_APP_POS_MULTIPLE_APPR_GROUPS_ASSIGNED');



debug('begin add_signature: CHARGE ACCOUNT DIGITS-ACCOUNT RANGE LOW DIGITS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '8391',
      p_sig_id                 => 'CHARGE ACCOUNT DIGITS-ACCOUNT RANGE LOW DIGITS',
      p_sig_sql                => 'SELECT  
  distinct poh.po_header_id, poh.segment1, poh.org_id, l.line_num,
           ll.shipment_num,
           d.distribution_num,
            d.quantity_ordered,
(LENGTH(rtrim(cr.segment1_low))||''.''||
             LENGTH(rtrim(cr.segment2_low))||''.''||
              LENGTH(rtrim(cr.segment3_low))||''.''||
               LENGTH(rtrim(cr.segment4_low))||''.''||
                LENGTH(rtrim(cr.segment5_low))||''.''||
                 LENGTH(rtrim(cr.segment6_low))||''.''||
                  LENGTH(rtrim(cr.segment7_low))||''.''||
                   LENGTH(rtrim(cr.segment8_low))||''.''||
                    LENGTH(rtrim(cr.segment9_low))||''.''||
                     LENGTH(rtrim(cr.segment10_low))||''.''||
                      LENGTH(rtrim(cr.segment11_low))||''.''||
                       LENGTH(rtrim(cr.segment12_low)))nr_segm_range_low,  
(LENGTH(rtrim(g.segment1))||''.''||
LENGTH(rtrim(g.segment2))||''.''||
LENGTH(rtrim(g.segment3))||''.''||
LENGTH(rtrim(g.segment4))||''.''||
LENGTH(rtrim(g.segment5))||''.''||
LENGTH(rtrim(g.segment6))||''.''||
LENGTH(rtrim(g.segment7))||''.''||
LENGTH(rtrim(g.segment8))||''.''||
LENGTH(rtrim(g.segment9))||''.''||
LENGTH(rtrim(g.segment10))||''.''||
LENGTH(rtrim(g.segment11))||''.''||
LENGTH(rtrim(g.segment12))) nr_seg_charge_Account,
decode(LENGTH(rtrim(cr.segment1_low)),LENGTH(rtrim(g.segment1)), ''OK'',
''MISMATCHED # digits in Account Range Low vs Charge Account Segment1'')COMP_SEG1_LOW,
decode(LENGTH(rtrim(cr.segment2_low)),LENGTH(rtrim(g.segment2)), ''OK'',
''MISMATCHED # digits in Account Range Low vs Charge Account Segment2'')COMP_SEG2_LOW,
decode(LENGTH(rtrim(cr.segment3_low)),LENGTH(rtrim(g.segment3)), ''OK'',
''MISMATCHED # digits in Account Range Low vs Charge Account Segment3'')COMP_SEG3_LOW,
decode(LENGTH(rtrim(cr.segment4_low)),LENGTH(rtrim(g.segment4)), ''OK'',
''MISMATCHED # digits in Account Range Low vs Charge Account Segment4'')COMP_SEG4_LOW,
decode(LENGTH(rtrim(cr.segment5_low)),LENGTH(rtrim(g.segment5)), ''OK'',
''MISMATCHED # digits in Account Range Low vs Charge Account Segment5'')COMP_SEG5_LOW,
decode(LENGTH(rtrim(cr.segment6_low)),LENGTH(rtrim(g.segment6)), ''OK'',
''MISMATCHED # digits in Account Range Low vs Charge Account Segment6'')COMP_SEG6_LOW,
decode(LENGTH(rtrim(cr.segment7_low)),LENGTH(rtrim(g.segment7)), ''OK'',
''MISMATCHED # digits in Account Range Low vs Charge Account Segment7'')COMP_SEG7_LOW,
decode(LENGTH(rtrim(cr.segment8_low)),LENGTH(rtrim(g.segment8)), ''OK'',
''MISMATCHED # digits in Account Range Low vs Charge Account Segment8'')COMP_SEG8_LOW,
decode(LENGTH(rtrim(cr.segment9_low)),LENGTH(rtrim(g.segment9)), ''OK'',
''MISMATCHED # digits in Account Range Low vs Charge Account Segment9'')COMP_SEG9_LOW,
decode(LENGTH(rtrim(cr.segment10_low)),LENGTH(rtrim(g.segment10)), ''OK'',
''MISMATCHED # digits in Account Range Low vs Charge Account Segment10'')COMP_SEG10_LOW,
decode(LENGTH(rtrim(cr.segment11_low)),LENGTH(rtrim(g.segment11)), ''OK'',
''MISMATCHED # digits in Account Range Low vs Charge Account Segment11'')COMP_SEG11_LOW,
decode(LENGTH(rtrim(cr.segment12_low)),LENGTH(rtrim(g.segment12)), ''OK'',
''MISMATCHED # digits in Account Range Low vs Charge Account Segment12'')COMP_SEG12_LOW
    FROM po_distributions_all d,
    po_lines_all l,
     po_line_locations_all ll,
         gl_code_combinations g,
       po_headers_all poh,
         po_action_history ah,
             per_all_people_f p,
             per_all_assignments_f a,
              per_all_positions pos,
              po_position_controls_all pc,
                   po_control_rules cr,
                     po_control_groups_all cg,
                     po_control_functions cf
    WHERE 
      (
      LENGTH(rtrim(cr.segment1_high)) <> LENGTH(rtrim(g.segment1))
      OR LENGTH(rtrim(cr.segment2_low)) <> LENGTH(rtrim(g.segment2))
      OR LENGTH(rtrim(cr.segment3_low)) <> LENGTH(rtrim(g.segment3))
      OR LENGTH(rtrim(cr.segment4_low)) <> LENGTH(rtrim(g.segment4))
      OR LENGTH(rtrim(cr.segment5_low)) <> LENGTH(rtrim(g.segment5))
      OR LENGTH(rtrim(cr.segment6_low)) <> LENGTH(rtrim(g.segment6))
      OR LENGTH(rtrim(cr.segment7_low)) <> LENGTH(rtrim(g.segment7))
      OR LENGTH(rtrim(cr.segment8_low)) <> LENGTH(rtrim(g.segment8))
      OR LENGTH(rtrim(cr.segment9_low)) <> LENGTH(rtrim(g.segment9))
      OR LENGTH(rtrim(cr.segment10_low)) <> LENGTH(rtrim(g.segment10))
      OR LENGTH(rtrim(cr.segment11_low)) <> LENGTH(rtrim(g.segment11))
      OR LENGTH(rtrim(cr.segment12_low)) <> LENGTH(rtrim(g.segment12))
      )
    and cr.object_code=''ACCOUNT_RANGE''
    AND   cr.control_group_id = pc.control_group_id
    and cf.control_function_name in (''Approve Standard Purchase Orders'',''Approve Purchase Requisitions'',''Approve Internal Requisitions'')-----create a parameter field
    AND   cf.document_type_code = ''##$$DOCTYPESHORT$$##'' --in (''PO'',''PA'',''REQUISITION'',''RELEASE'')
    and   cf.control_function_id = pc.control_function_id
    AND cg.enabled_flag = ''Y''
    and   cg.control_group_id = pc.control_group_id 
    AND trunc(sysdate) BETWEEN pc.start_date AND nvl(pc.end_date,sysdate+1)
    and   pc.org_id = ##$$ORGID$$##
    AND   pc.position_id = ##$$FK2$$##
    AND   pc.position_id = pos.position_id
    AND pos.position_id (+) = a.position_id
    AND trunc(sysdate) BETWEEN a.effective_start_date AND a.effective_end_date
    AND   a.assignment_type in (''E'',
            decode(nvl(fnd_profile.value(''HR_TREAT_CWK_AS_EMP''), ''N''),
              ''Y'', ''C'',
              ''E''))
    AND   a.primary_flag = ''Y''
    AND   a.person_id = p.person_id
    AND trunc(sysdate) BETWEEN p.effective_start_date AND p.effective_end_date
    AND   (nvl(p.current_employee_flag, ''N'') = ''Y'' OR  nvl(p.current_npw_flag, ''N'') = ''Y'')
    AND   p.person_id (+) = ah.employee_id
    AND ah.object_type_code=''##$$DOCTYPESHORT$$##''--in (''PO'',''PA'','' REQUISITION'',''RELEASE'')
    AND   ah.object_id = poh.po_header_id
    AND g.code_combination_id(+) = d.code_combination_id
    AND ll.line_location_id = d.line_location_id
    AND l.po_line_id = d.po_line_id
    AND d.po_header_id = poh.po_header_id
    AND poh.authorization_status is NULL
    AND   poh.org_id = ##$$ORGID$$##
    AND   poh.po_header_id = ''##$$DOCID$$##''
    order by l.line_num',
      p_title                  => 'Compare Charge Account digits per account segment with Account Range Low digits per account segment',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Number of digits for each PO charge account segment is not the same as the number of digits per segment for account range low in Approval Group setup.',
      p_solution               => 'Number of digits per segment for PO charge account is not the same as the number of digits per segment for account range low in Approval Groups setup. Please apply the solution from the following note by specifying the correct number of digits per segment in account range low:

[1107338/KB737521] How to Verify that Document Charge Account and Approval Groups Setup is Valid in Order to Prevent no Approver Found Issues (Approval List not Generated)
',
      p_success_msg            => 'Number of digits per segment in account range low is the same as the number of digits per charge account segment in the PO charge account(s)',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: CHARGE ACCOUNT DIGITS-ACCOUNT RANGE LOW DIGITS');



