LENGTH(rtrim(g.segment11))||''.''||
LENGTH(rtrim(g.segment12))) nr_seg_charge_Account,
decode(LENGTH(rtrim(cr.segment1_high)),LENGTH(rtrim(g.segment1)), ''OK'',
''MISMATCHED # digits in Account Range High vs Charge Account Segment1'')COMP_SEGMENT1_HIGH,
decode(LENGTH(rtrim(cr.segment2_high)),LENGTH(rtrim(g.segment2)), ''OK'',
''MISMATCHED # digits in Account Range High vs Charge Account Segment2'')COMP_SEGMENT2_HIGH,
decode(LENGTH(rtrim(cr.segment3_high)),LENGTH(rtrim(g.segment3)), ''OK'',
''MISMATCHED # digits in Account Range High vs Charge Account Segment3'')COMP_SEGMENT3_HIGH,
decode(LENGTH(rtrim(cr.segment4_high)),LENGTH(rtrim(g.segment4)), ''OK'',
''MISMATCHED # digits in Account Range High vs Charge Account Segment4'')COMP_SEGMENT4_HIGH,
decode(LENGTH(rtrim(cr.segment5_high)),LENGTH(rtrim(g.segment5)), ''OK'',
''MISMATCHED # digits in Account Range High vs Charge Account Segment5'')COMP_SEGMENT5_HIGH,
decode(LENGTH(rtrim(cr.segment6_high)),LENGTH(rtrim(g.segment6)), ''OK'',
''MISMATCHED # digits in Account Range High vs Charge Account Segment6'')COMP_SEGMENT6_HIGH,
decode(LENGTH(rtrim(cr.segment7_high)),LENGTH(rtrim(g.segment7)), ''OK'',
''MISMATCHED # digits in Account Range High vs Charge Account Segment7'')COMP_SEGMENT7_HIGH,
decode(LENGTH(rtrim(cr.segment8_high)),LENGTH(rtrim(g.segment8)), ''OK'',
''MISMATCHED # digits in Account Range High vs Charge Account Segment8'')COMP_SEGMENT8_HIGH,
decode(LENGTH(rtrim(cr.segment9_high)),LENGTH(rtrim(g.segment9)), ''OK'',
''MISMATCHED # digits in Account Range High vs Charge Account Segment9'')COMP_SEGMENT9_HIGH,
decode(LENGTH(rtrim(cr.segment10_high)),LENGTH(rtrim(g.segment10)), ''OK'',
''MISMATCHED # digits in Account Range High vs Charge Account Segment10'')COMP_SEGMENT10_HIGH,
decode(LENGTH(rtrim(cr.segment11_high)),LENGTH(rtrim(g.segment11)), ''OK'',
''MISMATCHED # digits in Account Range High vs Charge Account Segment11'')COMP_SEGMENT11_HIGH,
decode(LENGTH(rtrim(cr.segment12_high)),LENGTH(rtrim(g.segment12)), ''OK'',
''MISMATCHED # digits in Account Range High vs Charge Account Segment12'')COMP_SEGMENT12_HIGH
    FROM po_distributions_all d,
    po_lines_all l,
     po_line_locations_all ll,
         gl_code_combinations g,
       po_headers_all poh,
         po_action_history ah,
             per_all_people_f p,
             per_all_assignments_f a,
              per_all_positions pos,
              po_position_controls_all pc,
                   po_control_rules cr,
                     po_control_groups_all cg,
                     po_control_functions cf
    WHERE 
      (
      LENGTH(rtrim(cr.segment1_high)) <> LENGTH(rtrim(g.segment1))
      OR LENGTH(rtrim(cr.segment2_high)) <> LENGTH(rtrim(g.segment2))
      OR LENGTH(rtrim(cr.segment3_high)) <> LENGTH(rtrim(g.segment3))
      OR LENGTH(rtrim(cr.segment4_high)) <> LENGTH(rtrim(g.segment4))
      OR LENGTH(rtrim(cr.segment5_high)) <> LENGTH(rtrim(g.segment5))
      OR LENGTH(rtrim(cr.segment6_high)) <> LENGTH(rtrim(g.segment6))
      OR LENGTH(rtrim(cr.segment7_high)) <> LENGTH(rtrim(g.segment7))
      OR LENGTH(rtrim(cr.segment8_high)) <> LENGTH(rtrim(g.segment8))
      OR LENGTH(rtrim(cr.segment9_high)) <> LENGTH(rtrim(g.segment9))
      OR LENGTH(rtrim(cr.segment10_high)) <> LENGTH(rtrim(g.segment10))
      OR LENGTH(rtrim(cr.segment11_high)) <> LENGTH(rtrim(g.segment11))
      OR LENGTH(rtrim(cr.segment12_high)) <> LENGTH(rtrim(g.segment12))
      )
    and cr.object_code=''ACCOUNT_RANGE''
    AND   cr.control_group_id = pc.control_group_id
    and cf.control_function_name in (''Approve Standard Purchase Orders'',''Approve Purchase Requisitions'',''Approve Internal Requisitions'')-----create a parameter field
    AND   cf.document_type_code = ''##$$DOCTYPESHORT$$##'' --in (''PO'',''PA'',''REQUISITION'',''RELEASE'')
    and   cf.control_function_id = pc.control_function_id
    AND cg.enabled_flag = ''Y''
    and   cg.control_group_id = pc.control_group_id 
    AND trunc(sysdate) BETWEEN pc.start_date AND nvl(pc.end_date,sysdate+1)
    and   pc.org_id = ##$$ORGID$$##
    AND   pc.position_id = ##$$FK2$$##
    AND   pc.position_id = pos.position_id
    AND pos.position_id (+) = a.position_id
    AND trunc(sysdate) BETWEEN a.effective_start_date AND a.effective_end_date
    AND   a.assignment_type in (''E'',
            decode(nvl(fnd_profile.value(''HR_TREAT_CWK_AS_EMP''), ''N''),
              ''Y'', ''C'',
              ''E''))
    AND   a.primary_flag = ''Y''
    AND   a.person_id = p.person_id
    AND trunc(sysdate) BETWEEN p.effective_start_date AND p.effective_end_date
    AND   (nvl(p.current_employee_flag, ''N'') = ''Y'' OR  nvl(p.current_npw_flag, ''N'') = ''Y'')
    AND   p.person_id (+) = ah.employee_id
    AND ah.object_type_code=''##$$DOCTYPESHORT$$##''--in (''PO'',''PA'','' REQUISITION'',''RELEASE'')
    AND   ah.object_id = poh.po_header_id
    AND g.code_combination_id(+) = d.code_combination_id
    AND ll.line_location_id = d.line_location_id
    AND l.po_line_id = d.po_line_id
    AND d.po_header_id = poh.po_header_id
    AND poh.authorization_status is NULL
    AND   poh.org_id = ##$$ORGID$$##
    AND   poh.po_header_id = ''##$$DOCID$$##''
    order by l.line_num',
      p_title                  => 'Compare Charge Account digits per account segment with Account Range High digits per account segment',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Number of digits for each PO charge account segment is not the same as the number of digits per segment for account range high in Approval Group setup.',
      p_solution               => 'Number of digits per segment for PO charge account is not the same as the number of digits per segment for account range high in Approval Groups setup.  Please apply the solution from the following note by specifying the correct number of digits per segment in account range high:

[1107338/KB737521] How to Verify that Document Charge Account and Approval Groups Setup is Valid in Order to Prevent no Approver Found Issues (Approval List not Generated)
',
      p_success_msg            => 'Number of digits per segment in account range high is the same as the number of digits per charge account segment in the PO charge account(s)',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: CHARGE ACCOUNT DIGITS-ACCOUNT RANGE HIGH DIGITS');



debug('begin add_signature: POA_APP_POS_HIERARCHY_MAIN');
   l_info('##MASK##FULL_NAME'):= 'DISPLAY_FIRST_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '2363',
      p_sig_id                 => 'POA_APP_POS_HIERARCHY_MAIN',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(eh, p, a, pos, poss) */
           p.full_name,
           eh.superior_id person_id,
           eh.superior_id "##$$FK1$$##",
           eh.superior_level,
           pos.position_id,
           pos.position_id "##$$FK2$$##",
           pos.name position_name,
           poss.name hierarchy_name,
           poss.position_structure_id hierarchy_id
    FROM --hr_employees_current_v ec,
         --po_employees_current_x ec,
         po_employee_hierarchies_all eh,
         per_all_people_f p,
         per_all_assignments_f a,
         per_all_positions pos,
         per_position_structures poss
    WHERE eh.position_structure_id = ##$$APPATH$$##
    AND   eh.employee_id = ##$$PREPID$$##
    AND   eh.business_group_id IN (
            SELECT fsp.business_group_id
            FROM financials_system_params_all fsp
            WHERE fsp.org_id = ##$$ORGID$$##)
    AND   p.person_id = eh.superior_id
    AND   (eh.superior_level > 0 OR
           eh.superior_id = eh.employee_id)
    AND   a.person_id = p.person_id
    AND   a.primary_flag = ''Y''
    AND   trunc(sysdate) BETWEEN p.effective_start_date AND
            p.effective_end_date
    AND   trunc(sysdate) BETWEEN a.effective_start_date AND
            a.effective_end_date
    AND   (nvl(p.current_employee_flag, ''N'') = ''Y'' OR
           nvl(p.current_npw_flag, ''N'') = ''Y'')
    AND   a.assignment_type in (''E'',
            decode(nvl(fnd_profile.value(''HR_TREAT_CWK_AS_EMP''), ''N''),
              ''Y'', ''C'',
              ''E''))
    AND   pos.position_id (+) = a.position_id
    AND   poss.position_structure_id (+) = eh.position_structure_id
   UNION
   SELECT /*+ ordered use_nl(poeh, cwk, a, ps, pos, poss) */
          cwk.full_name,
          poeh.superior_id person_id,
          poeh.superior_id "##$$FK1$$##",
          poeh.superior_level,
          pos.position_id,
          pos.position_id "##$$FK2$$##",
          pos.name position_name,
          poss.name hierarchy_name,
          poss.position_structure_id hierarchy_id
   FROM po_employee_hierarchies_all poeh,
        per_all_people_f cwk,
        per_all_assignments_f a,
        per_periods_of_service ps,
        per_all_positions pos,
        per_position_structures poss
   WHERE poeh.position_structure_id = ##$$APPATH$$##
   AND   poeh.employee_id = ##$$PREPID$$##
   AND   poeh.business_group_id IN (
           SELECT fsp.business_group_id
           FROM financials_system_params_all fsp
           WHERE fsp.org_id = ##$$ORGID$$##)
   AND   cwk.person_id = poeh.superior_id
   AND   (poeh.superior_level > 0 OR
          poeh.superior_id = poeh.employee_id)
   AND   nvl(fnd_profile.value(''HR_TREAT_CWK_AS_EMP''),''N'') = ''Y''
   AND   a.person_id = cwk.person_id
   AND   a.person_id = ps.person_id
   AND   a.assignment_type=''E''
   AND   cwk.employee_number is not null
   AND   a.period_of_service_id = ps.period_of_service_id
   AND   a.primary_flag = ''Y''
   AND   trunc(sysdate) BETWEEN cwk.effective_start_date AND
           cwk.effective_end_date
   AND   trunc(sysdate) BETWEEN a.effective_start_date AND
           a.effective_end_date
   AND    (ps.actual_termination_date >= trunc(sysdate) OR
           ps.actual_termination_date is null)
   AND   poss.position_structure_id (+) = poeh.position_structure_id
   AND   pos.position_id (+) = a.position_id
   UNION
   SELECT /*+ ordered use_nl(poeh, cwk, a, pp, pos, poss) */
          cwk.full_name,
          poeh.superior_id ,
          poeh.superior_id "##$$FK1$$##",
          poeh.superior_level,
          pos.position_id,
          pos.position_id "##$$FK2$$##",
          pos.name position_name,
          poss.name hierarchy_name,
          poss.position_structure_id hierarchy_id
   FROM per_all_people_f cwk,
        po_employee_hierarchies poeh,
        per_all_assignments_f a,
        per_periods_of_placement pp,
        per_all_positions pos,
        per_position_structures poss
   WHERE poeh.position_structure_id = ##$$APPATH$$##
   AND   poeh.employee_id = ##$$PREPID$$##
   AND   cwk.person_id = poeh.superior_id
   AND   (poeh.superior_level > 0 OR
          poeh.superior_id = poeh.employee_id)
   AND   nvl(fnd_profile.value(''HR_TREAT_CWK_AS_EMP''),''N'') = ''Y''
   AND   a.person_id = cwk.person_id
   AND   a.person_id = pp.person_id
   AND   a.assignment_type = ''C''
   AND   cwk.npw_number is not null
   AND   a.period_of_placement_date_start = pp.date_start
   AND   a.primary_flag = ''Y''
   AND   trunc(sysdate) BETWEEN cwk.effective_start_date AND
           cwk.effective_end_date
   AND   trunc(sysdate) BETWEEN a.effective_start_date AND
           a.effective_end_date
   AND   (pp.actual_termination_date >= trunc(sysdate) OR
          pp.actual_termination_date is null)
   AND   poss.position_structure_id (+) = poeh.position_structure_id
   AND   pos.position_id (+) = a.position_id
   ORDER BY 4, 1',
      p_title                  => 'Approving Employee',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'No approvers found for approval hierarchy ID: ##$$APPATH$$## (null ID value indicates no default approval hierarchy found)',
      p_solution               => 'If the approval hierarchy ID is NULL make sure the document type has a default approval path:
    <ol><li>Go to the document types form. (Navigation: PO Responsibility > Setup > Purchasing > Document Types)</li>
     <li>Query the specific document type i.e. Purchase Order</li>
     <li>Associate a default hierarchy.</li></ol>
<p>Anytime changes are made to the hierarchy or approval list is not built as expected, it is very important to run the Fill Employee Hierarchy process and ensure it completes without error.</p>
For setup information, please review the following document [134947/KB533560] - <i>Purchasing Setup of Approval Hierarchies</i>
<li>Also review recommended actions from [1106106/KB706205]</li>',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL('APP_HIER_CHECK2_V1','POA_APP_HIER_CHECK3_V1','POA_APP_HIER_CHECK4','POA_APP_HIER_CHECK5','POA_APP_HIER_CHECK6','EBS_MFG_PO_APPRVL_HIER_CHECK7_EMP_NO_USER','EBS_MFG_PO_APPRVL_HIER_CHECK8_EMP_NOT_ACTIVE','EBS_MFG_PO_APPRVL_HIER_CHECK9_EMP_VS_USER_EMAIL','EBS_MFG_PO_APPRVL_HIER_CHECK11','POA_APP_POS_MULTIPLE_APPR_GROUPS_ASSIGNED','CHARGE ACCOUNT DIGITS-ACCOUNT RANGE LOW DIGITS','CHARGE ACCOUNT DIGITS-ACCOUNT RANGE HIGH DIGITS'),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '90'
      );
   l_info.delete;
debug('end add_signature: POA_APP_POS_HIERARCHY_MAIN');



debug('begin add_signature: EBS_MFG_PO_APPRVL_FORWARD_TO_POSITION_APPROVAL_ASSIGNMENTS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '31767',
      p_sig_id                 => 'EBS_MFG_PO_APPRVL_FORWARD_TO_POSITION_APPROVAL_ASSIGNMENTS',
      p_sig_sql                => 'select ppca.position_id, ppca.position_id "##$$FK2$$##", ppca.control_function_id, ppca.org_id, fndu.user_id, 
paaf.person_id, paaf.person_id "##$$FK1$$##", pcf.document_type_code, pcf.document_subtype, pcf.description
from po_position_controls_all ppca, po_control_functions pcf,
per_all_assignments_f paaf, per_all_people_f papf, fnd_user fndu,
  (select poah.employee_id
  from po_action_history poah, po_action_history poah2, 
     (select max(sequence_num) topseq from po_action_history 
      where object_type_code = ''##$$TRXTP$$##'' and object_sub_type_code = ''##$$SUBTP$$##''
      and object_id = ##$$DOCID$$##) findseq
  where poah2.action_code = ''FORWARD'' and poah2.sequence_num = (findseq.topseq - 1)
  and poah2.object_type_code = poah.object_type_code and poah2.object_sub_type_code = poah.object_sub_type_code and poah2.object_id = poah.object_id
  and poah.sequence_num = findseq.topseq 
  and poah.object_type_code = ''##$$TRXTP$$##'' and poah.object_sub_type_code = ''##$$SUBTP$$##'' and poah.object_id = ##$$DOCID$$##) ActHistFwdTo
where ppca.org_id = ##$$ORGID$$##
and ppca.control_function_id = pcf.control_function_id
and pcf.document_type_code = ''##$$TRXTP$$##'' and pcf.document_subtype = ''##$$SUBTP$$##''
and ppca.position_id = paaf.position_id and ppca.position_id is not null --- THIS MAKES THE QUERY FOR POSITION BASED APPROVALS
and paaf.effective_start_date <= sysdate and paaf.effective_end_date >= sysdate
and papf.effective_start_date <= sysdate and papf.effective_end_date >= sysdate
and paaf.person_id = papf.person_id
and concat(concat(paaf.person_id,''-''),NVL(paaf.object_version_number,0)) in
(select concat(concat(person_id, ''-''), NVL(max(object_version_number),0))
from per_all_assignments_f
where person_id = ActHistFwdTo.employee_id
group by person_id)
and paaf.person_id = fndu.employee_id
and fndu.employee_id = ActHistFwdTo.employee_id
order by ppca.position_id',
      p_title                  => 'Forward To Person - Position Approval Assignments and Validation Checks',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'No Approval Assignments found for this document type and the position assigned to the current Forward To approver person on the document',
      p_solution               => 'Assign an approval group to this document type and Forward To approver person''s position if needed.
Navigation: PO Responsibility > Setup > Approvals > Approval Assignments.
',
      p_success_msg            => 'Approval Assignments for the Document Type as assigned to the Position of the current Forward To approver person on this Document',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL('APP_HIER_CHECK2_V1','POA_APP_HIER_CHECK3_V1','POA_APP_HIER_CHECK4','POA_APP_HIER_CHECK5','POA_APP_HIER_CHECK6','EBS_MFG_PO_APPRVL_HIER_CHECK7_EMP_NO_USER','EBS_MFG_PO_APPRVL_HIER_CHECK8_EMP_NOT_ACTIVE','EBS_MFG_PO_APPRVL_HIER_CHECK9_EMP_VS_USER_EMAIL','EBS_MFG_PO_APPRVL_HIER_CHECK11','POA_APP_POS_MULTIPLE_APPR_GROUPS_ASSIGNED','CHARGE ACCOUNT DIGITS-ACCOUNT RANGE LOW DIGITS','CHARGE ACCOUNT DIGITS-ACCOUNT RANGE HIGH DIGITS'),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_PO_APPRVL_FORWARD_TO_POSITION_APPROVAL_ASSIGNMENTS');



debug('begin add_signature: EBS_MFG_PO_APPRVL_OWNER_JOB_APPROVAL_ASSIGNMENTS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '29354',
