      p_sig_sql                => 'select ppca.position_id, ppca.control_group_id, ppca.job_id, ppca.control_function_id, ppca.org_id, paaf.job_id, fndu.user_id, paaf.person_id, paaf.person_id "##$$FK1$$##", pcr.control_group_id, pcr.control_rule_id,
pcr.last_update_date, pcr.rule_type_code, pcr.object_code, pcf.document_type_code, pcf.document_subtype, pcf.description, pcr.amount_limit,
(CASE 
WHEN flexcharge.accountsegcount = 1 THEN
''LOW: ''||(NVL(pcr.segment1_low,''null''))||'' HIGH: ''||
(NVL(pcr.segment1_high,''null''))

