''LOW: ''||(NVL(pcr.segment1_low,''null'')||''.''||NVL(pcr.segment2_low,''null''))||'' HIGH: ''||
(NVL(pcr.segment1_high,''null'')||''.''||NVL(pcr.segment2_high,''null''))

