''LOW: ''||(NVL(pcr.segment1_low,''null'')||''.''||NVL(pcr.segment2_low,''null'')||''.''||NVL(pcr.segment3_low,''null''))||'' HIGH: ''||
(NVL(pcr.segment1_high,''null'')||''.''||NVL(pcr.segment2_high,''null'')||''.''||NVL(pcr.segment3_high,''null''))

WHEN flexcharge.accountsegcount = 4 THEN
''LOW: ''||(NVL(pcr.segment1_low,''null'')||''.''||NVL(pcr.segment2_low,''null'')||''.''||NVL(pcr.segment3_low,''null'')||''.''||NVL(pcr.segment4_low,''null''))||'' HIGH: ''||
(NVL(pcr.segment1_high,''null'')||''.''||NVL(pcr.segment2_high,''null'')||''.''||NVL(pcr.segment3_high,''null'')||''.''||NVL(pcr.segment4_high,''null''))

WHEN flexcharge.accountsegcount = 5 THEN
''LOW: ''||(NVL(pcr.segment1_low,''null'')||''.''||NVL(pcr.segment2_low,''null'')||''.''||NVL(pcr.segment3_low,''null'')||''.''||NVL(pcr.segment4_low,''null'')||''.''||NVL(pcr.segment5_low,''null''))||'' HIGH: ''||
(NVL(pcr.segment1_high,''null'')||''.''||NVL(pcr.segment2_high,''null'')||''.''||NVL(pcr.segment3_high,''null'')||''.''||NVL(pcr.segment4_high,''null'')||''.''||NVL(pcr.segment5_high,''null''))

WHEN flexcharge.accountsegcount = 6 THEN
''LOW: ''||(NVL(pcr.segment1_low,''null'')||''.''||NVL(pcr.segment2_low,''null'')||''.''||NVL(pcr.segment3_low,''null'')||''.''||NVL(pcr.segment4_low,''null'')||''.''||NVL(pcr.segment5_low,''null'')||''.''||NVL(pcr.segment6_low,''null''))||'' HIGH: ''||
(NVL(pcr.segment1_high,''null'')||''.''||NVL(pcr.segment2_high,''null'')||''.''||NVL(pcr.segment3_high,''null'')||''.''||NVL(pcr.segment4_high,''null'')||''.''||NVL(pcr.segment5_high,''null'')||''.''||NVL(pcr.segment6_high,''null''))

WHEN flexcharge.accountsegcount = 7 THEN
''LOW: ''||(NVL(pcr.segment1_low,''null'')||''.''||NVL(pcr.segment2_low,''null'')||''.''||NVL(pcr.segment3_low,''null'')||''.''||NVL(pcr.segment4_low,''null'')||''.''||NVL(pcr.segment5_low,''null'')||''.''||NVL(pcr.segment6_low,''null'')||''.''
||NVL(pcr.segment7_low,''null''))||'' HIGH: ''||
(NVL(pcr.segment1_high,''null'')||''.''||NVL(pcr.segment2_high,''null'')||''.''||NVL(pcr.segment3_high,''null'')||''.''||NVL(pcr.segment4_high,''null'')||''.''||NVL(pcr.segment5_high,''null'')||''.''||NVL(pcr.segment6_high,''null'')||''.''
||NVL(pcr.segment7_high,''null''))

WHEN flexcharge.accountsegcount = 8 THEN
''LOW: ''||(NVL(pcr.segment1_low,''null'')||''.''||NVL(pcr.segment2_low,''null'')||''.''||NVL(pcr.segment3_low,''null'')||''.''||NVL(pcr.segment4_low,''null'')||''.''||NVL(pcr.segment5_low,''null'')||''.''||NVL(pcr.segment6_low,''null'')||''.''
||NVL(pcr.segment7_low,''null'')||''.''||NVL(pcr.segment8_low,''null''))||'' HIGH: ''||
(NVL(pcr.segment1_high,''null'')||''.''||NVL(pcr.segment2_high,''null'')||''.''||NVL(pcr.segment3_high,''null'')||''.''||NVL(pcr.segment4_high,''null'')||''.''||NVL(pcr.segment5_high,''null'')||''.''||NVL(pcr.segment6_high,''null'')||''.''
||NVL(pcr.segment7_high,''null'')||''.''||NVL(pcr.segment8_high,''null''))

WHEN flexcharge.accountsegcount = 9 THEN
''LOW: ''||(NVL(pcr.segment1_low,''null'')||''.''||NVL(pcr.segment2_low,''null'')||''.''||NVL(pcr.segment3_low,''null'')||''.''||NVL(pcr.segment4_low,''null'')||''.''||NVL(pcr.segment5_low,''null'')||''.''||NVL(pcr.segment6_low,''null'')||''.''
||NVL(pcr.segment7_low,''null'')||''.''||NVL(pcr.segment8_low,''null'')||''.''||NVL(pcr.segment9_low,''null''))||'' HIGH: ''||
(NVL(pcr.segment1_high,''null'')||''.''||NVL(pcr.segment2_high,''null'')||''.''||NVL(pcr.segment3_high,''null'')||''.''||NVL(pcr.segment4_high,''null'')||''.''||NVL(pcr.segment5_high,''null'')||''.''||NVL(pcr.segment6_high,''null'')||''.''
||NVL(pcr.segment7_high,''null'')||''.''||NVL(pcr.segment8_high,''null'')||''.''||NVL(pcr.segment9_high,''null''))

WHEN flexcharge.accountsegcount = 10 THEN
''LOW: ''||(NVL(pcr.segment1_low,''null'')||''.''||NVL(pcr.segment2_low,''null'')||''.''||NVL(pcr.segment3_low,''null'')||''.''||NVL(pcr.segment4_low,''null'')||''.''||NVL(pcr.segment5_low,''null'')||''.''||NVL(pcr.segment6_low,''null'')||''.''
||NVL(pcr.segment7_low,''null'')||''.''||NVL(pcr.segment8_low,''null'')||''.''||NVL(pcr.segment9_low,''null'')||''.''||NVL(pcr.segment10_low,''null''))||'' HIGH: ''||
(NVL(pcr.segment1_high,''null'')||''.''||NVL(pcr.segment2_high,''null'')||''.''||NVL(pcr.segment3_high,''null'')||''.''||NVL(pcr.segment4_high,''null'')||''.''||NVL(pcr.segment5_high,''null'')||''.''||NVL(pcr.segment6_high,''null'')||''.''
||NVL(pcr.segment7_high,''null'')||''.''||NVL(pcr.segment8_high,''null'')||''.''||NVL(pcr.segment9_high,''null'')||''.''||NVL(pcr.segment10_high,''null''))

WHEN flexcharge.accountsegcount = 11 THEN
''LOW: ''||(NVL(pcr.segment1_low,''null'')||''.''||NVL(pcr.segment2_low,''null'')||''.''||NVL(pcr.segment3_low,''null'')||''.''||NVL(pcr.segment4_low,''null'')||''.''||NVL(pcr.segment5_low,''null'')||''.''||NVL(pcr.segment6_low,''null'')||''.''
||NVL(pcr.segment7_low,''null'')||''.''||NVL(pcr.segment8_low,''null'')||''.''||NVL(pcr.segment9_low,''null'')||''.''||NVL(pcr.segment10_low,''null'')||''.''||NVL(pcr.segment11_low,''null''))||'' HIGH: ''||
(NVL(pcr.segment1_high,''null'')||''.''||NVL(pcr.segment2_high,''null'')||''.''||NVL(pcr.segment3_high,''null'')||''.''||NVL(pcr.segment4_high,''null'')||''.''||NVL(pcr.segment5_high,''null'')||''.''||NVL(pcr.segment6_high,''null'')||''.''
||NVL(pcr.segment7_high,''null'')||''.''||NVL(pcr.segment8_high,''null'')||''.''||NVL(pcr.segment9_high,''null'')||''.''||NVL(pcr.segment10_high,''null'')||''.''||NVL(pcr.segment11_high,''null''))

WHEN flexcharge.accountsegcount = 12 THEN
''LOW: ''||(NVL(pcr.segment1_low,''null'')||''.''||NVL(pcr.segment2_low,''null'')||''.''||NVL(pcr.segment3_low,''null'')||''.''||NVL(pcr.segment4_low,''null'')||''.''||NVL(pcr.segment5_low,''null'')||''.''||NVL(pcr.segment6_low,''null'')||''.''
||NVL(pcr.segment7_low,''null'')||''.''||NVL(pcr.segment8_low,''null'')||''.''||NVL(pcr.segment9_low,''null'')||''.''||NVL(pcr.segment10_low,''null'')||''.''||NVL(pcr.segment11_low,''null'')||''.''||NVL(pcr.segment12_low,''null''))||'' HIGH: ''||
(NVL(pcr.segment1_high,''null'')||''.''||NVL(pcr.segment2_high,''null'')||''.''||NVL(pcr.segment3_high,''null'')||''.''||NVL(pcr.segment4_high,''null'')||''.''||NVL(pcr.segment5_high,''null'')||''.''||NVL(pcr.segment6_high,''null'')||''.''
||NVL(pcr.segment7_high,''null'')||''.''||NVL(pcr.segment8_high,''null'')||''.''||NVL(pcr.segment9_high,''null'')||''.''||NVL(pcr.segment10_high,''null'')||''.''||NVL(pcr.segment11_high,''null'')||''.''||NVL(pcr.segment12_high,''null''))
END)  low_high
--pcr.segment1_low low1, pcr.segment2_low low2, pcr.segment3_low low3, pcr.segment4_low low4,
--pcr.segment5_low low5, pcr.segment6_low low6, pcr.segment7_low low7, pcr.segment8_low low8,
--pcr.segment9_low low9, pcr.segment10_low low10, pcr.segment11_low low11, pcr.segment12_low low12,
--pcr.segment1_high high1, pcr.segment2_high high2, pcr.segment3_high high3, pcr.segment4_high high4,
--pcr.segment5_high high5, pcr.segment6_high high6, pcr.segment7_high high7, pcr.segment8_high high8,
--pcr.segment9_high high9, pcr.segment10_high high10, pcr.segment11_high high11, pcr.segment12_high high12
from po_control_rules pcr, po_position_controls_all ppca, po_control_functions pcf,
per_all_assignments_f paaf, per_all_people_f papf, fnd_user fndu,
   (SELECT count(distinct ifs.segment_name) accountsegcount
    FROM fnd_id_flex_structures fifs , fnd_id_flex_structures_tl fifst , fnd_id_flex_segments ifs , fnd_flex_value_sets ffvs , gl_ledgers gll , fnd_segment_attribute_values fsav1 , 
    fnd_segment_attribute_values fsav2 , fnd_segment_attribute_values fsav3 , fnd_segment_attribute_values fsav4 , fnd_segment_attribute_values fsav5 , fnd_segment_attribute_values fsav6 
    WHERE 1=1 and fifs.id_flex_code = ''GL#'' and fifs.application_id = fifst.application_id and fifs.id_flex_code = fifst.id_flex_code and fifs.id_flex_num = fifst.id_flex_num and 
    fifs.application_id = ifs.application_id and fifs.id_flex_code = ifs.id_flex_code and fifs.id_flex_num = ifs.id_flex_num and fsav1.application_id = ifs.application_id and 
    fsav1.id_flex_code = ifs.id_flex_code and fsav1.id_flex_num = ifs.id_flex_num and fsav1.application_column_name = ifs.application_column_name and fsav2.application_id = ifs.application_id 
    and fsav2.id_flex_code = ifs.id_flex_code and fsav2.id_flex_num = ifs.id_flex_num and fsav2.application_column_name = ifs.application_column_name and fsav3.application_id = ifs.application_id 
    and fsav3.id_flex_code = ifs.id_flex_code and fsav3.id_flex_num = ifs.id_flex_num and fsav3.application_column_name = ifs.application_column_name and fsav4.application_id = ifs.application_id 
    and fsav4.id_flex_code = ifs.id_flex_code and fsav4.id_flex_num = ifs.id_flex_num and fsav4.application_column_name = ifs.application_column_name and fsav5.application_id = ifs.application_id 
    and fsav5.id_flex_code = ifs.id_flex_code and fsav5.id_flex_num = ifs.id_flex_num and fsav5.application_column_name = ifs.application_column_name and fsav6.application_id = ifs.application_id 
    and fsav6.id_flex_code = ifs.id_flex_code and fsav6.id_flex_num = ifs.id_flex_num and fsav6.application_column_name = ifs.application_column_name and fsav1.segment_attribute_type = ''GL_BALANCING'' 
    and fsav2.segment_attribute_type = ''FA_COST_CTR'' and fsav3.segment_attribute_type = ''GL_ACCOUNT'' and fsav4.segment_attribute_type = ''GL_INTERCOMPANY'' and fsav5.segment_attribute_type = ''GL_SECONDARY_TRACKING'' 
    and fsav6.segment_attribute_type = ''GL_MANAGEMENT'' and ifs.id_flex_num = gll.chart_of_accounts_id and ifs.flex_value_set_id = ffvs.flex_value_set_id 
    and gll.ledger_id in (select set_of_books_id from hr_operating_units where organization_id = ##$$ORGID$$## )
    ) flexcharge
where pcr.control_group_id = ppca.control_group_id
and ppca.org_id = ##$$ORGID$$##
and ppca.control_function_id = pcf.control_function_id
and pcf.document_type_code = ''##$$TRXTP$$##'' and pcf.document_subtype = ''##$$SUBTP$$##''
and ppca.job_id = paaf.job_id and ppca.job_id is not null --- THIS MAKES THE QUERY FOR JOB BASED APPROVALS
and paaf.effective_start_date <= sysdate and paaf.effective_end_date >= sysdate
and papf.effective_start_date <= sysdate and papf.effective_end_date >= sysdate
--and TO_DATE(ppca.start_date) <= sysdate and TO_DATE(ppca.end_date) >= sysdate
and paaf.person_id = papf.person_id
and concat(concat(paaf.person_id,''-''),NVL(paaf.object_version_number,0)) in
(select concat(concat(person_id, ''-''), NVL(max(object_version_number),0))
from per_all_assignments_f
where person_id = ##$$PREPID$$##
group by person_id)
and paaf.person_id = fndu.employee_id
and fndu.employee_id = ##$$PREPID$$##

and fndu.user_id = (select created_by from
(select poha.created_by from po_headers_all poha, po_control_functions pcf where poha.po_header_id = ##$$DOCID$$## 
   and pcf.DOCUMENT_TYPE_CODE in (''PO'',''PA'') and pcf.document_type_code = ''##$$TRXTP$$##''  and pcf.document_subtype = ''##$$SUBTP$$##''
UNION ALL
Select pora.created_by from po_releases_all pora, po_control_functions pcf where pora.po_release_id = ##$$RELID$$## and pora.po_header_id = ##$$DOCID$$## 
   and pcf.DOCUMENT_TYPE_CODE = ''RELEASE'' and pcf.document_type_code = ''##$$TRXTP$$##''  and pcf.document_subtype = ''##$$SUBTP$$##''
UNION ALL
Select prha.created_by from po_requisition_headers_all prha, po_control_functions pcf where prha.requisition_header_id = ##$$DOCID$$## 
   and pcf.DOCUMENT_TYPE_CODE = ''REQUISITION'' and pcf.document_type_code = ''##$$TRXTP$$##''  and pcf.document_subtype = ''##$$SUBTP$$##''
))

order by
pcr.control_group_id, pcr.control_rule_id, fndu.user_name ',
      p_title                  => 'Owner Job Approval Assignments',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'No Approval Assignments found for this document type and the job assigned to the Owner of the document',
      p_solution               => 'Assign an approval group to this document type and job if needed.
Navigation: PO Responsibility > Setup > Approvals > Approval Assignments.
',
      p_success_msg            => 'Approval Assignments for the Document Type as assigned to the Job of the Owner of this Document',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_PO_APPRVL_OWNER_JOB_APPROVAL_ASSIGNMENTS');



debug('begin add_signature: POA_APP_HIER_CHECK1');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '12649',
      p_sig_id                 => 'POA_APP_HIER_CHECK1',
      p_sig_sql                => 'SELECT org_id, control_function_name, control_group_name, rule_type_code, object_code, amount_limit, accountsegcount segmentcount,
crseg1_low||crseg2_low||crseg3_low||crseg4_low||crseg5_low||crseg6_low||crseg7_low||crseg8_low||crseg9_low||crseg10_low||crseg11_low||crseg12_low account_limit_low,
crseg1_high||crseg2_high||crseg3_high||crseg4_high||crseg5_high||crseg6_high||crseg7_high||crseg8_high||crseg9_high||crseg10_high||crseg11_high||crseg12_high account_limit_high
from
(SELECT
 pc2.org_id,
 pc2.control_function_name,
 pc2.control_group_name,
 pc2.rule_type_code,
 pc2.object_code,
 pc2.amount_limit,
 pc2.accountsegcount,
 (CASE WHEN (pc2.seg1 =1) THEN pc2.segment1_low WHEN (pc2.seg1 =0 and accountsegcount >= 1) THEN ''null'' ELSE '''' END) crseg1_low,
 (CASE WHEN (pc2.seg2 =1) THEN ''.''||pc2.segment2_low WHEN (pc2.seg2 =0 and accountsegcount >= 2) THEN ''.null'' ELSE '''' END) crseg2_low,
 (CASE WHEN (pc2.seg3 =1) THEN ''.''||pc2.segment3_low WHEN (pc2.seg3 =0 and accountsegcount >= 3) THEN ''.null'' ELSE '''' END) crseg3_low,
 (CASE WHEN (pc2.seg4 =1) THEN ''.''||pc2.segment4_low WHEN (pc2.seg4 =0 and accountsegcount >= 4) THEN ''.null'' ELSE '''' END) crseg4_low,
 (CASE WHEN (pc2.seg5 =1) THEN ''.''||pc2.segment5_low WHEN (pc2.seg5 =0 and accountsegcount >= 5) THEN ''.null'' ELSE '''' END) crseg5_low,
 (CASE WHEN (pc2.seg6 =1) THEN ''.''||pc2.segment6_low WHEN (pc2.seg6 =0 and accountsegcount >= 6) THEN ''.null'' ELSE '''' END) crseg6_low,
 (CASE WHEN (pc2.seg7 =1) THEN ''.''||pc2.segment7_low WHEN (pc2.seg7 =0 and accountsegcount >= 7) THEN ''.null'' ELSE '''' END) crseg7_low,
 (CASE WHEN (pc2.seg8 =1) THEN ''.''||pc2.segment8_low WHEN (pc2.seg8 =0 and accountsegcount >= 8) THEN ''.null'' ELSE '''' END) crseg8_low,
 (CASE WHEN (pc2.seg9 =1) THEN ''.''||pc2.segment9_low WHEN (pc2.seg9 =0 and accountsegcount >= 9) THEN ''.null'' ELSE '''' END) crseg9_low,
 (CASE WHEN (pc2.seg10 =1) THEN ''.''||pc2.segment10_low WHEN (pc2.seg10 =0 and accountsegcount >= 10) THEN ''.null'' ELSE '''' END) crseg10_low,
 (CASE WHEN (pc2.seg11 =1) THEN ''.''||pc2.segment11_low WHEN (pc2.seg11 =0 and accountsegcount >= 11) THEN ''.null'' ELSE '''' END) crseg11_low,
 (CASE WHEN (pc2.seg12 =1) THEN ''.''||pc2.segment12_low WHEN (pc2.seg12 =0 and accountsegcount >= 12) THEN ''.null'' ELSE '''' END) crseg12_low,
 (CASE WHEN (pc2.seg1h =1) THEN pc2.segment1_high WHEN (pc2.seg1h =0 and accountsegcount >= 1) THEN ''null'' ELSE '''' END) crseg1_high,
 (CASE WHEN (pc2.seg2h =1) THEN ''.''||pc2.segment2_high WHEN (pc2.seg2h =0 and accountsegcount >= 2) THEN ''.null'' ELSE '''' END) crseg2_high,
 (CASE WHEN (pc2.seg3h =1) THEN ''.''||pc2.segment3_high WHEN (pc2.seg3h =0 and accountsegcount >= 3) THEN ''.null'' ELSE '''' END) crseg3_high,
 (CASE WHEN (pc2.seg4h =1) THEN ''.''||pc2.segment4_high WHEN (pc2.seg4h =0 and accountsegcount >= 4) THEN ''.null'' ELSE '''' END) crseg4_high,
 (CASE WHEN (pc2.seg5h =1) THEN ''.''||pc2.segment5_high WHEN (pc2.seg5h =0 and accountsegcount >= 5) THEN ''.null'' ELSE '''' END) crseg5_high,
 (CASE WHEN (pc2.seg6h =1) THEN ''.''||pc2.segment6_high WHEN (pc2.seg6h =0 and accountsegcount >= 6) THEN ''.null'' ELSE '''' END) crseg6_high,
 (CASE WHEN (pc2.seg7h =1) THEN ''.''||pc2.segment7_high WHEN (pc2.seg7h =0 and accountsegcount >= 7) THEN ''.null'' ELSE '''' END) crseg7_high,
 (CASE WHEN (pc2.seg8h =1) THEN ''.''||pc2.segment8_high WHEN (pc2.seg8h =0 and accountsegcount >= 8) THEN ''.null'' ELSE '''' END) crseg8_high,
 (CASE WHEN (pc2.seg9h =1) THEN ''.''||pc2.segment9_high WHEN (pc2.seg9h =0 and accountsegcount >= 9) THEN ''.null'' ELSE '''' END) crseg9_high,
 (CASE WHEN (pc2.seg10h =1) THEN ''.''||pc2.segment10_high WHEN (pc2.seg10h =0 and accountsegcount >= 10) THEN ''.null'' ELSE '''' END) crseg10_high,
 (CASE WHEN (pc2.seg11h =1) THEN ''.''||pc2.segment11_high WHEN (pc2.seg11h =0 and accountsegcount >= 11) THEN ''.null'' ELSE '''' END) crseg11_high,
 (CASE WHEN (pc2.seg12h =1) THEN ''.''||pc2.segment12_high WHEN (pc2.seg12h =0 and accountsegcount >= 12) THEN ''.null'' ELSE '''' END) crseg12_high
 FROM
 (SELECT pc.org_id,
        cf.control_function_name,
        cg.control_group_name,
        cr.rule_type_code,
        cr.object_code,
        to_char(cr.amount_limit) amount_limit,
        flexcharge.accountsegcount,
        cr.segment1_low, cr.segment2_low, cr.segment3_low, cr.segment4_low, cr.segment5_low, cr.segment6_low, cr.segment7_low, cr.segment8_low, cr.segment9_low, cr.segment10_low, cr.segment11_low, cr.segment12_low,
        cr.segment1_high, cr.segment2_high, cr.segment3_high, cr.segment4_high, cr.segment5_high, cr.segment6_high, cr.segment7_high, cr.segment8_high, cr.segment9_high, cr.segment10_high, cr.segment11_high, cr.segment12_high,
        DECODE(segment1_low,null,0,1) seg1, DECODE(segment2_low,null,0,1) seg2, DECODE(segment3_low,null,0,1) seg3, DECODE(segment4_low,null,0,1) seg4, DECODE(segment5_low,null,0,1) seg5, DECODE(segment6_low,null,0,1) seg6, 
        DECODE(segment7_low,null,0,1) seg7, DECODE(segment8_low,null,0,1) seg8, DECODE(segment9_low,null,0,1) seg9, DECODE(segment10_low,null,0,1) seg10, DECODE(segment11_low,null,0,1) seg11, DECODE(segment12_low,null,0,1) seg12,
        DECODE(segment1_high,null,0,1) seg1h, DECODE(segment2_high,null,0,1) seg2h, DECODE(segment3_high,null,0,1) seg3h, DECODE(segment4_high,null,0,1) seg4h, DECODE(segment5_high,null,0,1) seg5h, DECODE(segment6_high,null,0,1) seg6h, 
        DECODE(segment7_high,null,0,1) seg7h, DECODE(segment8_high,null,0,1) seg8h, DECODE(segment9_high,null,0,1) seg9h, DECODE(segment10_high,null,0,1) seg10h, DECODE(segment11_high,null,0,1) seg11h, DECODE(segment12_high,null,0,1) seg12h
 FROM po_position_controls_all pc,
      po_control_groups_all cg,
      po_control_functions cf,
      po_control_rules cr,
   (SELECT count(distinct ifs.segment_name) accountsegcount
    FROM fnd_id_flex_structures fifs , fnd_id_flex_structures_tl fifst , fnd_id_flex_segments ifs , fnd_flex_value_sets ffvs , gl_ledgers gll , fnd_segment_attribute_values fsav1 , 
    fnd_segment_attribute_values fsav2 , fnd_segment_attribute_values fsav3 , fnd_segment_attribute_values fsav4 , fnd_segment_attribute_values fsav5 , fnd_segment_attribute_values fsav6 
    WHERE 1=1 and fifs.id_flex_code = ''GL#'' and fifs.application_id = fifst.application_id and fifs.id_flex_code = fifst.id_flex_code and fifs.id_flex_num = fifst.id_flex_num and 
    fifs.application_id = ifs.application_id and fifs.id_flex_code = ifs.id_flex_code and fifs.id_flex_num = ifs.id_flex_num and fsav1.application_id = ifs.application_id and 
    fsav1.id_flex_code = ifs.id_flex_code and fsav1.id_flex_num = ifs.id_flex_num and fsav1.application_column_name = ifs.application_column_name and fsav2.application_id = ifs.application_id 
    and fsav2.id_flex_code = ifs.id_flex_code and fsav2.id_flex_num = ifs.id_flex_num and fsav2.application_column_name = ifs.application_column_name and fsav3.application_id = ifs.application_id 
    and fsav3.id_flex_code = ifs.id_flex_code and fsav3.id_flex_num = ifs.id_flex_num and fsav3.application_column_name = ifs.application_column_name and fsav4.application_id = ifs.application_id 
    and fsav4.id_flex_code = ifs.id_flex_code and fsav4.id_flex_num = ifs.id_flex_num and fsav4.application_column_name = ifs.application_column_name and fsav5.application_id = ifs.application_id 
    and fsav5.id_flex_code = ifs.id_flex_code and fsav5.id_flex_num = ifs.id_flex_num and fsav5.application_column_name = ifs.application_column_name and fsav6.application_id = ifs.application_id 
    and fsav6.id_flex_code = ifs.id_flex_code and fsav6.id_flex_num = ifs.id_flex_num and fsav6.application_column_name = ifs.application_column_name and fsav1.segment_attribute_type = ''GL_BALANCING'' 
    and fsav2.segment_attribute_type = ''FA_COST_CTR'' and fsav3.segment_attribute_type = ''GL_ACCOUNT'' and fsav4.segment_attribute_type = ''GL_INTERCOMPANY'' and fsav5.segment_attribute_type = ''GL_SECONDARY_TRACKING'' 
    and fsav6.segment_attribute_type = ''GL_MANAGEMENT'' and ifs.id_flex_num = gll.chart_of_accounts_id and ifs.flex_value_set_id = ffvs.flex_value_set_id 
    and gll.ledger_id in (select set_of_books_id from hr_operating_units where organization_id = ##$$ORGID$$##)
    ) flexcharge
 WHERE pc.control_group_id = cg.control_group_id
  AND   pc.control_function_id = cf.control_function_id
    AND   pc.org_id = ##$$ORGID$$##
    AND   pc.job_id = ##$$FK2$$##
    AND   cf.document_type_code = ''##$$TRXTP$$##''
    AND   cf.document_subtype = ''##$$SUBTP$$##''
    AND   trunc(sysdate) BETWEEN pc.start_date AND nvl(pc.end_date,sysdate+1)
    AND   cr.control_group_id = pc.control_group_id
    AND   cf.enabled_flag = ''Y''
    AND   cg.enabled_flag = ''Y''
    ) pc2
)
ORDER BY control_function_name, control_group_name, object_code, rule_type_code DESC',
      p_title                  => 'Job Approval Assignments',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'No approval assignments found for this document type and job',
      p_solution               => 'Assign an approval group to this document type and job if needed.
(Navigation: PO Responsibility > Setup > Approvals > Approval Assignments.)',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
