debug('begin add_signature: POA_APP_SUP_JOB_ASG_MULTIPLE_GROUPS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '16864',
      p_sig_id                 => 'POA_APP_SUP_JOB_ASG_MULTIPLE_GROUPS',
      p_sig_sql                => 'SELECT distinct ''Job'' type, pj.job_id ID, pj.name Name, pc.org_id,
cg.control_group_name ApprovalGroup
    FROM po_position_controls_all pc,
         per_jobs pj,
         po_control_groups_all cg,
         po_control_functions cf,
         po_control_rules cr
    WHERE pc.control_group_id = cg.control_group_id
    AND   cr.control_group_id = pc.control_group_id
    AND   pc.control_function_id = cf.control_function_id
    AND   pc.org_id = ##$$ORGID$$##
    AND   pj.job_id = pc.job_id
    AND   pc.job_id = ##$$FK2$$##
    AND   trunc(sysdate) BETWEEN pc.start_date AND nvl(pc.end_date,sysdate+1)
AND cf.document_type_code = ''##$$TRXTP$$##'' AND cf.document_subtype = ''##$$SUBTP$$##'' 
    AND   cf.enabled_flag = ''Y''
    AND   cg.enabled_flag = ''Y''
order by pj.name, pc.org_id',
      p_title                  => 'Multiple Approval Groups Assigned to Single Job',
      p_fail_condition         => 'RSGT1',
      p_problem_descr          => 'Multiple Approval Groups assigned to a single Job results in questionable Approval Routing and/or incomplete No Approver Found result',
      p_solution               => 'Review [374263/KB676948] for clarification and recommendations about assigning only one approval group per job (or position when using position hierarchy)',
      p_success_msg            => 'There are not multiple approval groups assigned to this job; only a single approval group is assigned to this job, as recommended in [374263/KB676948].',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: POA_APP_SUP_JOB_ASG_MULTIPLE_GROUPS');



