debug('begin add_signature: POA_APP_SUP_HIERARCHY_MAIN');
   l_info('##MASK##EMPLOYEE_NAME'):= 'DISPLAY_FIRST_25_PCNT_WORD';
   l_info('##MASK##SUPERVISOR_NAME'):= 'DISPLAY_FIRST_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '2364',
      p_sig_id                 => 'POA_APP_SUP_HIERARCHY_MAIN',
      p_sig_sql                => 'SELECT p1.full_name employee_name,
           h.employee_id,
           nvl(h.employee_id,0) "##$$FK1$$##",
           p2.full_name supervisor_name,
           h.supervisor_id,
           nvl(h.supervisor_id, 0) "##$$FK3$$##",
           j.name job_name,
           h.job_id,
           h.job_id "##$$FK2$$##",
           h.hier_level lvl,
           h.loop,
           h.loop "##$$FK4$$##"
    FROM per_all_people_f p1,
         per_all_people_f p2,
         per_jobs j,
         (
           SELECT a.person_id employee_id,
                  a.assignment_id,
                  a.effective_start_date,
                  a.effective_end_date,
                  a.supervisor_id,
                  a.job_id,
                  level hier_level,
                  decode(connect_by_iscycle,
                    0, ''No'',
                    ''Yes'') loop
           FROM per_assignments_f a
           WHERE EXISTS (
                   SELECT ''1''
                   FROM per_people_f p, per_assignments_f a1
                   WHERE trunc(sysdate) BETWEEN p.effective_start_date AND
                           p.effective_end_date
                   AND   p.person_id = a.person_id
                   AND   a1.person_id = p.person_id
                   AND   trunc(sysdate) BETWEEN a1.effective_start_date AND
                           a1.effective_end_date
                   AND   a1.primary_flag = ''Y''
                   AND   a1.ASSIGNMENT_TYPE IN (''E'',''C'')
                   AND   EXISTS (
                         SELECT ''1''
                         FROM per_person_types pt,
                              per_person_type_usages_f ptu
                         WHERE ptu.person_id = p.person_id
                         AND   pt.system_person_type IN (''EMP'',''EMP_APL'',''CWK'')
                         AND   pt.person_type_id = ptu.person_type_id))
           START WITH a.person_id = ##$$PREPID$$##
                AND   trunc(sysdate) BETWEEN a.effective_start_date AND
                        a.effective_end_date
                AND   a.primary_flag = ''Y''
                AND   a.ASSIGNMENT_TYPE IN (''E'',''C'')
           CONNECT BY NOCYCLE PRIOR a.supervisor_id = a.person_id
                AND   trunc(sysdate) BETWEEN a.effective_start_date AND
                        a.effective_end_date
                AND   a.primary_flag = ''Y''
                AND   a.ASSIGNMENT_TYPE IN (''E'',''C'')
         ) h
    WHERE p1.person_id = h.employee_id
    AND   trunc(sysdate) BETWEEN p1.effective_start_date AND
                         p1.effective_end_date
    AND   p2.person_id (+) = h.supervisor_id
    AND   trunc(sysdate) BETWEEN p2.effective_start_date (+) AND
                         p2.effective_end_date (+)
    AND   j.job_id = h.job_id
    ORDER BY h.hier_level',
      p_title                  => 'Approving Employee',
      p_fail_condition         => '[LOOP]=[Yes]',
      p_problem_descr          => 'There is a loop in the employee/supervisor hierarchy',
      p_solution               => 'Review the list of approvers shown above and modify the approval hierarchy so there is no loop in the employee/supervisor hierarchy.
More details should be available under the record where the loop was found.

For setup information, please review the following document [134947/KB533560] - <i>Purchasing Setup of Approval Hierarchies</i>
<li>Also review recommended actions from [1106106/KB706205]</li>',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL('POA_APP_HIER_CHECK1','POA_APP_HIER_CHECK3_V1','POA_APP_HIER_CHECK4','POA_APP_HIER_CHECK5','POA_APP_HIER_CHECK6','EBS_MFG_PO_APPRVL_HIER_CHECK11','POA_APP_SUP_JOB_ASG_MULTIPLE_GROUPS','LOOP_CHECK','EBS_MFG_PO_APPRVL_HIER_CHECK7_EMP_NO_USER','EBS_MFG_PO_APPRVL_HIER_CHECK8_EMP_NOT_ACTIVE','EBS_MFG_PO_APPRVL_HIER_CHECK9_EMP_VS_USER_EMAIL'),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '86'
      );
   l_info.delete;
debug('end add_signature: POA_APP_SUP_HIERARCHY_MAIN');



debug('begin add_signature: EBS_MFG_PO_APPRVL_FORWARD_TO_JOB_APPROVAL_ASSIGNMENTS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '31769',
      p_sig_id                 => 'EBS_MFG_PO_APPRVL_FORWARD_TO_JOB_APPROVAL_ASSIGNMENTS',
      p_sig_sql                => 'select distinct ppca.job_id, ppca.job_id "##$$FK2$$##", ppca.control_function_id, ppca.org_id, fndu.user_id, 
paaf.person_id, paaf.person_id "##$$FK1$$##", pcf.document_type_code, pcf.document_subtype, pcf.description
from po_position_controls_all ppca, po_control_functions pcf,
per_all_assignments_f paaf, per_all_people_f papf, fnd_user fndu,
  (select poah.employee_id
  from po_action_history poah, po_action_history poah2, 
     (select max(sequence_num) topseq from po_action_history 
      where object_type_code = ''##$$TRXTP$$##'' and object_sub_type_code = ''##$$SUBTP$$##''
      and object_id = ##$$DOCID$$##) findseq
  where poah2.action_code = ''FORWARD'' and poah2.sequence_num = (findseq.topseq - 1)
  and poah2.object_type_code = poah.object_type_code and poah2.object_sub_type_code = poah.object_sub_type_code and poah2.object_id = poah.object_id
  and poah.sequence_num = findseq.topseq 
  and poah.object_type_code = ''##$$TRXTP$$##'' and poah.object_sub_type_code = ''##$$SUBTP$$##'' and poah.object_id = ##$$DOCID$$##) ActHistFwdTo
where ppca.org_id = ##$$ORGID$$##
and ppca.control_function_id = pcf.control_function_id
and pcf.document_type_code = ''##$$TRXTP$$##'' and pcf.document_subtype = ''##$$SUBTP$$##''
and ppca.job_id = paaf.job_id and ppca.job_id is not null --- THIS MAKES THE QUERY FOR JOB BASED APPROVALS
and paaf.effective_start_date <= sysdate and paaf.effective_end_date >= sysdate
and papf.effective_start_date <= sysdate and papf.effective_end_date >= sysdate
and paaf.person_id = papf.person_id
and concat(concat(paaf.person_id,''-''),NVL(paaf.object_version_number,0)) in
(select concat(concat(person_id, ''-''), NVL(max(object_version_number),0))
from per_all_assignments_f
where person_id = ActHistFwdTo.employee_id
group by person_id)
and paaf.person_id = fndu.employee_id
and fndu.employee_id = ActHistFwdTo.employee_id
order by ppca.job_id',
      p_title                  => 'Forward To Person - Job Approval Assignments and Validation Checks',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'No Approval Assignments found for this document type and the job assigned to the current Forward To approver person on the document',
      p_solution               => 'Assign an approval group to this document type and Forward To approver person''s job if needed.
Navigation: PO Responsibility > Setup > Approvals > Approval Assignments.
',
      p_success_msg            => 'Approval Assignments for the Document Type as assigned to the Job of the current Forward To approver person on this Document',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL('POA_APP_HIER_CHECK1','POA_APP_HIER_CHECK3_V1','POA_APP_HIER_CHECK4','POA_APP_HIER_CHECK5','POA_APP_HIER_CHECK6','EBS_MFG_PO_APPRVL_HIER_CHECK7_EMP_NO_USER','EBS_MFG_PO_APPRVL_HIER_CHECK8_EMP_NOT_ACTIVE','EBS_MFG_PO_APPRVL_HIER_CHECK9_EMP_VS_USER_EMAIL','EBS_MFG_PO_APPRVL_HIER_CHECK11','POA_APP_SUP_JOB_ASG_MULTIPLE_GROUPS','CHARGE ACCOUNT DIGITS-ACCOUNT RANGE LOW DIGITS','CHARGE ACCOUNT DIGITS-ACCOUNT RANGE HIGH DIGITS'),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_PO_APPRVL_FORWARD_TO_JOB_APPROVAL_ASSIGNMENTS');



