file_version.translation_level desc) as rank1
from ad_file_versions file_version, 
(select filename, app_short_name, subdir, file_id from ad_files
where subdir = ''java/notifications/server'' and 
(FILENAME like ''%.xml'') -- or FILENAME like ''Po%.xml'' OR FILENAME like ''RELEASE%.xml'' OR FILENAME like ''clm%.xml'' OR FILENAME like ''PA_%.xml'') AND (FILENAME not like ''PAY%.xml'' AND FILENAME not like ''PON%.xml'')
) files
where files.file_id = file_version.file_id
) que
where rank1 = 1
order by filename',
