debug('begin add_signature: EBS_MFG_PO_APPRVL_XSL_FILE_VERSIONS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '29962',
      p_sig_id                 => 'EBS_MFG_PO_APPRVL_XSL_FILE_VERSIONS',
      p_sig_sql                => 'select que.filename, --que.subdir, 
que.version
from 
(select files.filename filename,files.subdir subdir, file_version.version version, rank()over(partition by files.filename, files.subdir
order by file_version.version_segment1 desc, file_version.version_segment2 desc,file_version.version_segment3 desc, file_version.version_segment4 desc,file_version.version_segment5 desc,
file_version.version_segment6 desc,file_version.version_segment7 desc, file_version.version_segment8 desc,file_version.version_segment9 desc, file_version.version_segment10 desc,
file_version.translation_level desc) as rank1
from ad_file_versions file_version, 
(select filename, app_short_name, subdir, file_id from ad_files
where subdir = ''patch/115/publisher/templates'' and 
(FILENAME like ''PO%.xsl'' OR FILENAME like ''RELEASE%.xsl'' OR FILENAME like ''clm%.xsl'' OR FILENAME like ''PA_%.xsl'') AND (FILENAME not like ''PAY%.xsl'' AND FILENAME not like ''PON%.xsl'')) files
where files.file_id = file_version.file_id
) que
where rank1 = 1
order by filename',
      p_title                  => 'Purchasing XSL File Versions',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Procurement Approval related .xsl files not found',
      p_solution               => '',
      p_success_msg            => 'Procurement Approval related .xsl file versions',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_PO_APPRVL_XSL_FILE_VERSIONS');



