debug('begin add_signature: EBS_MFG_APPRVL_REQ_APPROVAL_WORKFLOW_HAS_OPEN_POERROR_OR_WFERROR_CHILD_WORKFLOW');
   l_info('##MASK##ORIGINAL_RECIPIENT'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '32835',
      p_sig_id                 => 'EBS_MFG_APPRVL_REQ_APPROVAL_WORKFLOW_HAS_OPEN_POERROR_OR_WFERROR_CHILD_WORKFLOW',
      p_sig_sql                => 'SELECT 
  we.item_type ERROR_TYPE,
  we.item_key error_key,
  weias.notification_id,
  wfn.sent_date,
  we.end_date notif_end_date,
  wfn.subject notif_subject,
  wfn.original_recipient original_recipient,
  we.parent_item_type po_type,
  we.parent_item_key po_key
FROM 
  wf_items we,
  wf_item_activity_statuses weias,
  wf_notifications wfn
WHERE 
  we.item_type IN (''POERROR'', ''WFERROR'')
  AND weias.item_type = we.item_type
  AND weias.item_key = we.item_key
  AND wfn.GROUP_ID = weias.notification_id
  AND we.parent_item_type IN (
    SELECT DISTINCT 
      wf_item_type
    FROM 
      po_requisition_headers_all
    WHERE 
      wf_item_type IS NOT NULL
  )
  AND wfn.end_date IS NULL
  AND we.end_date IS NULL
  AND NOT EXISTS (
    SELECT 
      1
    FROM 
      wf_items wp,
      po_requisition_headers_all p
    WHERE 
      wp.item_key = we.parent_item_key
      AND wp.item_type = we.parent_item_type
      AND wp.end_date IS NULL
      AND p.wf_item_type = wp.item_type
      AND P.WF_ITEM_KEY = WP.ITEM_KEY
  )
ORDER BY 
  weias.notification_id DESC',
      p_title                  => 'Requisition Approval Workflow (REQAPPRV or Custom) has open POERROR or WFERROR child workflow(s)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'When attempting to purge closed Requisition approval workflow(s) by running Purge Obsolete Workflow Runtime Data (FNDWFPR), the workflow(s) do not (will not) get purged.  There are open POERROR or WFERROR child workflow(s) associated to the requisition approval (REQAPPRV or custom) workflow(s).  This condition will prevent purge of the corresponding requisition approval (REQAPPRV) workflow(s).',
      p_solution               => '<p>There are open POERROR or WFERROR child workflow(s) associated to the requisition approval (REQAPPRV or custom) workflow(s). After troubleshooting the cause of the POERROR or WFERROR errors, you may request from Support a datafix to purge the open POERROR or WFERROR workflows.</p>
<p>REFERENCE: [1666857/KB386049] </p>',
      p_success_msg            => 'There are no open POERROR or WFERROR workflows found for the seeded REQAPPRV (or custom) requisition workflows, so the issue described in [1666857/KB386049] is not an issue in this instance.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_APPRVL_REQ_APPROVAL_WORKFLOW_HAS_OPEN_POERROR_OR_WFERROR_CHILD_WORKFLOW');



