debug('begin add_signature: PO_WORKFLOW_APPROVAL_MODE');
   l_info('##MASK##SETTING_LEVEL'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1698',
      p_sig_id                 => 'PO_WORKFLOW_APPROVAL_MODE',
      p_sig_sql                => 'SELECT pov.setting_level,
           pov.option_value
    FROM (
           SELECT ''10001-Site'' Setting_Level,
                  nvl(profile_option_value,''BACKGROUND'') Option_Value
           FROM fnd_profile_option_values v,
                fnd_profile_options o
           WHERE o. profile_option_name = ''PO_WORKFLOW_APPROVAL_MODE''
           AND   v.profile_option_id (+) = o.profile_option_id
           AND   v.application_id (+) = o.application_id
           AND   v.level_id (+) = 10001
           AND   nvl(v.profile_option_value,''BACKGROUND'') = ''BACKGROUND''
           UNION
           SELECT decode(v.level_id,
                    10002, ''10002-Appl: ''||a.application_name,
                    10003, ''10003-Resp: ''||r.responsibility_name,
                    10004, ''10004-User: ''||u.user_name),
                  v.profile_option_value
           FROM fnd_profile_option_values v,
                fnd_profile_options o,
                fnd_application_vl a,
                fnd_responsibility_vl r,
                fnd_user u
           WHERE o. profile_option_name = ''PO_WORKFLOW_APPROVAL_MODE''
           AND   v.profile_option_value = ''BACKGROUND''
           AND   v.level_id IN (10002,10003,10004)
           AND   v.level_value = decode(v.level_id,
                   10004, u.user_id, 10003, r.responsibility_id,
                   10002, a.application_id, -1)
           AND   v.profile_option_id = o.profile_option_id
           AND   v.application_id = o.application_id
           AND   a.application_id (+) = v.level_value
           AND   r.responsibility_id (+) = v.level_value
           AND   u.user_id (+) = v.level_value
         ) pov
    WHERE (NOT EXISTS (
            SELECT 1
            FROM fnd_concurrent_requests r,
                 fnd_concurrent_programs p
            WHERE p.concurrent_program_name = ''FNDWFBG''
            AND   p.application_id = 0
            AND   r.program_application_id = p.application_id
            AND   r.concurrent_program_id = p.concurrent_program_id
            AND   nvl(r.phase_code,''P'') <> ''C''
            AND   nvl(r.resubmit_interval,-1) > 0
            AND   nvl(r.resubmit_end_date, sysdate+1) >= sysdate
            AND   nvl(r.argument1,''POAPPRV'') = ''POAPPRV'') OR
           NOT EXISTS (
            SELECT 1
            FROM fnd_concurrent_requests r,
                 fnd_concurrent_programs p
            WHERE p.concurrent_program_name = ''FNDWFBG''
            AND   p.application_id = 0
            AND   r.program_application_id = p.application_id
            AND   r.concurrent_program_id = p.concurrent_program_id
            AND   nvl(r.phase_code,''P'') <> ''C''
            AND   nvl(r.resubmit_interval,-1) > 0
            AND   nvl(r.resubmit_end_date, sysdate+1) >= sysdate
            AND   nvl(r.argument1,''REQAPPRV'') = ''REQAPPRV''))
    ORDER BY 1,2',
      p_title                  => 'PO:Workflow Processing Mode Set to Background',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The profile option PO:Workflow Processing Mode is Set to "Background"
    at some level, and there is no "Workflow Background Process"
    concurrent program scheduled, either for Purchase Orders or
    Requisitions',
      p_solution               => '<ul>
<li>Review the settings indicated above</li>
<li>Either change these settings to "Online" OR </li>
<li>Insure that the concurrent program "Workflow Background Process"
    is scheduled to run regularly for the "PO Approval" and
    "PO Requisition Approval" item types.</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: PO_WORKFLOW_APPROVAL_MODE');



debug('begin add_signature: P2P_CREATEPO_ATTRIBUTES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '2553',
      p_sig_id                 => 'P2P_CREATEPO_ATTRIBUTES',
      p_sig_sql                => 'SELECT              rtrim(w.name) name, 
                        w.text_default Value, 
                        rtrim(w.item_type) item_type, 
                        ''Should Workflow Create The Release?'' Attribute
                  from   wf_item_attributes w
                  where  w.NAME = ''CONT_WF_FOR_AC_REL_GEN''
                  and item_type = ''CREATEPO''
                  union  
                  select rtrim(w.name) name, 
                        w.text_default Value, 
                        rtrim(w.item_type) item_type, 
                        ''Is Automatic Creation Allowed?'' Attribute
                  from wf_item_attributes w
                  where w.NAME = ''AUTOCREATE_DOC''
                  and item_type = ''CREATEPO''
                  union 
                  select rtrim(w.name) name, 
                        w.text_default Value, 
                        rtrim(w.item_type) item_type, 
                        ''Is Automatic Approval Allowed?'' Attribute
                  from   wf_item_attributes w
                  where  w.NAME = ''AUTO_APPROVE_DOC''
                  and item_type = ''CREATEPO''',
      p_title                  => 'CREATEPO Attributes Details',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'CREATEPO Attributes not all set to yes.',
      p_solution               => '<ul>
      <li> 1) if you want both Std POs or Blanket Releases created automatically, you have to have the following set to Y :   Is 
      Automatic Creation Allowed?  and Should Workflow Create The Release? </li>
      <li> 2) If you want Std POs created automatically but you dont want Blanekt Releases created automatically, you need to set  Is 
      Automatic Creation Allowed?  = Y  and Should Workflow Create The Release? = N </li>
      <li> 3) If you dont want any documents created automatically set them both to N  </li>
      <li> 4) Unfortunately, if you want Blanket Releases created automatically but you dont want Standard POs, its not possible.  This 
      would be setting Is Automatic Creation Allowed? = N and once that happens the worklfow ends without getting to 
      Should Workflow Create The Release?  </li>
      <li> 5) The last part is the automatic approval, which is an all or nothing setting (for Std POs and Blkt Releases) -- if you want  
       automatically created documents automatically submitted for approval, then set Is Automatic Approval Allowed? = Y , if  
       not set it to N (some customers dont want these created POs automatically submitted for approval)  </li>
   </ul>

See [460003/KB273172] and [830933/KB269563] for further details.',
      p_success_msg            => 'All CREATEPO attributes have been defined.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: P2P_CREATEPO_ATTRIBUTES');



