      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: Note312582.1_SINGLE');



debug('begin add_signature: B2B_DROP_SHIP_SUPPLY_SOURCE_TYPE_INCORRECT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '21043',
      p_sig_id                 => 'B2B_DROP_SHIP_SUPPLY_SOURCE_TYPE_INCORRECT',
      p_sig_sql                => 'SELECT prha.requisition_header_id, prla.requisition_line_id, pha.po_header_id, plla.po_line_id, 
mttreqline.supply_source_header_id mtl_supply_headerid,
mttreqline.supply_source_line_id mtl_supply_lineid, 
mttreqline.supply_source_type_id
FROM po_headers_all pha,
po_line_locations_all plla,
po_requisition_lines_all prla,
po_requisition_headers_all prha
,
(
select mtt.supply_source_header_id, mtt.supply_source_line_id, mtt.supply_source_type_id
from mtl_reservations mtt
where mtt.supply_source_header_id is not null and mtt.SUPPLY_SOURCE_TYPE_ID = ''1''  --should be 17 for Req
) mttreqline
WHERE 
   mttreqline.supply_source_line_id = NVL(prla.requisition_line_id, mttreqline.supply_source_line_id)
   and mttreqline.supply_source_header_id = prha.requisition_header_id
and 
pha.po_header_id = plla.po_header_id
and plla.line_location_id = prla.line_location_id
AND prla.requisition_header_id =
prha.requisition_header_id
AND (prha.interface_source_code = ''CTO''
OR nvl(plla.drop_ship_flag, ''N'') = ''Y'')
AND nvl(plla.cancel_flag,''N'') = ''N''
AND pha.po_header_id = ##$$DOCID$$##
AND ''PO'' = ''##$$DOCTYPESHORT$$##''',
      p_title                  => 'Back-to-Back (B2B) Drop Ship Order Has Incorrect Source Type',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Back-to-Back (B2B) Drop Ship Purchase Order Has Incorrect Source Type in MTL Supply.  This will cause Document Manager error 3 in approval as described in [1914523/KB856617]',
      p_solution               => 'Apply the patch fix from [1915537/KB670218] to prevent the issue from occurring again on Back-to-Back (B2B) Drop Ship Orders.

For a DATAFIX for the existing B2B Drop Ship Order, reset the supply source type to the correct type.  Review and implement the DATAFIX solution from [1914523/KB856617].',
      p_success_msg            => 'Back-to-Back (B2B) Drop Ship PO Has Correct Source Type in MTL Supply',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: B2B_DROP_SHIP_SUPPLY_SOURCE_TYPE_INCORRECT');



debug('begin add_signature: NOTE867855.1_REL');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '9256',
      p_sig_id                 => 'NOTE867855.1_REL',
      p_sig_sql                => 'SELECT ''Blanket Release'' Transaction_Type,
poh.segment1 PO_Number,
pr.release_num Release_Num,
pr.org_id Organization_Id,
pr.authorization_status Authorization_Status
FROM wf_item_attribute_values wiav,
wf_item_attributes wia,
wf_items wfi,
wf_notifications wfn,
po_headers_all poh,
po_releases_all pr,
all_source als
WHERE wiav.item_type in (''REQAPPRV'', ''POAPPRV'')
AND wia.item_type = wiav.item_type
AND wia.name = wiav.name
AND wiav.name = ''SYSADMIN_ERROR_MSG''
AND wia.type <> ''EVENT''
AND wiav.item_key = wfi.parent_item_key
AND wfi.item_type = ''POERROR''
AND wfi.item_key = wfn.item_key
AND wfn.status = ''OPEN''
AND wfn.message_type = ''POERROR''
AND wfn.message_name = ''DOC_MANAGER_FAILED''
AND poh.po_header_id = pr.po_header_id
AND pr.wf_item_type = wiav.item_type
AND pr.wf_item_key = wiav.item_key
AND pr.authorization_status IN (
''IN PROCESS'', ''PRE-APPROVED'')
/* Base script ends, specific checks for this error follow */
AND wiav.text_value like
''po.plsql.PO_DOCUMENT_ACTION_CLOSE.auto_update_close_status:30:''||
''100ORA-01403: no data found%''||
''po.plsql.PO_DOCUMENT_ACTION_CLOSE.auto_close_po:120:''||
''unexpected error in updating closed status%''||
''po.plsql.PO_DOCUMENT_ACTION_PVT.do_action:110:''||
''unexpected error in action call''
AND ((''12.1'' = substr(''##$$REL$$##'',1,4) AND
FND_IREP_LOADER_PRIVATE.compare_versions(
substr(substr(als.text,regexp_instr(als.text,'' *[0-9]'',1,1,1)-1),
1, instr(substr(als.text,regexp_instr(als.text,'' *[0-9]'',1,1,1) - 1),
'' '',1,1)-1),
''120.9.12010000.3'') = ''<'' ) OR
(''12.0'' = substr(''##$$REL$$##'',1,4) AND
FND_IREP_LOADER_PRIVATE.compare_versions(
substr(substr(als.text,regexp_instr(als.text,'' *[0-9]'',1,1,1)-1),
1, instr(substr(als.text,regexp_instr(als.text,'' *[0-9]'',1,1,1)-1),
'' '',1,1)-1),
''120.9.12000000.3'') = ''<'' ))
AND als.type = ''PACKAGE BODY''
AND als.name = ''PO_DOCUMENT_ACTION_CLOSE''
AND als.text like ''%$Header%''
AND pr.po_release_id = ##$$DOCID$$##',
      p_title                  => 'Release stuck with Error in auto_update_close_status:30:100 ORA-1403',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'This release are stuck in the approval process and failing with error in auto_update_close_status:30:100ORA-01403 and auto_close_po:120 ',
      p_solution               => '<ul>
<li>Please apply {8566664}</li>
<li>To resubmit the document that is in error follow instructions in [312582/KB306833]</li>
<li>Source KB Article: [867855/KB459992]</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: NOTE867855.1_REL');



debug('begin add_signature: Note390023.1_case_GEN2');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Bug Number'):= '14254641';
   l_info('Doc ID'):= '1487949.1';
  add_signature(
      p_sig_repo_id            => '1718',
      p_sig_id                 => 'Note390023.1_case_GEN2',
      p_sig_sql                => 'SELECT count(*) cnt
    FROM (
           SELECT 1
           FROM (
                  SELECT bug_number FROM ad_bugs
                  UNION
                  SELECT patch_name FROM ad_applied_patches
                ) bugs
           WHERE bugs.bug_number = ''14254641''
           AND   ''##$$REL$$##'' = ''12.1.3''
           UNION
           SELECT 1 FROM dual WHERE ''##$$REL$$##'' like ''12.2%''
