debug('begin add_signature: Note390023.1_case_GEN4');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1761',
      p_sig_id                 => 'Note390023.1_case_GEN4',
      p_sig_sql                => 'SELECT ''PO/PA'' "Doc Type",
           h.segment1 "Doc Number",
           h.po_header_id "Doc ID",
           h.org_id,
           null "Release Num",
           null "PO Release ID",
           h.type_lookup_code "Type Code",
           h.authorization_status "Authorization Status",
           nvl(h.cancel_flag,''N'') canceled,
           nvl(h.closed_code,''OPEN'') "Closed Code",
           h.change_requested_by "Change Requested By",
           h.revision_num,
           h.wf_item_type, h.wf_item_type "##$$FK1$$##",
           h.wf_item_key, h.wf_item_key "##$$FK2$$##",
           h.approved_date "Approved Date"
    FROM po_headers_all h
    WHERE to_date(''##$$FDATE$$##'') <= (
            SELECT max(ah.action_date) FROM po_action_history ah
            WHERE ah.object_id = h.po_header_id
            AND   ah.object_type_code IN (''PO'',''PA'')
            AND   ah.action_code = ''SUBMIT''
            AND   ah.object_sub_type_code = h.type_lookup_code)
    AND   h.org_id = ##$$ORGID$$##
    AND   h.authorization_status IN (''IN PROCESS'', ''PRE-APPROVED'')
    AND   nvl(h.cancel_flag,''N'') <> ''Y''
    AND   nvl(h.closed_code,''OPEN'') <> ''FINALLY CLOSED''
    AND   nvl(h.change_requested_by,''NONE'') NOT IN (''REQUESTER'',''SUPPLIER'')
    AND   (nvl(h.ENCUMBRANCE_REQUIRED_FLAG, ''N'') <> ''Y'' OR
           h.type_lookup_code <> ''BLANKET'')
    AND   NOT EXISTS (
            SELECT null
            FROM wf_item_activity_statuses ias,
                 wf_notifications n
            WHERE ias.notification_id is not null
            AND   ias.notification_id = n.group_id
            AND   n.status = ''OPEN''
            AND   ias.item_type = ''POAPPRV''
            AND   ias.item_key IN (
                    SELECT i.item_key FROM wf_items i
                    START WITH i.item_type = ''POAPPRV''
                    AND        i.item_key = h.wf_item_key
                    CONNECT BY PRIOR i.item_type = i.parent_item_type
                    AND        PRIOR i.item_key = i.parent_item_key
                    AND     nvl(i.end_date,sysdate+1) >= sysdate))
    AND   NOT EXISTS (
            SELECT 1
            FROM po_lines_all l,
                 po_line_locations_all s,
                 po_distributions_all d
            WHERE  s.line_location_id = d.line_location_id
            AND   l.po_line_id = s.po_line_id
            AND   d.po_header_id = h.po_header_id
            AND   l.matching_basis = ''QUANTITY''
            AND   nvl(d.encumbered_flag, ''N'') = ''Y''
            AND   nvl(s.cancel_flag, ''N'') = ''N''
            AND   nvl(s.closed_code, ''OPEN'') <> ''FINALLY CLOSED''
            AND   nvl(d.prevent_encumbrance_flag, ''N'') = ''N''
            AND   d.budget_account_id IS NOT NULL
            AND   nvl(s.shipment_type,''BLANKET'') = ''STANDARD''
            AND   round(nvl(d.encumbered_amount, 0), 2) <>
                    round((s.price_override * d.quantity_ordered *
                    nvl(d.rate, 1) + nvl(d.nonrecoverable_tax, 0) *
                    nvl(d.rate, 1)), 2)
            UNION
            SELECT 1
            FROM po_lines_all l,
                 po_line_locations_all s,
                 po_distributions_all d
            WHERE  s.line_location_id = d.line_location_id
            AND   l.po_line_id = s.po_line_id
            AND   d.po_header_id = h.po_header_id
            AND   l.matching_basis = ''AMOUNT''
            AND   nvl(d.encumbered_flag, ''N'') = ''Y''
            AND   nvl(s.cancel_flag, ''N'') = ''N''
            AND   nvl(s.closed_code, ''OPEN'') <> ''FINALLY CLOSED''
            AND   nvl(d.prevent_encumbrance_flag, ''N'') = ''N''
            AND   d.budget_account_id IS NOT NULL
            AND   nvl(s.shipment_type,''BLANKET'') = ''STANDARD''
            AND   round(nvl(d.encumbered_amount, 0), 2) <>
                    round((d.amount_ordered +
                    nvl(d.nonrecoverable_tax, 0)) *
                    nvl(d.rate, 1), 2))
    AND   NOT EXISTS (
            SELECT 1
            FROM po_lines_all l,
                 po_line_locations_all s,
                 po_distributions_all d
            WHERE  s.line_location_id = d.line_location_id
            AND   l.po_line_id = s.po_line_id
            AND   d.po_header_id = h.po_header_id
            AND   nvl(d.encumbered_flag, ''N'') = ''Y''
            AND   nvl(d.prevent_encumbrance_flag, ''N'') = ''N''
            AND   d.budget_account_id IS NOT NULL
            AND   nvl(s.shipment_type,''BLANKET'') = ''PLANNED'')
    UNION
    SELECT ''RELEASE'',
           h.segment1,
           h.po_header_id,
           h.org_id,
           r.release_num,
           r.po_release_id,
           r.release_type,
           r.authorization_status,
           nvl(r.cancel_flag,''N'') canceled,
           nvl(r.closed_code,''OPEN'') closed_code,
           r.change_requested_by,
           r.revision_num,
           r.wf_item_type, r.wf_item_type "##$$FK1$$##",
           r.wf_item_key, r.wf_item_key "##$$FK2$$##",
           r.approved_date
    FROM po_headers_all h,
         po_releases_all r
    WHERE to_date(''##$$FDATE$$##'') <= (
            SELECT max(ah.action_date) FROM po_action_history ah
            WHERE ah.object_id = r.po_release_id
            AND   ah.object_type_code = ''RELEASE''
            AND   ah.action_code = ''SUBMIT''
            AND   ah.object_sub_type_code = r.release_type)
    AND   h.org_id = ##$$ORGID$$##
    AND   r.po_header_id = h.po_header_id
    AND   r.org_id = h.org_id
    AND   r.authorization_status IN (''IN PROCESS'',''PRE-APPROVED'')
    AND   nvl(r.cancel_flag,''N'') <> ''Y''
    AND   nvl(r.closed_code,''OPEN'') <> ''FINALLY CLOSED''
    AND   nvl(r.change_requested_by,''NONE'') NOT IN (''REQUESTER'',''SUPPLIER'')
    AND   NOT EXISTS (
            SELECT null
            FROM wf_item_activity_statuses ias,
                 wf_notifications          n
            WHERE ias.notification_id is not null
            AND   ias.notification_id = n.group_id
            AND   n.status = ''OPEN''
            AND   ias.item_type = ''POAPPRV''
            AND   ias.item_key = r.wf_item_key)
    UNION
    SELECT ''REQUISITION'',
           h.segment1,
           h.requisition_header_id,
           h.org_id,
           null,
           null,
           h.type_lookup_code,
           h.authorization_status,
           nvl(h.cancel_flag,''N'') canceled,
           nvl(h.closed_code,''OPEN'') closed_code,
           null,
           null,
           h.wf_item_type, h.wf_item_type "##$$FK1$$##",
           h.wf_item_key, h.wf_item_key "##$$FK2$$##",
           h.approved_date
    FROM po_requisition_headers_all h
    WHERE to_date(''##$$FDATE$$##'') <= (
            SELECT max(ah.action_date) FROM po_action_history ah
            WHERE ah.object_id = h.requisition_header_id
            AND   ah.object_type_code = ''REQUISITION''
            AND   ah.action_code = ''SUBMIT''
            AND   ah.object_sub_type_code = h.type_lookup_code)
    AND   h.org_id = ##$$ORGID$$##
    AND   h.authorization_status IN (''IN PROCESS'', ''PRE-APPROVED'')
    AND   nvl(h.cancel_flag,''N'') <> ''Y''
    AND   nvl(h.closed_code,''OPEN'') <> ''FINALLY CLOSED''
    AND   nvl(transferred_to_oe_flag,''N'') <> ''Y''
    AND   NOT EXISTS (
            SELECT 1 FROM po_requisition_lines_all rl
            WHERE  rl.requisition_header_id = h.requisition_header_id
            AND    rl.line_location_id is not null)
    AND   NOT EXISTS (
            SELECT null
            FROM wf_item_activity_statuses ias,
                 wf_notifications n
            WHERE ias.notification_id is not null
            AND   ias.notification_id = n.group_id
            AND   n.status = ''OPEN''
            AND   ias.item_type = ''REQAPPRV''
            AND   ias.item_key IN (
                    SELECT i.item_key FROM wf_items i
                    START WITH i.item_type = ''REQAPPRV''
                    AND        i.item_key = h.wf_item_key
                    CONNECT BY PRIOR i.item_type = i.parent_item_type
                    AND        PRIOR i.item_key = i.parent_item_key
                    AND        nvl(i.end_date,sysdate+1) >= sysdate))
    AND   NOT EXISTS (
            SELECT 1
            FROM po_requisition_lines_all l,
                 po_req_distributions_all d
            WHERE l.requisition_header_id = h.requisition_header_id
            AND   d.requisition_line_id = l.requisition_line_id
            AND   l.matching_basis = ''QUANTITY''
            AND   nvl(d.encumbered_flag, ''N'') = ''Y''
            AND   nvl(l.cancel_flag, ''N'') = ''N''
            AND   nvl(l.closed_code, ''OPEN'') <> ''FINALLY CLOSED''
            AND   nvl(d.prevent_encumbrance_flag, ''N'') = ''N''
            AND   d.budget_account_id IS NOT NULL
            AND   round(nvl(d.encumbered_amount, 0), 2) <>
                    round(l.unit_price * d.req_line_quantity +
                    nvl(d.nonrecoverable_tax, 0), 2)
            UNION
            SELECT 1
            FROM po_requisition_lines_all l,
                 po_req_distributions_all d
            WHERE l.requisition_header_id = h.requisition_header_id
            AND   d.requisition_line_id = l.requisition_line_id
            AND   l.matching_basis = ''AMOUNT''
            AND   nvl(d.encumbered_flag, ''N'') = ''Y''
            AND   nvl(l.cancel_flag, ''N'') = ''N''
            AND   nvl(l.closed_code, ''OPEN'') <> ''FINALLY CLOSED''
            AND   nvl(d.prevent_encumbrance_flag, ''N'') = ''N''
            AND   d.budget_account_id IS NOT NULL
            AND   round(nvl(d.encumbered_amount, 0), 2) <>
                    round(d.req_line_amount +
                    nvl(d.nonrecoverable_tax, 0), 2))
    ORDER BY 1,2',
      p_title                  => 'Recent Documents - Candidates for Reset',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Recent documents exist which are candidates for reset.  The documents
    listed are all IN PROCESS or PRE-APPROVED approval status
    and do not have an open workflow notification.',
      p_solution               => '<ul><li>Review the results in the Workflow Activity section
         for the documents.</li>
      <li>If multiple documents are stuck with errors in the same
         workflow activity then try the Mass Retry in [458216/KB725430].</li>
      <li>For all other document see [390023/KB627850] for details on
         how to reset these documents if needed.</li>
      <li>To obtain a summary count for all such documents in your 
         system by document type, refer to [1584264/KB398941]</li></ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL('Note390023.1_case_GEN4_CHILD1','Note390023.1_case_GEN4_CHILD2'),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '11'
      );
   l_info.delete;
debug('end add_signature: Note390023.1_case_GEN4');



debug('begin add_signature: EBS_MFG_PO_APPRVL_SUMMARY_ITEM_TYPE_PARENT_ITEM_TYPE_COUNT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '30276',
      p_sig_id                 => 'EBS_MFG_PO_APPRVL_SUMMARY_ITEM_TYPE_PARENT_ITEM_TYPE_COUNT',
      p_sig_sql                => 'select wi.item_type "ITEM TYPE", wit.display_name "DISPLAY NAME", wi.PARENT_ITEM_TYPE "PARENT ITEM TYPE", nvl(to_char(wi.end_date, ''YYYY''),''OPEN'') "CLOSED",
	to_char(count(wi.item_key),''999,999,999,999'') "COUNT"
	from wf_items wi, wf_item_types_tl wit
	where wi.item_type = wit.name
	and wit.language = ''US''
	and (wi.item_type in (''POAPPRV'',''REQAPPRV'',''POXML'',''POWFRQAG'',''PORCPT'',''APVRMDER'',''PONPBLSH'',''POSPOACK'',''PONAUCT'',''PORPOCHA'',''PODSNOTF'',''POSREGV2'',''POREQCHA'',''POWFPOAG'',''POSCHORD'',''POSASNNB'',''PONAPPRV'',''POSCHPDT'',''POAUTH'',''POWFDS'',''POERROR'',''POSBPR'',''CREATEPO'')  or (wi.item_type like ''%ERROR%'' and wi.parent_item_type in (''POAPPRV'',''REQAPPRV'',''POXML'',''POWFRQAG'',''PORCPT'',''APVRMDER'',''PONPBLSH'',''POSPOACK'',''PONAUCT'',''PORPOCHA'',''PODSNOTF'',''POSREGV2'',''POREQCHA'',''POWFPOAG'',''POSCHORD'',''POSASNNB'',''PONAPPRV'',''POSCHPDT'',''POAUTH'',''POWFDS'',''POERROR'',''POSBPR'',''CREATEPO'')))
	group by wi.item_type, wit.display_name, wi.parent_item_type, to_char(wi.end_date, ''YYYY'')
	order by to_char(wi.end_date, ''YYYY'')',
      p_title                  => 'SUMMARY of All PO Workflow Processes - Item Type & Parent Item Type Count',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'SUMMARY of All PO Workflow Processes By Item Type & Parent',
      p_solution               => 'Summarized list of seeded workflow processes',
      p_success_msg            => 'No data found',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_PO_APPRVL_SUMMARY_ITEM_TYPE_PARENT_ITEM_TYPE_COUNT');



debug('begin add_signature: EBS_MFG_PO_APPRVL_SUMMARY_ITEM_TYPE_STATUS_COUNT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '30277',
      p_sig_id                 => 'EBS_MFG_PO_APPRVL_SUMMARY_ITEM_TYPE_STATUS_COUNT',
      p_sig_sql                => 'select
	to_char(NUM_ACTIVE,''999,999,999,999'') "ACTIVE",
	to_char(NUM_COMPLETE,''999,999,999,999'') "COMPLETED",
	to_char(NUM_PURGEABLE,''999,999,999,999'') "PURGEABLE",
	WIT.NAME "ITEM TYPE",
	DISPLAY_NAME "DISPLAY NAME",
        PERSISTENCE_TYPE "PERSISTENCE TYPE",
        PERSISTENCE_DAYS "PERSISTENCE DAYS",
	to_char(NUM_ERROR,''999,999,999,999'') "ERRORED",
	to_char(NUM_DEFER,''999,999,999,999'') "DEFERRED",
	to_char(NUM_SUSPEND,''999,999,999,999'') "SUSPENDED"
	from wf_item_types wit, wf_item_types_tl wtl
	where wit.name in (''POAPPRV'',''REQAPPRV'',''POXML'',''POWFRQAG'',''PORCPT'',''APVRMDER'',''PONPBLSH'',''POSPOACK'',''PONAUCT'',''PORPOCHA'',''PODSNOTF'',''POSREGV2'',''POREQCHA'',''POWFPOAG'',''POSCHORD'',''POSASNNB'',''PONAPPRV'',''POSCHPDT'',''POAUTH'',''POWFDS'',''POERROR'',''POSBPR'',''CREATEPO'')
	AND wtl.name = wit.name
	AND wtl.language = userenv(''LANG'')
	AND wit.NUM_ACTIVE is not NULL
	AND wit.NUM_ACTIVE <>0
	order by PERSISTENCE_TYPE, NUM_COMPLETE desc',
      p_title                  => 'SUMMARY of PO Workflow Processes - Item Type & Status Count',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'SUMMARY of PO Workflow Processes - Item Type and Status Count',
      p_solution               => 'Counts of PO Workflows by Item Type and Status',
      p_success_msg            => 'No data found',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_PO_APPRVL_SUMMARY_ITEM_TYPE_STATUS_COUNT');



debug('begin add_signature: EBS_MFG_PO_APPRVL_EXCESSIVE_LOOPING_CHECK');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '30278',
      p_sig_id                 => 'EBS_MFG_PO_APPRVL_EXCESSIVE_LOOPING_CHECK',
      p_sig_sql                => 'select sta.item_type "ITEM_TYPE", sta.item_key "ITEM_KEY",
	to_char(COUNT(*),''999,999,999,999'') "COUNT",
	 TO_CHAR(wfi.begin_date, ''YYYY-MM-DD'') "OPENED", TO_CHAR(wfi.end_date, ''YYYY-MM-DD'') "CLOSED", wfi.user_key "DESCRIPTION"
	 FROM wf_item_activity_statuses_h sta,
	 wf_items wfi WHERE sta.item_type = wfi.item_type AND sta.item_key = wfi.item_key
	 AND wfi.item_type in (''POAPPRV'',''REQAPPRV'',''POXML'',''POWFRQAG'',''PORCPT'',''APVRMDER'',''PONPBLSH'',''POSPOACK'',''PONAUCT'',''PORPOCHA'',''PODSNOTF'',''POSREGV2'',''POREQCHA'',''POWFPOAG'',''POSCHORD'',''POSASNNB'',''PONAPPRV'',''POSCHPDT'',''POAUTH'',''POWFDS'',''POERROR'',''POSBPR'',''CREATEPO'')
	 GROUP BY sta.item_type, sta.item_key, wfi.USER_KEY, TO_CHAR(wfi.begin_date, ''YYYY-MM-DD''),
	 TO_CHAR(wfi.end_date, ''YYYY-MM-DD'')
	 HAVING COUNT(*) > 500
	 ORDER BY COUNT(*) DESC',
