debug('begin add_signature: EBS_MFG_PO_APPRVL_PURCHASING_WORKFLOWS_IN_ERROR');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '30279',
      p_sig_id                 => 'EBS_MFG_PO_APPRVL_PURCHASING_WORKFLOWS_IN_ERROR',
      p_sig_sql                => 'select
rpad(STA.ITEM_TYPE, 17, '' '') "ITEM_TYPE",
rpad(STA.ACTIVITY_RESULT_CODE, 17, '' '') "RESULT",
rpad(PRA.PROCESS_NAME, 30, '' '') "PROCESS_LABEL",
rpad(PRA.INSTANCE_LABEL, 30, '' '') "ACTIVITY_LABEL",
rpad(to_char(COUNT(*),''999,999,999,999''), 20, '' '') "ROWS"
	from  WF_ITEM_ACTIVITY_STATUSES  STA, WF_PROCESS_ACTIVITIES PRA
	where STA.ACTIVITY_STATUS = ''ERROR''
	and STA.PROCESS_ACTIVITY = PRA.INSTANCE_ID
	and STA.ITEM_TYPE in (''POAPPRV'',''REQAPPRV'',''POXML'',''POWFRQAG'',''PORCPT'',''APVRMDER'',''PONPBLSH'',''POSPOACK'',''PONAUCT'',''PORPOCHA'',''PODSNOTF'',''POSREGV2'',''POREQCHA'',''POWFPOAG'',''POSCHORD'',''POSASNNB'',''PONAPPRV'',''POSCHPDT'',''POAUTH'',''POWFDS'',''POERROR'',''POSBPR'',''CREATEPO'')
	group by STA.ITEM_TYPE, STA.ACTIVITY_RESULT_CODE, PRA.PROCESS_NAME, PRA.INSTANCE_LABEL
	order by COUNT(*) desc',
      p_title                  => 'Purchasing Workflows in Error',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are Purchasing Workflows in Error at this time',
      p_solution               => 'You may retry failing PO activities.<br>
See [458216/KB725430] - How To Retry Multiple Errored Approval Workflow Processes After A Fix Or Patch Has Been Implemented.<br>
Also see [947141/KB567388] - How to Mass Retry Errored Workflows?<br>
Run Procurement Analyzers for a specific transaction to get additional details.  The following analyzers are available to gather additional workflow details:<br>
Procurement Approval Analyzer, Procurement Change Request Analyzer, Procurement Sourcing Analyzer, Procurement iSupplier Analyzer.',
