debug('begin add_signature: EBS_MFG_PO_APPRVL_INCOMPLETE_ACTIVITIES_FOR_APPROVED_PO_WORKFLOWS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '30280',
      p_sig_id                 => 'EBS_MFG_PO_APPRVL_INCOMPLETE_ACTIVITIES_FOR_APPROVED_PO_WORKFLOWS',
      p_sig_sql                => 'select i.parent_item_type "PARENT ITEM TYPE", i.item_type "ITEM TYPE",
	to_char(count(i.item_key),''999,999,999,999'') "COUNT"
	  FROM wf_items i,
		   wf_item_activity_statuses ias
	  WHERE i.parent_item_type = ''POAPPRV''
	  AND   i.item_key = ias.item_key
	  AND   i.item_type = ias.item_type
	  AND   i.begin_date <= sysdate
	  AND   ias.activity_status <> ''COMPLETE''
	  AND   parent_item_key IN (
			  SELECT i1.item_key
			  FROM wf_items i1,
				   po_headers_all h
			  WHERE i1.item_key = h.wf_item_key
			  AND   i1.item_type = ''POAPPRV''
			  AND   h.authorization_status NOT IN (''IN PROCESS'',''PRE-APPROVED'')
			  UNION
			  SELECT i1.item_key
			  FROM wf_items i1,
				   po_releases_all r
			  WHERE i1.item_key = r.wf_item_key
			  AND   i1.item_type = ''POAPPRV''
			  AND   r.authorization_status NOT IN (''IN PROCESS'',''PRE-APPROVED''))
	  AND   ias.end_date is null
	  group by i.parent_item_type, i.item_type',
      p_title                  => 'Incomplete Activities for Purchasing Workflows',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Incomplete WF Activities for Child Processes of Approved POs using POAPPRV workflow.',
      p_solution               => 'To troubleshoot further, run this analyzer for a specific document number to see more details about the workflow.',
      p_success_msg            => 'There are no Incomplete WF Activities for Child Processes of Approved POs using POAPPRV workflow.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_PO_APPRVL_INCOMPLETE_ACTIVITIES_FOR_APPROVED_PO_WORKFLOWS');



debug('begin add_signature: EBS_MFG_PO_APPRVL_INCOMPLETE_ACTIVITIES_COUNT');
