debug('begin add_signature: NOTE1304639.1_CASE_4_GEN');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '9231',
      p_sig_id                 => 'NOTE1304639.1_CASE_4_GEN',
      p_sig_sql                => 'SELECT decode(nvl(poh.segment1,''$$$''),''$$$'',
decode(nvl(prh.segment1,''$$$''),''$$$'',''Unknown'',
''Requisition''),
''Purchase Order'') Transaction_Type,
nvl(poh.segment1,prh.segment1) Transaction_Number,
