debug('begin add_signature: DATA_RANGE_POREL7');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Doc ID'):= '756627.1';
  add_signature(
      p_sig_repo_id            => '2273',
      p_sig_id                 => 'DATA_RANGE_POREL7',
      p_sig_sql                => 'SELECT DISTINCT
           h.segment1 "PO_Number",
           h.po_header_id,
           d.rate "PO Dist Rate",
           h.currency_code "PO Currency Code",
           rl.rate "Req Line Rate",
           rl.currency_code "Req Line Currency",
           d.creation_date "PO Dist Creation Date",
           (d.rate/rl.rate) rate_ratio
    FROM po_distributions_all d,
         po_req_distributions_all rd,
         po_requisition_lines_all rl,
         po_headers_all h
    WHERE h.org_id = ##$$ORGID$$##
    AND   h.creation_date >= to_date(''##$$FDATE$$##'')
    AND   d.req_distribution_id = rd.distribution_id
    AND   rl.requisition_line_id = rd.requisition_line_id
    AND   rl.rate / d.rate < 0.5
    AND   h.po_header_id = d.po_header_id
    AND   h.currency_code = rl.currency_code
    ORDER BY rl.currency_code',
      p_title                  => 'Incorrect Rate on Autocreated PO',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Foreign currency autocreated PO''''s using the "Specify" option can result in
     the inverse rate being assigned.  This PO has an incorrect rate assigned.',
      p_solution               => 'Please review [756627/KB650423]. To correct the data please create a Service
     Request with Oracle Support referencing [756627/KB650423] to obtain a fix.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: DATA_RANGE_POREL7');



debug('begin add_signature: DATA_RANGE_POREL8');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Doc ID'):= '1280061.1';
  add_signature(
      p_sig_repo_id            => '2274',
      p_sig_id                 => 'DATA_RANGE_POREL8',
      p_sig_sql                => 'SELECT pod.po_header_id,
           poh.segment1 po_number,
           poll.line_location_id,
           poll.ship_to_organization_id,
           pod.po_distribution_id,
           pod.destination_organization_id,
           null supply_source_id,
           null to_organization_id
    FROM po_distributions_all pod,
         po_line_locations_all poll,
         po_headers_all poh
    WHERE poh.org_id = ##$$ORGID$$##
    AND   poh.creation_date >= to_date(''##$$FDATE$$##'')
    AND   poh.po_header_id = poll.po_header_id
    AND   pod.line_location_id = poll.line_location_id
    AND   pod.po_header_id = poll.po_header_id
    AND   pod.destination_organization_id != poll.ship_to_organization_id
    AND   nvl(poll.closed_code,''OPEN'') != ''FINALLY CLOSED''
    AND   nvl(poll.cancel_flag,''N'') != ''Y''
    UNION
    SELECT poh.po_header_id,
           poh.segment1,
           poll.line_location_id,
           poll.ship_to_organization_id,
           null,
           null,
           mtl.supply_source_id,
           mtl.to_organization_id
    FROM mtl_supply mtl,
         po_line_locations_all poll,
         po_headers_all poh
    WHERE poh.org_id = ##$$ORGID$$##
    AND   poh.creation_date >= to_date(''##$$FDATE$$##'')
    AND   mtl.supply_type_code = ''PO''
    AND   mtl.po_line_location_id = poll.line_location_id
    AND   mtl.po_header_id = poll.po_header_id
    AND   mtl.to_organization_id != poll.ship_to_organization_id
    AND   nvl(poll.closed_code,''OPEN'') != ''FINALLY CLOSED''
    AND   nvl(poll.cancel_flag,''N'') != ''Y''
    AND   poh.po_header_id = poll.po_header_id',
      p_title                  => 'Ship To Organization Mismatch',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The ship to organization on the PO does not match the deliver to organization on the distributions or in mtl_supply.<br> 
This can cause approved PO''''s not to be displayed in Inventory''''s Supply/Demand Detail window.',
      p_solution               => 'Please review [1280061/KB566661].<br>
To correct the data or if you need any other assistance implementing the solution, please create a Service Request with Purchase Order team referencing [1280061/KB566661].',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: DATA_RANGE_POREL8');



debug('begin add_signature: DATA_RANGE_REQ1');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Doc ID'):= '415151.1';
   l_info('Script Name'):= 'poxrqesf.sql';
  add_signature(
      p_sig_repo_id            => '2275',
      p_sig_id                 => 'DATA_RANGE_REQ1',
      p_sig_sql                => 'SELECT prl.requisition_header_id,
           prl.requisition_line_id,
           pll.line_location_id,
           prl.modified_by_agent_flag,
           prl.cancel_flag,
           prl.source_type_code
    FROM po_requisition_lines_all prl,
         po_line_locations_all pll
    WHERE prl.org_id = ##$$ORGID$$##
    AND   prl.creation_date >= to_date(''##$$FDATE$$##'')
    AND   prl.line_location_id = pll.line_location_id
    AND   pll.approved_flag = ''Y''
    AND   nvl(prl.cancel_flag,''N'') = ''N''
    AND   nvl(prl.modified_by_agent_flag,''N'') = ''N''
    AND   EXISTS (
            SELECT 1 FROM mtl_supply
            WHERE prl.requisition_line_id = supply_source_id
            AND   supply_type_code = ''REQ'')
    UNION ALL
    SELECT prl.requisition_header_id,
           prl.requisition_line_id,
           to_number(NULL) line_location_id,
           prl.modified_by_agent_flag,
           prl.cancel_flag,
           prl.source_type_code
    FROM po_requisition_lines_all prl
    WHERE prl.org_id = ##$$ORGID$$##
    AND   prl.creation_date >= to_date(''##$$FDATE$$##'')
    AND   (nvl(prl.cancel_flag,''N'') = ''Y'' OR
           (prl.cancel_flag = ''N'' AND
            prl.modified_by_agent_flag = ''Y''))
    AND   EXISTS (
              SELECT 1 FROM mtl_supply
              WHERE prl.requisition_line_id = supply_source_id
              AND   supply_type_code = ''REQ'')
    UNION ALL
    SELECT req_header_id,
           req_line_id,
           NULL,
           NULL,
           NULL,
           NULL
    FROM mtl_supply ms
    WHERE ms.supply_type_code = ''REQ''
    AND   ms.supply_source_id NOT IN (
            SELECT prl.requisition_line_id
            FROM po_requisition_lines_all prl)
    AND   ms.creation_date  >= to_date(''##$$FDATE$$##'')',
      p_title                  => 'Invalid Supply/Demand for Requisition Lines',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'These documents have canceled or modified or missing
     requisition lines with invalid supply existing in the
     mtl_supply table.',
      p_solution               => 'Follow the solution instructions provided in [415151/KB775383]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: DATA_RANGE_REQ1');



debug('begin add_signature: DATA_RANGE_REQ2');
