debug('begin add_signature: UPGRADE_ALL');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Doc ID'):= '1532406.1';
  add_signature(
      p_sig_repo_id            => '2278',
      p_sig_id                 => 'UPGRADE_ALL',
      p_sig_sql                => 'SELECT  wiav.item_type,
            wiav.item_key,
            wiav.NAME,
            wiav.text_value
     FROM   wf_item_attribute_values wiav,
            WF_ITEM_ACTIVITY_STATUSES wias
     WHERE  wiav.NAME IN (''PO_REQ_APPROVE_MSG'',
                     ''PO_REQ_APPROVED_MSG'',
                     ''PO_REQ_NO_APPROVER_MSG'',
                     ''PO_REQ_REJECT_MSG'',
                     ''REQ_LINES_DETAILS'',
                     ''PO_LINES_DETAILS'')
            AND (wiav.text_value LIKE ''PLSQL:%POAPPRV%''
                  OR wiav.text_value LIKE ''PLSQL:%REQAPPRV%'')
            AND wiav.item_key = wias.item_key
            AND wiav.item_type = wias.item_type
            AND wias.notification_id IN (SELECT notification_id FROM wf_notifications
                                        WHERE message_type IN (''POAPPRV'',''REQAPPRV'')
                                        AND status <> ''CLOSED'')
            AND wias.begin_date >= to_date(''##$$FDATE$$##'')',
      p_title                  => 'Documents with active revisions created before upgrade',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'These documents have pending revisions that have been created and not closed before the upgrade.',
      p_solution               => 'Follow the solution instructions provided in [1532406/KB510962]',
      p_success_msg            => '',
