debug('begin add_signature: EBS_MFG_GINV_ENABLED_VIA_PROFILES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '25892',
      p_sig_id                 => 'EBS_MFG_GINV_ENABLED_VIA_PROFILES',
      p_sig_sql                => 'select NumGinvProfiles from
(select count(*) NumGinvProfiles from
(
select distinct(abc.profile_name) "G Invoicing Profile", 
CASE WHEN min(concat(concat(proflevel,''-''),levelvalue)) <> ''-''
THEN min(concat(concat(proflevel,''-''),levelvalue))
ELSE null
END LevelValue
from
(
   SELECT fpo.profile_option_id prof_option_id,
       SUBSTR (fpot.user_profile_option_name, 0, 50) profile_name, '''' profvalue, '''' proflevel, '''' levelvalue
  FROM fnd_profile_options_tl fpot,
       fnd_profile_options fpo
 WHERE ((fpot.user_profile_option_name = ''G-Invoicing Integration Admin'') 
     or (fpot.user_profile_option_name = ''G-Invoicing Integrating System Id'')
     or (fpot.user_profile_option_name = ''G-Invoicing Service Host'')
     or (fpot.user_profile_option_name = ''G-Invoicing Service Path'')
     or (fpot.user_profile_option_name = ''G-Invoicing Service Version''))
AND fpot.language = ''US''
 AND fpo.profile_option_name = fpot.profile_option_name
 AND not exists (select level_id from fnd_profile_option_values fpov where fpov.profile_option_id = fpo.profile_option_id)

UNION ALL

SELECT fpo.profile_option_id prof_option_id,
       SUBSTR (fpot.user_profile_option_name, 0, 50) profile_name,
(CASE WHEN
      (SUBSTR (fpot.user_profile_option_name, 0, 50) like ''G-Invoicing Service Host%''
OR SUBSTR (fpot.user_profile_option_name, 0, 50) like ''G-Invoicing Service Path%''
OR SUBSTR (fpot.user_profile_option_name, 0, 50) like ''G-Invoicing Integration Admin%''
OR SUBSTR (fpot.user_profile_option_name, 0, 50) like ''G-Invoicing Integrating System Id%''
     )
    THEN rpad   (substr(SUBSTR (fpov.profile_option_value, 0, 450), 1,      ceil(length(SUBSTR (fpov.profile_option_value, 0, 450))*0.25) ),     length(SUBSTR (fpov.profile_option_value, 0, 450)), ''*'')
    ELSE SUBSTR (fpov.profile_option_value, 0, 450)
    END) ProfValue,
DECODE (fpov.level_id,
               10001, ''Site'',
               10002, ''Application'',
               10003, ''Responsibility'',
               10004, ''User''
              ) "ProfLevel",
DECODE (fpov.level_id,
               10001, TO_CHAR (fpov.level_value),
               10002, fa2.application_short_name,
               10003, frt.responsibility_name,
               10004, fu.user_name
              ) "LevelValue"
FROM fnd_profile_options_tl fpot,
       fnd_profile_options fpo,
       fnd_profile_option_values fpov,
       fnd_application fa,
       fnd_application fa2,
       fnd_responsibility_tl frt,
       fnd_user fu
 WHERE ((fpot.user_profile_option_name = ''G-Invoicing Integration Admin'') or (fpot.user_profile_option_name = ''G-Invoicing Integrating System Id'')  or (fpot.user_profile_option_name = ''G-Invoicing Service Host'') or (fpot.user_profile_option_name = ''G-Invoicing Service Path'') or (fpot.user_profile_option_name = ''G-Invoicing Service Version''))
AND fpot.language = ''US''
 AND fpo.profile_option_name = fpot.profile_option_name
   AND fpov.profile_option_id = fpo.profile_option_id
   AND fa.application_id = fpov.application_id
   AND fpov.level_value = fa2.application_id(+)
   AND frt.responsibility_id(+) = fpov.level_value
   AND fu.user_id(+) = fpov.level_value
) abc
group by abc.profile_name
)
where LevelValue is not null
and (select count(*) FROM fnd_profile_options_tl fpot
     WHERE ((fpot.user_profile_option_name = ''G-Invoicing Integration Admin'')
         or (fpot.user_profile_option_name = ''G-Invoicing Integrating System Id'')
         or (fpot.user_profile_option_name = ''G-Invoicing Service Host'')
         or (fpot.user_profile_option_name = ''G-Invoicing Service Path'')
         or (fpot.user_profile_option_name = ''G-Invoicing Service Version'')) AND fpot.language = ''US'') = 5
) Ginv
where Ginv.NumGinvProfiles >= 5
',
      p_title                  => 'G-Invoicing is Enabled',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'G-Invoicing is enabled via the required profile options for G-Invoicing',
      p_solution               => 'The following profile options are set (not null) indicating that this instance is setup for G-Invoicing<br>
G-Invoicing Integration Admin<br>
G-Invoicing Integrating System Id<br>
G-Invoicing Service Host<br>
G-Invoicing Service Path<br>
G-Invoicing Service Version<br>',
      p_success_msg            => 'G-Invoicing is not enabled.  One or more of the following profile options are not set<br><br>

G-Invoicing Integration Admin<br>
G-Invoicing Integrating System Id<br>
G-Invoicing Service Host<br>
G-Invoicing Service Path<br>
G-Invoicing Service Version<br>
',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('N','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_GINV_ENABLED_VIA_PROFILES');



