debug('begin add_signature: EBS_MFG_PO_APPRVL_MAX_ARCHIVE_REV_GREATER_THAN_CURRENT_REV');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22822',
      p_sig_id                 => 'EBS_MFG_PO_APPRVL_MAX_ARCHIVE_REV_GREATER_THAN_CURRENT_REV',
      p_sig_sql                => 'select poha.po_header_id, null po_release_id, poha.revision_num, pohaa.revision_num archive_max_revision_num 
from po_headers_all poha, po_headers_archive_all pohaa
where pohaa.revision_num > poha.revision_num
and pohaa.po_header_id = poha.po_header_id
and poha.po_header_id = ##$$DOCID$$##
and (''PO'' = ''##$$DOCTYPESHORT$$##'')  -- PO or PA
UNION ALL
select null po_header_id, pora.po_release_id, pora.revision_num, poraa.revision_num archive_max_revision_num 
from po_releases_all pora, po_releases_archive_all poraa
where poraa.revision_num > pora.revision_num
and poraa.po_release_id = pora.po_release_id
and pora.po_release_id = ##$$DOCID$$##
and ''REL'' = ''##$$DOCTYPESHORT$$##''',
      p_title                  => 'Document Max Revision > Current Revision',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The maximum revision of the document in the archive table is greater than the current revision of the document.',
      p_solution               => 'Request a datafix from Support per [1296639/KB455926].',
      p_success_msg            => 'The maximum revision of the document is NOT greater than the current revision.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_PO_APPRVL_MAX_ARCHIVE_REV_GREATER_THAN_CURRENT_REV');



