           d.REQUEST_ID,
           d.PROGRAM_APPLICATION_ID,
           d.PROGRAM_ID,
           d.PROGRAM_UPDATE_DATE,
           d.ORG_ID,
           d.KANBAN_CARD_ID,
           d.AWARD_ID
    FROM po_distributions_all d,
         gl_code_combinations g,
         ( SELECT  FSP.set_of_books_id, GLS.currency_code, COAFS.id_flex_structure_code coa_structure_code, b.concatenated_segment_delimiter delimiter
           FROM financials_system_params_all FSP, gl_sets_of_books GLS, fnd_id_flex_structures COAFS, fnd_id_flex_structures b
           WHERE
           b.id_flex_code = COAFS.id_flex_code
           AND b.id_flex_structure_code = COAFS.id_flex_structure_code
           AND b.id_flex_num = GLS.chart_of_accounts_id 
           AND FSP.org_id= ##$$ORGID$$##
           AND FSP.set_of_books_id = GLS.set_of_books_id
           AND COAFS.id_flex_num = GLS.chart_of_accounts_id
           AND COAFS.application_id = 101 /** SQLGL **/
           AND COAFS.id_flex_code = ''GL#''
          ) gcf        
    WHERE d.po_header_id = ##$$DOCID$$##
    AND d.code_combination_id = g.code_combination_id(+)
    ORDER BY d.po_line_id, d.distribution_num',
      p_title                  => 'PO Distribution Details',
      p_fail_condition         => '[QUANTITY_ORDERED] = [0]',
      p_problem_descr          => 'There exists zero quantity or amount distribution lines for document number ##$$DOCNUM$$##!',
      p_solution               => 'Ensure all distribution lines have valid quantities/amount entered (greater than 0).',
      p_success_msg            => 'Distribution details for PO Number ##$$DOCNUM$$##. 
',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '13'
      );
   l_info.delete;
debug('end add_signature: DOC_DETAIL_PO_DISTS');



