debug('begin add_signature: EBS_MFG_PO_APPRVL_CHARGEABLE_FLAG_FOR_TASK_ID');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '28042',
      p_sig_id                 => 'EBS_MFG_PO_APPRVL_CHARGEABLE_FLAG_FOR_TASK_ID',
      p_sig_sql                => 'SELECT
    pol.line_num,
    poll.shipment_num,
    pod.distribution_num,
    pap.name,
    pap.segment1,
    pat.chargeable_flag chargeable_flag,
    pat.task_id,
    pat.*
FROM
    pa_tasks              pat,
    pa_projects_all       pap,
    po_distributions_all  pod,
    po_lines_all          pol,
    po_line_locations_all poll
WHERE
        pat.project_id = pap.project_id
    AND pap.project_id = pod.project_id
    AND pat.task_id = pod.task_id
    AND pod.po_line_id = pol.po_line_id
    AND pol.po_line_id = poll.po_line_id
    AND poll.po_line_id = pod.po_line_id
    AND pod.project_id IS NOT NULL
   AND  pod.po_line_id like NVL(''##$$LINEID$$##'',''%'') 
    AND pod.po_header_id = ##$$DOCID$$##',
      p_title                  => 'PA_TASKS_ALL',
      p_fail_condition         => '[chargeable_flag] = [N]',
      p_problem_descr          => 'PA_TASKS_ALL data shows CHARGEABLE_FLAG = N for one or more project tasks',
      p_solution               => 'The Task Is Not Chargeable for at least one of the project tasks.  This will lead to error at PO approval as described in [2991629/KB619714]',
      p_success_msg            => 'PA_TASKS_ALL data - No action is needed, informational purposes only.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_PO_APPRVL_CHARGEABLE_FLAG_FOR_TASK_ID');



debug('begin add_signature: EBS_MFG_PO_DOC_ATTACHMENTS');
   l_info('##MASK##DESCRIPTION'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '24561',
      p_sig_id                 => 'EBS_MFG_PO_DOC_ATTACHMENTS',
      p_sig_sql                => '(SELECT ad.entity_name, ad.seq_num Seq , ad.pk1_value,
DECODE(c.name, ''MISC'', ''Miscellaneous'', ''Vendor'', ''To Supplier'', ''Buyer'', ''To Buyer'', ''Receiver'', ''To Receiver'', ''Approver'', ''To Approver'', ''REQ Internal'', ''Internal to Requisition'', ''UNKNOWN'') AttentionTo,
DECODE(d.datatype_id, 1, ''Short text'', 2, ''Long text'', 5, ''Web Page'', 6, ''File'', 7, ''Document reference'', ''UNKNOWN'') Type,
dtl.description, dtl.file_name, dtl.media_id, dtl.datatype_name, dtl.publish_flag, dtl.usage_type_descr
FROM fnd_documents d,
fnd_document_categories c,
fnd_attached_documents ad,
fnd_documents_vl dtl,
po_headers_all h
WHERE 
d.category_id = c.category_id
AND d.document_id = ad.document_id
AND ad.entity_name in (''PO_HEADERS'',''PO_HEAD'')
AND ad.pk1_value = to_char(h.po_header_id)
AND h.po_header_id = ##$$DOCID$$##
AND d.document_id = dtl.document_id
union all
SELECT ad.entity_name, ad.seq_num Seq , ad.pk1_value,
DECODE(c.name, ''MISC'', ''Miscellaneous'', ''Vendor'', ''To Supplier'', ''Buyer'', ''To Buyer'', ''Receiver'', ''To Receiver'', ''Approver'', ''To Approver'', ''REQ Internal'', ''Internal to Requisition'', ''UNKNOWN'') AttentionTo,
DECODE(d.datatype_id, 1, ''Short text'', 2, ''Long text'', 5, ''Web Page'', 6, ''File'', 7, ''Document reference'', ''UNKNOWN'') Type,
dtl.description, dtl.file_name, dtl.media_id, dtl.datatype_name, dtl.publish_flag, dtl.usage_type_descr
FROM fnd_documents d,
fnd_document_categories c,
fnd_attached_documents ad,
fnd_documents_vl dtl,
po_lines_all l
WHERE d.category_id = c.category_id
AND d.document_id = ad.document_id
AND ad.entity_name = ''PO_LINES''
AND ad.pk1_value = to_char(l.po_line_id)
AND l.po_line_id like NVL(''##$$LINEID$$##'',''%'')
AND l.po_header_id = ##$$DOCID$$##
AND d.document_id = dtl.document_id
union all
SELECT ad.entity_name, ad.seq_num Seq , ad.pk1_value,
DECODE(c.name, ''MISC'', ''Miscellaneous'', ''Vendor'', ''To Supplier'', ''Buyer'', ''To Buyer'', ''Receiver'', ''To Receiver'', ''Approver'', ''To Approver'', ''REQ Internal'', ''Internal to Requisition'', ''UNKNOWN'') AttentionTo,
DECODE(d.datatype_id, 1, ''Short text'', 2, ''Long text'', 5, ''Web Page'', 6, ''File'', 7, ''Document reference'', ''UNKNOWN'') Type,
dtl.description, dtl.file_name, dtl.media_id, dtl.datatype_name, dtl.publish_flag, dtl.usage_type_descr
FROM fnd_documents d,
fnd_document_categories c,
fnd_attached_documents ad,
fnd_documents_vl dtl,
po_line_locations_all l
WHERE d.category_id = c.category_id
AND d.document_id = ad.document_id
AND ad.entity_name = ''PO_SHIPMENTS''
AND ad.pk1_value = to_char(l.line_location_id)
AND l.po_line_id like NVL(''##$$LINEID$$##'',''%'')
AND l.po_header_id = ##$$DOCID$$##
AND d.document_id = dtl.document_id
)
order by entity_name, seq
',
      p_title                  => 'Document Header, Line, and Shipment Attachments',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Document Attachments',
      p_solution               => 'Header, Line, and Shipment level attachments',
      p_success_msg            => 'No attachments found at the Header, Line, or Shipment level for this Document',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_PO_DOC_ATTACHMENTS');



debug('begin add_signature: NOTE390023.1_CASE_PO10');
   l_info('##MASK##FULL_NAME'):= 'DISPLAY_FIRST_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1731',
      p_sig_id                 => 'NOTE390023.1_CASE_PO10',
      p_sig_sql                => 'SELECT 
ah.sequence_num, to_char(ah.action_date, ''DD-MON-YY hh:mi:ss'') action_date, ah.action_code, flv.meaning, flv.description, p.first_name, substr(p.last_name, 1,1) last_name,
--length(p.first_name), ROUND(length(p.first_name)/2),
--substr(p.first_name,1,ROUND(length(p.first_name) * 3/4)) firstn, p.first_name, substr(p.last_name,1,ROUND(length(p.last_name) * 1/4)) lastn,
p.full_name, 
ah.employee_id, ph.segment1 po_num, ah.object_revision_num rev_num, ah.approval_path_id, ah.approval_group_id, ah.note, ah.object_id, 
ah.object_type_code, ah.object_sub_type_code, ah.offline_code, ah.request_id, ah.program_application_id, ah.program_id, to_char(ah.program_update_date, ''DD-MON-YY hh:mi:ss'') program_update_date, to_char(ah.program_date, ''DD-MON-YY hh:mi:ss'') program_date, 
to_char(ah.last_update_date, ''DD-MON-YY hh:mi:ss'') last_update_date, ah.last_updated_by, to_char(ah.creation_date, ''DD-MON-YY hh:mi:ss'') creation_date, ah.created_by 
    FROM po_headers_all ph,
         po_action_history ah,
         per_all_people_f p, fnd_lookup_values flv
    WHERE flv.lookup_code(+) = ah.action_code and flv.language(+) = ''US'' and flv.view_application_id(+) = 201 and flv.lookup_type(+) = ''APPROVER ACTIONS''
    AND ah.object_id = ph.po_header_id
    AND   p.person_id (+) = ah.employee_id
    AND   sysdate BETWEEN
            p.effective_start_date(+) AND p.effective_end_date (+)
    AND   ah.object_type_code in (''PO'', ''PA'')
--AND ah.last_update_date > sysdate - 100
    AND   ah.object_id = ##$$DOCID$$##
    ORDER BY ah.sequence_num desc',
      p_title                  => 'Purchase Order Action History',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Document Action History for PO Number ##$$DOCNUM$$##',
      p_solution               => '',
      p_success_msg            => 'No Document Action History found for PO Number ##$$DOCNUM$$##',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '27'
      );
   l_info.delete;
debug('end add_signature: NOTE390023.1_CASE_PO10');



debug('begin add_signature: PO_RELATED_REQ_DISTRIBUTIONS');
   l_info('##MASK##%ATTRIBUTE%'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22290',
      p_sig_id                 => 'PO_RELATED_REQ_DISTRIBUTIONS',
      p_sig_sql                => 'SELECT distinct prda.requisition_line_id,
           prda.distribution_num,
           prda.req_line_quantity,
           prda.code_combination_id,
           substr(rtrim(g.segment1||gcf.delimiter||g.segment2||gcf.delimiter||
             g.segment3||gcf.delimiter||g.segment4||gcf.delimiter||
             g.segment5||gcf.delimiter||g.segment6||gcf.delimiter||
             g.segment7||gcf.delimiter||g.segment8||gcf.delimiter||
             g.segment9||gcf.delimiter||g.segment10||gcf.delimiter||
             g.segment11||gcf.delimiter||g.segment12||gcf.delimiter||
             g.segment13||gcf.delimiter||g.segment14||gcf.delimiter||
             g.segment15||gcf.delimiter||g.segment16||gcf.delimiter||
             g.segment17||gcf.delimiter||g.segment18||gcf.delimiter||
             g.segment19||gcf.delimiter||g.segment20||gcf.delimiter||
             g.segment21||gcf.delimiter||g.segment22||gcf.delimiter||
             g.segment23||gcf.delimiter||g.segment24||gcf.delimiter||
             g.segment25||gcf.delimiter||g.segment26||gcf.delimiter||
             g.segment27||gcf.delimiter||g.segment28||gcf.delimiter||
             g.segment29||gcf.delimiter||g.segment30,gcf.delimiter), 1, 100) charge_acct,
           prda.encumbered_flag,
           prda.gl_encumbered_date,
           prda.gl_encumbered_period_name,
           prda.gl_cancelled_date,
           prda.failed_funds_lookup_code,
           prda.encumbered_amount,
           prda.budget_account_id,
           prda.accrual_account_id,
           prda.variance_account_id,
           prda.prevent_encumbrance_flag,
           prda.ussgl_transaction_code,
           prda.government_context,
           prda.project_id,
           prda.task_id,
           prda.expenditure_type,
           prda.project_accounting_context,
           prda.expenditure_organization_id,
           prda.gl_closed_date,
           prda.source_req_distribution_id,
           prda.allocation_type,
           prda.allocation_value,
           prda.project_related_flag,
           prda.expenditure_item_date,
           prda.DISTRIBUTION_ID,
           prda.LAST_UPDATE_DATE,
           prda.LAST_UPDATED_BY,
           prda.SET_OF_BOOKS_ID,
           prda.LAST_UPDATE_LOGIN,
           prda.CREATION_DATE,
           prda.CREATED_BY,
           prda.ATTRIBUTE_CATEGORY,
           prda.ATTRIBUTE1,
           prda.ATTRIBUTE2,
           prda.ATTRIBUTE3,
           prda.ATTRIBUTE4,
           prda.ATTRIBUTE5,
           prda.ATTRIBUTE6,
           prda.ATTRIBUTE7,
           prda.ATTRIBUTE8,
           prda.ATTRIBUTE9,
           prda.ATTRIBUTE10,
           prda.ATTRIBUTE11,
           prda.ATTRIBUTE12,
           prda.ATTRIBUTE13,
           prda.ATTRIBUTE14,
           prda.ATTRIBUTE15,
           prda.REQUEST_ID,
           prda.PROGRAM_APPLICATION_ID,
           prda.PROGRAM_ID,
           prda.PROGRAM_UPDATE_DATE,
           prda.END_ITEM_UNIT_NUMBER,
           prda.ORG_ID,
           prda.AWARD_ID,
           prda.RECOVERABLE_TAX,
           prda.NONRECOVERABLE_TAX,
           prda.RECOVERY_RATE,
           prda.TAX_RECOVERY_OVERRIDE_FLAG,
           prda.OKE_CONTRACT_LINE_ID,
           prda.OKE_CONTRACT_DELIVERABLE_ID,
           prda.REQ_LINE_AMOUNT,
           prda.REQ_LINE_CURRENCY_AMOUNT,
           prda.REQ_AWARD_ID
from po_distributions_all PODA, po_req_distributions_all PRDA, gl_code_combinations g,
         ( SELECT  FSP.set_of_books_id, GLS.currency_code, COAFS.id_flex_structure_code coa_structure_code, b.concatenated_segment_delimiter delimiter
           FROM financials_system_params_all FSP, gl_sets_of_books GLS, fnd_id_flex_structures COAFS, fnd_id_flex_structures b
           WHERE
           b.id_flex_code = COAFS.id_flex_code
           AND b.id_flex_structure_code = COAFS.id_flex_structure_code
           AND b.id_flex_num = GLS.chart_of_accounts_id 
           AND FSP.org_id= ##$$ORGID$$##
           AND FSP.set_of_books_id = GLS.set_of_books_id
           AND COAFS.id_flex_num = GLS.chart_of_accounts_id
           AND COAFS.application_id = 101 /** SQLGL **/
           AND COAFS.id_flex_code = ''GL#''
          ) gcf
where g.code_combination_id = prda.code_combination_id
