debug('begin add_signature: DOC_DETAIL_DOC_STYLE_INCOMPLETE_PO_AME_SETUP');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22091',
      p_sig_id                 => 'DOC_DETAIL_DOC_STYLE_INCOMPLETE_PO_AME_SETUP',
      p_sig_sql                => 'select style_id, style_name, style_type, wf_approval_process, ame_transaction_type 
from po_doc_style_headers 
where 
((WF_APPROVAL_PROCESS like (''%PO%AME%APPR%TOP%'') and AME_TRANSACTION_TYPE is null)
or
(WF_APPROVAL_PROCESS = ''POAPPRV_TOP'' and AME_TRANSACTION_TYPE is not null))
AND style_id = nvl(##$$STYLE_ID$$##, 0)
AND not exists
(select dt.wf_approval_process, dt.ame_transaction_type
  from po_document_types_all dt
  where (dt.WF_APPROVAL_PROCESS like ''%PO_AME_APPRV_TOP%'' and dt.AME_TRANSACTION_TYPE is not null)
  AND   dt.document_subtype = ''STANDARD''
  AND   dt.document_type_code = ''PO''
  AND   dt.document_type_code = ''##$$TRXTP$$##''
  AND   dt.document_subtype = ''##$$SUBTP$$##''
  AND   dt.org_id = ##$$ORGID$$##
)',
      p_title                  => 'Incomplete AME Setup for Document Style Associated to this Purchase Order',
      p_fail_condition         => 'RS',
      p_problem_descr          => '<p><b>Workflow Startup Process</b> (WF_APPROVAL_PROCESS) is not compatible with the <b>AME Transaction Type</b> (AME_TRANSACTION_TYPE).  Both the Workflow Approval Process and the AME Transaction Type must be set to either AME or non-AME values.</p><p>For Example:</p><p>
<table width="70%" border="1">
  <tr>
    <td><b>AME/Non-AME</b></td>
    <td><b>Workflow Startup Process</b></td>
    <td><b>WF_APPROVAL_PROCESS</b></td>
    <td><b>AME Transaction Type</b></td>
    <td><b>AME_TRANSACTION_TYPE</b></td>
  </tr>
  <tr>
    <td>AME Based</td>
    <td>PO AME Approval Top Process</td>
    <td>PO_AME_APPRV_TOP</td>
    <td>Purchase Order Approval</td>
    <td>PURCHASE_ORDER</td>
  </tr>
  <tr>
    <td>Non-AME Based</td>
    <td>PO Approval Top Process</td>
    <td>POAPPRV_TOP</td>
    <td></td>
    <td></td>
  </tr>
</table>
</p>',
      p_solution               => '<p>Navigate to Purchasing / Setup / Document Styles, and edit the Document Style for the style used on this Purchase Order as shown above.</p><p>For AME Based approval:<br>Set the Workflow Startup Process to PO AME Approval Top Process -- PO_AME_APPRV_TOP, and set the AME Transaction Type to a valid value (Ex: Purchase Order Approval -- PURCHASE_ORDER)</p>
<p>For non-AME Based approval:<br>Set the Workflow Startup Process to the standard (non-AME) process, PO Approval Top Process (POAPPRV_TOP) and set the AME Transaction Type as null (blank)</p><p>Reference: [2036287/KB697357] How to Define Style and Document Type for Purchase Orders when Using or not Using AME</p>',
      p_success_msg            => '<p><b>Workflow Startup Process</b> (WF_APPROVAL_PROCESS) appears compatible with the <b>AME Transaction Type</b> (AME_TRANSACTION_TYPE) in the Document Style setup, or there are compatible values specified at Document Type setup (Type ##$$TRXTP$$## SubType ##$$SUBTP$$##) that take precedence over the document style setup.</p><p>Reference: [2036287/KB697357] How to Define Style and Document Type for Purchase Orders when Using or not Using AME</p>',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '10'
      );
   l_info.delete;
debug('end add_signature: DOC_DETAIL_DOC_STYLE_INCOMPLETE_PO_AME_SETUP');



