debug('begin add_signature: EBS_MFG_PO_APPRVL_AUTHORIZATION_STATUS_VS_APPROVED_FLAG');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '29097',
      p_sig_id                 => 'EBS_MFG_PO_APPRVL_AUTHORIZATION_STATUS_VS_APPROVED_FLAG',
      p_sig_sql                => 'select poha.po_header_id, poha.authorization_status,
poha.approved_flag "PO Header Approved Flag", plla.approved_flag "PO Shipment Approved Flag", 
poha.cancel_flag "PO Header Cancel Flag", plla.cancel_flag "PO Shipment Cancel Flag",
plla.shipment_num, plla.line_location_id, poha.acceptance_required_flag, approval_required_flag, change_requested_by
from po_headers_all poha, po_line_locations_all plla
where poha.po_header_id = plla.po_header_id
AND poha.type_lookup_code = ''STANDARD''
AND poha.authorization_status = ''APPROVED''
AND (plla.approved_flag = ''R'' or poha.approved_flag = ''R'')
and poha.po_header_id = ##$$DOCID$$##',
      p_title                  => 'AUTHORIZATION_STATUS = APPROVED but APPROVED_FLAG = R',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'AUTHORIZATION_STATUS = APPROVED, however the APPROVED_FLAG = R on the Header or the Shipment(s) for this Purchase Order.',
      p_solution               => 'This is an unexpected data scenario.  When The document AUTHORIZATION_STATUS = APPROVED, the APPROVED_FLAG on both the PO Header and the PO Shipment should be ''Y''.  This likely requires a datafix.  One possible datafix is when this issue arises after a change request; the datafix script in [453551/KB625956] may be applicable for this case.  You may upload this Procurement Approval Analyzer output to an SR for further analysis.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
