debug('end add_signature: EBS_MFG_PO_APPRVL_AUTHORIZATION_STATUS_VS_APPROVED_FLAG');



debug('begin add_signature: DOC_DETAIL_REQ_DISTS');
   l_info('##MASK##%ATTRIBUTE%'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '2226',
      p_sig_id                 => 'DOC_DETAIL_REQ_DISTS',
      p_sig_sql                => 'SELECT d.distribution_id, d.requisition_line_id,
           d.distribution_num,
           d.req_line_quantity,
           d.code_combination_id,
           substr(rtrim(g.segment1||gcf.delimiter||g.segment2||gcf.delimiter||
             g.segment3||gcf.delimiter||g.segment4||gcf.delimiter||
             g.segment5||gcf.delimiter||g.segment6||gcf.delimiter||
             g.segment7||gcf.delimiter||g.segment8||gcf.delimiter||
             g.segment9||gcf.delimiter||g.segment10||gcf.delimiter||
             g.segment11||gcf.delimiter||g.segment12||gcf.delimiter||
             g.segment13||gcf.delimiter||g.segment14||gcf.delimiter||
             g.segment15||gcf.delimiter||g.segment16||gcf.delimiter||
             g.segment17||gcf.delimiter||g.segment18||gcf.delimiter||
             g.segment19||gcf.delimiter||g.segment20||gcf.delimiter||
             g.segment21||gcf.delimiter||g.segment22||gcf.delimiter||
             g.segment23||gcf.delimiter||g.segment24||gcf.delimiter||
             g.segment25||gcf.delimiter||g.segment26||gcf.delimiter||
             g.segment27||gcf.delimiter||g.segment28||gcf.delimiter||
             g.segment29||gcf.delimiter||g.segment30,gcf.delimiter), 1, 100) charge_acct,
           d.encumbered_flag,
           d.gl_encumbered_date,
           d.gl_encumbered_period_name,
           d.gl_cancelled_date,
           d.failed_funds_lookup_code,
           d.encumbered_amount,
           d.budget_account_id,
           d.accrual_account_id,
           d.variance_account_id,
           d.prevent_encumbrance_flag,
           d.ussgl_transaction_code,
           d.government_context,
           d.project_id,
           d.task_id,
           d.expenditure_type,
           d.project_accounting_context,
           d.expenditure_organization_id,
           d.gl_closed_date,
           d.source_req_distribution_id,
           d.allocation_type,
           d.allocation_value,
           d.project_related_flag,
           d.expenditure_item_date,
           d.DISTRIBUTION_ID,
           d.LAST_UPDATE_DATE,
           d.LAST_UPDATED_BY,
           d.SET_OF_BOOKS_ID,
           d.LAST_UPDATE_LOGIN,
           d.CREATION_DATE,
           d.CREATED_BY,
           d.ATTRIBUTE_CATEGORY,
           d.ATTRIBUTE1,
           d.ATTRIBUTE2,
           d.ATTRIBUTE3,
           d.ATTRIBUTE4,
           d.ATTRIBUTE5,
           d.ATTRIBUTE6,
           d.ATTRIBUTE7,
           d.ATTRIBUTE8,
           d.ATTRIBUTE9,
           d.ATTRIBUTE10,
           d.ATTRIBUTE11,
           d.ATTRIBUTE12,
           d.ATTRIBUTE13,
           d.ATTRIBUTE14,
           d.ATTRIBUTE15,
           d.REQUEST_ID,
           d.PROGRAM_APPLICATION_ID,
           d.PROGRAM_ID,
           d.PROGRAM_UPDATE_DATE,
           d.END_ITEM_UNIT_NUMBER,
           d.ORG_ID,
           d.AWARD_ID,
           d.RECOVERABLE_TAX,
           d.NONRECOVERABLE_TAX,
           d.RECOVERY_RATE,
           d.TAX_RECOVERY_OVERRIDE_FLAG,
           d.OKE_CONTRACT_LINE_ID,
           d.OKE_CONTRACT_DELIVERABLE_ID,
           d.REQ_LINE_AMOUNT,
           d.REQ_LINE_CURRENCY_AMOUNT,
           d.REQ_AWARD_ID
    FROM po_req_distributions_all d,
         gl_code_combinations g,
         ( SELECT  FSP.set_of_books_id, GLS.currency_code, COAFS.id_flex_structure_code coa_structure_code, b.concatenated_segment_delimiter delimiter
           FROM financials_system_params_all FSP, gl_sets_of_books GLS, fnd_id_flex_structures COAFS, fnd_id_flex_structures b
           WHERE
           b.id_flex_code = COAFS.id_flex_code
           AND b.id_flex_structure_code = COAFS.id_flex_structure_code
           AND b.id_flex_num = GLS.chart_of_accounts_id 
           AND FSP.org_id= ##$$ORGID$$##
           AND FSP.set_of_books_id = GLS.set_of_books_id
           AND COAFS.id_flex_num = GLS.chart_of_accounts_id
           AND COAFS.application_id = 101 /** SQLGL **/
           AND COAFS.id_flex_code = ''GL#''
          ) gcf
    WHERE d.requisition_line_id IN (
            SELECT pla.requisition_line_id
            FROM po_requisition_lines_all pla
            WHERE pla.requisition_header_id = ##$$DOCID$$## )
    AND   d.code_combination_id = g.code_combination_id(+)
    ORDER BY d.requisition_line_id, d.distribution_num',
      p_title                  => 'Requisition Distribution Details',
      p_fail_condition         => 'NRS',
