      p_solution               => 'Verify that the document exists in this operating unit',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: DOC_DETAIL_REQ_DISTS');



debug('begin add_signature: EBS_MFG_PO_APPRVL_PO_APPROVAL_LIST_HEADERS_REQUISITION');
   l_info('##MASK##FULL_NAME'):= 'DISPLAY_FIRST_25_PCNT_WORD';
   l_info('##MASK##USER_NAME'):= 'DISPLAY_FIRST_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '30271',
      p_sig_id                 => 'EBS_MFG_PO_APPRVL_PO_APPROVAL_LIST_HEADERS_REQUISITION',
      p_sig_sql                => 'SELECT pah.document_id, pah.revision ApprListHdrRevision, pah.approval_list_header_id, pal.approval_list_line_id, pal.sequence_num, 
pal.approver_type, pal.approver_id, ppf.first_name, substr(ppf.last_name, 1,1) last_name, ppf.full_name, fu.user_name, 
pah.creation_date
from po_approval_list_lines pal, 
po_approval_list_headers pah, 
fnd_user fu, 
per_all_people_f ppf,
(select max(revision) revision from po_approval_list_headers where ''##$$TRXTP$$##'' = ''REQUISITION'' and document_id = ##$$DOCID$$##) pahmrev
where 
pah.revision = pahmrev.revision
and pah.approval_list_header_id = pal.approval_list_header_id
and pal.approver_id = ppf.person_id
and ppf.person_id = fu.employee_id
and trunc(pah.creation_date)>= trunc(ppf.effective_start_date) and trunc(pah.creation_date)< trunc(ppf.effective_end_date)
and fu.employee_id = pal.approver_id
and pah.document_type = ''REQUISITION'' and pah.document_id = ##$$DOCID$$##
and ''##$$TRXTP$$##'' = ''REQUISITION''
order by pal.sequence_num',
      p_title                  => 'Requisition - Approval List Header and Lines',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'PO_APPROVAL_LIST_HEADERS and PO_APPROVAL_LIST_LINES data (for Requisitions only)',
      p_solution               => 'PO_APPROVAL_LIST_HEADERS and PO_APPROVAL_LIST_LINES data (latest revision) for the requisition',
      p_success_msg            => 'No data found in PO_APPROVAL_LIST_HEADERS / PO_APPROVAL_LIST_LINES for this requisition',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_PO_APPRVL_PO_APPROVAL_LIST_HEADERS_REQUISITION');



debug('begin add_signature: Note390023.1_case_REQ9');
   l_info('##MASK##FULL_NAME'):= 'DISPLAY_FIRST_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1744',
      p_sig_id                 => 'Note390023.1_case_REQ9',
      p_sig_sql                => 'SELECT ah.sequence_num, to_char(ah.action_date, ''DD-MON-YY hh:mi:ss'') action_date, ah.action_code, flv.meaning, flv.description, p.first_name, substr(p.last_name, 1,1) last_name, p.full_name, ah.employee_id, rh.segment1 req_num, 
ah.object_revision_num rev_num, ah.approval_path_id, ah.note, ah.object_id, ah.object_type_code, 
ah.object_sub_type_code, ah.offline_code, ah.request_id, ah.program_application_id, ah.program_id, 
to_char(ah.program_update_date, ''DD-MON-YY hh:mi:ss'') program_update_date, to_char(ah.program_date, ''DD-MON-YY hh:mi:ss'') program_date,
to_char(ah.last_update_date, ''DD-MON-YY hh:mi:ss'') last_update_date, ah.last_updated_by, 
to_char(ah.creation_date, ''DD-MON-YY hh:mi:ss'') creation_date, ah.created_by 
    FROM po_requisition_headers_all rh,
         po_action_history ah,
         per_people_f p, fnd_lookup_values flv
    WHERE flv.lookup_code(+) = ah.action_code and flv.language(+) = ''US'' and flv.view_application_id(+) = 201 and flv.lookup_type(+) = ''APPROVER ACTIONS''
    AND ah.object_id = rh.requisition_header_id
    AND   p.person_id (+) = ah.employee_id
    AND   sysdate BETWEEN
            p.effective_start_date(+) AND p.effective_end_date (+)
    AND   ah.object_type_code = ''REQUISITION''
    AND   ah.object_id = ##$$DOCID$$##
    ORDER BY ah.sequence_num desc',
      p_title                  => 'Requisition Action History',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Document Action History for Requisition number ##$$DOCNUM$$##.',
      p_solution               => '',
      p_success_msg            => 'No Document Action History for Requisition number ##$$DOCNUM$$##.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '20'
      );
   l_info.delete;
debug('end add_signature: Note390023.1_case_REQ9');



