   l_info('##MASK##%CONTRACTOR%NAME'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##MASK##%NOTE%'):= 'DISPLAY_FIRST_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '2219',
      p_sig_id                 => 'DOC_DETAIL_REL_LINES_ARCHIVE',
      p_sig_sql                => 'SELECT l.line_num,
           l.po_line_id,
           l.revision_num,
           l.item_id,
           substr(msi.segment1,1,40) item_number,
