           l.CREATION_DATE,
           l.CREATED_BY,
           l.QUANTITY_COMMITTED,
           l.COMMITTED_AMOUNT,
           l.UN_NUMBER_ID,
           l.HAZARD_CLASS_ID,
           l.NOTE_TO_VENDOR,
           l.FROM_HEADER_ID,
           l.FROM_LINE_ID,
           l.MIN_ORDER_QUANTITY,
           l.MAX_ORDER_QUANTITY,
           l.QTY_RCV_TOLERANCE,
           l.OVER_TOLERANCE_ERROR_FLAG,
           l.MARKET_PRICE,
           l.UNORDERED_FLAG,
           l.USER_HOLD_FLAG,
           l.CANCEL_REASON,
           l.FIRM_STATUS_LOOKUP_CODE,
           l.FIRM_DATE,
           l.VENDOR_PRODUCT_NUM,
           l.CONTRACT_NUM,
           l.TYPE_1099,
           l.CAPITAL_EXPENSE_FLAG,
           l.NEGOTIATED_BY_PREPARER_FLAG,
           l.ATTRIBUTE_CATEGORY,
           l.ATTRIBUTE1,
           l.ATTRIBUTE2,
           l.ATTRIBUTE3,
