           l.PROGRAM_ID,
           l.PROGRAM_UPDATE_DATE,
           l.CLOSED_DATE,
           l.CLOSED_REASON,
           l.CLOSED_BY,
           l.TRANSACTION_REASON_CODE,
           l.ORG_ID,
           l.QC_GRADE,
           l.SECONDARY_UOM,
           l.SECONDARY_QTY,
           l.GLOBAL_ATTRIBUTE_CATEGORY,
           l.GLOBAL_ATTRIBUTE1,
           l.GLOBAL_ATTRIBUTE2,
           l.GLOBAL_ATTRIBUTE3,
           l.GLOBAL_ATTRIBUTE4,
           l.GLOBAL_ATTRIBUTE5,
           l.GLOBAL_ATTRIBUTE6,
           l.GLOBAL_ATTRIBUTE7,
           l.GLOBAL_ATTRIBUTE8,
           l.GLOBAL_ATTRIBUTE9,
           l.GLOBAL_ATTRIBUTE10,
           l.GLOBAL_ATTRIBUTE11,
           l.GLOBAL_ATTRIBUTE12,
           l.GLOBAL_ATTRIBUTE13,
           l.GLOBAL_ATTRIBUTE14,
           l.GLOBAL_ATTRIBUTE15,
           l.GLOBAL_ATTRIBUTE16,
           l.GLOBAL_ATTRIBUTE17,
           l.GLOBAL_ATTRIBUTE18,
           l.GLOBAL_ATTRIBUTE19,
           l.GLOBAL_ATTRIBUTE20,
           l.LINE_REFERENCE_NUM,
           l.PROJECT_ID,
           l.TASK_ID,
           l.EXPIRATION_DATE,
           l.OKE_CONTRACT_HEADER_ID,
           l.OKE_CONTRACT_VERSION_ID,
           l.SECONDARY_QUANTITY,
           l.SECONDARY_UNIT_OF_MEASURE,
           l.PREFERRED_GRADE,
           l.AUCTION_HEADER_ID,
           l.AUCTION_DISPLAY_NUMBER,
           l.AUCTION_LINE_NUMBER,
           l.BID_NUMBER,
           l.BID_LINE_NUMBER,
           l.RETROACTIVE_DATE,
           l.SUPPLIER_REF_NUMBER,
           l.CONTRACT_ID,
           l.START_DATE,
           l.JOB_ID,
           l.CONTRACTOR_FIRST_NAME,
           l.CONTRACTOR_LAST_NAME,
           l.ORDER_TYPE_LOOKUP_CODE,
           l.PURCHASE_BASIS,
           l.MATCHING_BASIS,
           l.SVC_AMOUNT_NOTIF_SENT,
           l.SVC_COMPLETION_NOTIF_SENT,
           l.BASE_UNIT_PRICE,
           l.MANUAL_PRICE_CHANGE_FLAG,
           l.RETAINAGE_RATE,
           l.MAX_RETAINAGE_AMOUNT,
           l.PROGRESS_PAYMENT_RATE,
           l.RECOUPMENT_RATE,
           l.CATALOG_NAME,
           l.SUPPLIER_PART_AUXID,
           l.IP_CATEGORY_ID           
    FROM po_lines_archive_all l,
         po_line_types lt,
         mtl_system_items msi,
         financials_system_params_all fsp,
         mtl_categories_kfv mca
    WHERE l.po_header_id = ##$$DOCID$$##
    AND   l.po_line_id IN (
            SELECT ll.po_line_id FROM po_line_locations_all ll
            WHERE ll.po_release_id = ##$$RELID$$##)
    AND   fsp.org_id = l.org_id
    AND   msi.inventory_item_id (+) = l.item_id
    AND   nvl(msi.organization_id, fsp.inventory_organization_id) =
            fsp.inventory_organization_id
    AND   lt.line_type_id = l.line_type_id
    AND   mca.category_id  = l.category_id
    AND   l.revision_num IN
          (SELECT max(revision_num) FROM po_lines_archive_all WHERE po_line_id = l.po_line_id)
    ORDER BY l.line_num',
      p_title                  => 'Release Source Line Archive Record (Highest Revision)',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'No document lines archive data found associated to this release document',
      p_solution               => '<p>There is no archive data for the document line associated to this Release.  Approve or Transmit (Print/Fax/Email) the release document to see data in the archive table.</p>
<p>Reference: <b>[1638338/KB663801] - Difference in Behavior when ''Archive On'' is set to ''Transmission'' or ''Approve''</b>.</p>',
      p_success_msg            => 'Lines archive data associated to this release document',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: DOC_DETAIL_REL_LINES_ARCHIVE');



