debug('begin add_signature: EBS_MFG_PO_RELEASE_ATTACHMENTS');
   l_info('##MASK##DESCRIPTION'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '24562',
      p_sig_id                 => 'EBS_MFG_PO_RELEASE_ATTACHMENTS',
      p_sig_sql                => '(SELECT ad.entity_name, ad.seq_num Seq , ad.pk1_value,
DECODE(c.name, ''MISC'', ''Miscellaneous'', ''Vendor'', ''To Supplier'', ''Buyer'', ''To Buyer'', ''Receiver'', ''To Receiver'', ''Approver'', ''To Approver'', ''REQ Internal'', ''Internal to Requisition'', ''UNKNOWN'') AttentionTo,
DECODE(d.datatype_id, 1, ''Short text'', 2, ''Long text'', 5, ''Web Page'', 6, ''File'', 7, ''Document reference'', ''UNKNOWN'') Type,
dtl.description, dtl.file_name, dtl.media_id, dtl.datatype_name, dtl.publish_flag, dtl.usage_type_descr
FROM fnd_documents d,
fnd_document_categories c,
fnd_attached_documents ad,
fnd_documents_vl dtl,
po_releases_all r
WHERE 
d.category_id = c.category_id
AND d.document_id = ad.document_id
AND ad.entity_name in (''PO_RELEASES'',''PO_REL'')
AND ad.pk1_value = to_char(r.po_release_id)
AND r.po_release_id = ''##$$RELID$$##''
AND r.po_header_id = ##$$DOCID$$##
AND d.document_id = dtl.document_id
union all
SELECT ad.entity_name, ad.seq_num Seq , ad.pk1_value,
DECODE(c.name, ''MISC'', ''Miscellaneous'', ''Vendor'', ''To Supplier'', ''Buyer'', ''To Buyer'', ''Receiver'', ''To Receiver'', ''Approver'', ''To Approver'', ''REQ Internal'', ''Internal to Requisition'', ''UNKNOWN'') AttentionTo,
DECODE(d.datatype_id, 1, ''Short text'', 2, ''Long text'', 5, ''Web Page'', 6, ''File'', 7, ''Document reference'', ''UNKNOWN'') Type,
dtl.description, dtl.file_name, dtl.media_id, dtl.datatype_name, dtl.publish_flag, dtl.usage_type_descr
FROM fnd_documents d,
fnd_document_categories c,
fnd_attached_documents ad,
fnd_documents_vl dtl,
po_line_locations_all l
WHERE d.category_id = c.category_id
AND d.document_id = ad.document_id
AND ad.entity_name = ''PO_SHIPMENTS''
AND ad.pk1_value = to_char(l.line_location_id)
AND l.po_line_id like NVL(''##$$LINEID$$##'',''%'')
AND l.po_release_id = ##$$RELID$$##
AND l.po_header_id = ##$$DOCID$$##
AND d.document_id = dtl.document_id
)
order by entity_name, seq
',
      p_title                  => 'Purchase Release Header and Shipment Attachments',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Purchase Release Attachments',
      p_solution               => 'Header and Shipment level attachments',
      p_success_msg            => 'No attachments found at the Header or Shipment level for this Purchase Release',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_PO_RELEASE_ATTACHMENTS');



debug('begin add_signature: Note390023.1_case_REL7');
   l_info('##MASK##FULL_NAME'):= 'DISPLAY_FIRST_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1760',
      p_sig_id                 => 'Note390023.1_case_REL7',
      p_sig_sql                => 'SELECT ah.sequence_num, to_char(ah.action_date, ''DD-MON-YY hh:mi:ss'') action_date, ah.action_code, flv.meaning, flv.description, p.first_name, substr(p.last_name, 1,1) last_name, p.full_name, ah.employee_id, h.segment1 po_num, r.release_num, ah.object_revision_num rev_num, 
ah.approval_path_id, ah.note, to_char(ah.last_update_date, ''DD-MON-YY hh:mi:ss'') last_update_date, ah.last_updated_by, to_char(ah.creation_date, ''DD-MON-YY hh:mi:ss'') creation_date, ah.created_by 
    FROM po_releases_all r,
         po_headers_all h,
         po_action_history ah,
         per_people_f p, fnd_lookup_values flv
    WHERE flv.lookup_code(+) = ah.action_code and flv.language(+) = ''US'' and flv.view_application_id(+) = 201 and flv.lookup_type(+) = ''APPROVER ACTIONS''
    AND ah.object_id = r.po_release_id
    AND   h.po_header_id = r.po_header_id
    AND   p.person_id (+) = ah.employee_id
    AND   sysdate BETWEEN
            p.effective_start_date(+) AND p.effective_end_date (+)
    AND   ah.object_type_code = ''RELEASE''
    AND   ah.object_id = ##$$RELID$$##
    ORDER BY ah.sequence_num desc',
      p_title                  => 'Document Action History',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Document Action History for document number ##$$DOCNUM$$## and release id ##$$RELID$$##.',
      p_solution               => '',
      p_success_msg            => 'No Document Action History found for document number ##$$DOCNUM$$## and release id ##$$RELID$$##.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '20'
      );
   l_info.delete;
debug('end add_signature: Note390023.1_case_REL7');



