           prda.REQUEST_ID,
           prda.PROGRAM_APPLICATION_ID,
           prda.PROGRAM_ID,
           prda.PROGRAM_UPDATE_DATE,
           prda.END_ITEM_UNIT_NUMBER,
           prda.ORG_ID,
           prda.AWARD_ID,
           prda.RECOVERABLE_TAX,
           prda.NONRECOVERABLE_TAX,
           prda.RECOVERY_RATE,
           prda.TAX_RECOVERY_OVERRIDE_FLAG,
           prda.OKE_CONTRACT_LINE_ID,
           prda.OKE_CONTRACT_DELIVERABLE_ID,
           prda.REQ_LINE_AMOUNT,
           prda.REQ_LINE_CURRENCY_AMOUNT,
           prda.REQ_AWARD_ID
from po_line_locations_all plla, po_requisition_lines_all prla, po_req_distributions_all prda, po_distributions_all poda, gl_code_combinations g,
         ( SELECT  FSP.set_of_books_id, GLS.currency_code, COAFS.id_flex_structure_code coa_structure_code, b.concatenated_segment_delimiter delimiter
           FROM financials_system_params_all FSP, gl_sets_of_books GLS, fnd_id_flex_structures COAFS, fnd_id_flex_structures b
           WHERE
           b.id_flex_code = COAFS.id_flex_code
           AND b.id_flex_structure_code = COAFS.id_flex_structure_code
           AND b.id_flex_num = GLS.chart_of_accounts_id 
           AND FSP.org_id= ##$$ORGID$$##
           AND FSP.set_of_books_id = GLS.set_of_books_id
           AND COAFS.id_flex_num = GLS.chart_of_accounts_id
           AND COAFS.application_id = 101 /** SQLGL **/
           AND COAFS.id_flex_code = ''GL#''
          ) gcf
where
g.code_combination_id = prda.code_combination_id
and prda.requisition_line_id = prla.requisition_line_id 
and prla.line_location_id = plla.line_location_id
and ( (prda.distribution_id = poda.req_distribution_id) or 
      (poda.line_location_id = plla.line_location_id) )
and plla.po_release_id = ##$$RELID$$##
order by PRDA.distribution_id

',
      p_title                  => 'Requisition Distributions related to this Blanket Release',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'No requisition distributions associated at the Purchase Order Distribution for this Blanket Release',
      p_solution               => '',
      p_success_msg            => 'Requisition Distribution Details for Requisitions related to this Blanket Release',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
