debug('begin add_signature: EBS_MFG_PO_APPRVL_AUTHORIZATION_STATUS_VS_APPROVED_FLAG_REL');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '29098',
      p_sig_id                 => 'EBS_MFG_PO_APPRVL_AUTHORIZATION_STATUS_VS_APPROVED_FLAG_REL',
      p_sig_sql                => 'select pora.org_id, pora.release_num, pora.po_header_id, pora.po_release_id, pora.authorization_status,
pora.approved_flag "Release Approved Flag", plla.approved_flag "Release Shipment Approved Flag", 
pora.cancel_flag "Release Cancel Flag", plla.cancel_flag "Release Shipment Cancel Flag",
plla.shipment_num, plla.line_location_id, pora.acceptance_required_flag, change_requested_by
from po_releases_all pora, po_line_locations_all plla
where pora.po_release_id = plla.po_release_id
AND pora.authorization_status = ''APPROVED''
AND (plla.approved_flag = ''R'' or pora.approved_flag = ''R'')
and pora.po_release_id = ##$$RELID$$##',
      p_title                  => 'AUTHORIZATION_STATUS = APPROVED but APPROVED_FLAG = R',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Purchase Release AUTHORIZATION_STATUS = APPROVED, however the APPROVED_FLAG = R on the Release Header or the Release Shipment(s) for this Purchase Release.',
      p_solution               => 'This is an unexpected data scenario.  When the Purchase Release document AUTHORIZATION_STATUS = APPROVED, the APPROVED_FLAG on both the Release Header and the Release Shipment should be ''Y''.  This likely requires a datafix.  One possible datafix is when this issue arises after a change request; the datafix script in [453551/KB625956] may be applicable for this case.  You may upload this Procurement Approval Analyzer output to an SR for further analysis.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
