debug('begin add_signature: Note1565821.1');
   l_info('##MASK##ASSIGNED_USER'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##MASK##PERFORMED_BY'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1732',
      p_sig_id                 => 'Note1565821.1',
      p_sig_sql                => 'select distinct
        poh.po_header_id, poh.org_id, poh.segment1, poh.authorization_status, poh.wf_item_key, 
        poh.revision_num, pohaa.revision_num ARCHIVE_REVISION_NUM,
        poh.ame_approval_id POH_AME_APPROVAL_ID, pohaa.ame_approval_id POH_ARCHIVE_AME_APPROVAL_ID,
            to_char(ias.begin_date,''DD-MON-RR HH24:MI:SS'') begin_date,
            to_char(ias.end_date,''DD-MON-RR HH24:MI:SS'') end_date,
            ap.name||''/''||pa.instance_label Activity,
            ias.activity_status Status,
            ias.activity_result_code Result,
            ias.assigned_user assigned_user,
            ias.notification_id NID,
            ntf.status "Status",
            ias.action,
            ias.performed_by
    from    wf_item_activity_statuses ias,
            wf_process_activities pa,
            wf_activities ac,
            wf_activities ap,
            wf_items i,
            wf_notifications ntf,
            po_headers_all poh,
        po_headers_archive_all pohaa
    where   ias.item_type = ''POAPPRV''
    and     ias.process_activity    = pa.instance_id
    and     pa.activity_name        = ac.name
    and     pa.activity_item_type   = ac.item_type
    and     pa.process_name         = ap.name
    and     ias.activity_result_code = ''NO_NEXT_APPROVER''
   and     ap.name||''/''||pa.instance_label = ''AME_ROUTING/GET_NEXT_APPROVER_AME''
   and     poh.AME_APPROVAL_ID = pohaa.AME_APPROVAL_ID 
   and     poh.ame_approval_id is not null
    and     pa.process_item_type    = ap.item_type
    and     pa.process_version      = ap.version
    and     i.item_type             = ''POAPPRV''
    and     i.item_key              = ''##$$ITMKEY$$##''
    and     i.item_key              = ias.item_key
    and     ias.item_key            = poh.wf_item_key
    and     ias.item_type           = poh.wf_item_type
  and pohaa.revision_num = poh.revision_num - 1
  and pohaa.po_header_id = poh.po_header_id
  and poh.revision_num >= 1
    and     poh.authorization_status = ''APPROVED''
    and     i.begin_date            >= ac.begin_date
    and     i.begin_date            < nvl(ac.end_date, i.begin_date+1)
    and     ntf.notification_id(+)  = ias.notification_id

and exists
(
SELECT subdir, af.filename, afv.version 
FROM ad_file_versions afv, ad_files af 
WHERE 
afv.version_segment1 = (select max(TO_NUMBER(version_segment1)) from ad_file_versions where file_id = afv.file_id) 
and afv.version_segment2 = (select max(TO_NUMBER(version_segment2)) from ad_file_versions where file_id = afv.file_id and afv.version_segment1 = version_segment1) 
and afv.version_segment3 = (select max(TO_NUMBER(version_segment3)) from ad_file_versions where file_id = afv.file_id and afv.version_segment1 = version_segment1 and afv.version_segment2 = version_segment2) 
and afv.version_segment4 = (select max(TO_NUMBER(version_segment4)) from ad_file_versions where file_id = afv.file_id and afv.version_segment1 = version_segment1 and afv.version_segment2 = version_segment2 and afv.version_segment3 = version_segment3) 
and ( 
  (afv.version_segment1 = ''120'' and afv.version_segment3 = ''12020000'' and (afv.version_segment2 < ''11'' or (afv.version_segment2 = ''11'' and afv.version_segment4 < ''7'')) ) 
  or
  (afv.version_segment1 = ''120'' and afv.version_segment3 = ''12010000'' and (afv.version_segment2 < ''8'' or (afv.version_segment2 = ''8'' and afv.version_segment4 < ''7'')) )
    )
and subdir = ''resource'' and afv.file_id = af.file_id AND upper(af.filename) = upper(''POXPIPOL.pll'') 
UNION ALL
SELECT subdir, af.filename, afv.version 
FROM ad_file_versions afv, ad_files af 
WHERE 
afv.version_segment1 = (select max(TO_NUMBER(version_segment1)) from ad_file_versions where file_id = afv.file_id) 
and afv.version_segment2 = (select max(TO_NUMBER(version_segment2)) from ad_file_versions where file_id = afv.file_id and afv.version_segment1 = version_segment1) 
and afv.version_segment3 = (select max(TO_NUMBER(version_segment3)) from ad_file_versions where file_id = afv.file_id and afv.version_segment1 = version_segment1 and afv.version_segment2 = version_segment2) 
and afv.version_segment4 = (select max(TO_NUMBER(version_segment4)) from ad_file_versions where file_id = afv.file_id and afv.version_segment1 = version_segment1 and afv.version_segment2 = version_segment2 and afv.version_segment3 = version_segment3) 
and ( 
  (afv.version_segment1 = ''120'' and afv.version_segment3 = ''12020000'' and (afv.version_segment2 < ''5'' or (afv.version_segment2 = ''5'' and afv.version_segment4 < ''4'')) ) 
  or
  (afv.version_segment1 = ''120'' and afv.version_segment3 = ''12010000'' and (afv.version_segment2 < ''5'' or (afv.version_segment2 = ''5'' and afv.version_segment4 < ''4'')) )
    )
and subdir = ''resource'' and afv.file_id = af.file_id AND upper(af.filename) = upper(''POXPIPOH.pll'') 
UNION ALL
SELECT subdir, af.filename, afv.version 
FROM ad_file_versions afv, ad_files af 
WHERE 
afv.version_segment1 = (select max(TO_NUMBER(version_segment1)) from ad_file_versions where file_id = afv.file_id) 
and afv.version_segment2 = (select max(TO_NUMBER(version_segment2)) from ad_file_versions where file_id = afv.file_id and afv.version_segment1 = version_segment1) 
and afv.version_segment3 = (select max(TO_NUMBER(version_segment3)) from ad_file_versions where file_id = afv.file_id and afv.version_segment1 = version_segment1 and afv.version_segment2 = version_segment2) 
and afv.version_segment4 = (select max(TO_NUMBER(version_segment4)) from ad_file_versions where file_id = afv.file_id and afv.version_segment1 = version_segment1 and afv.version_segment2 = version_segment2 and afv.version_segment3 = version_segment3) 
and ( 
  (afv.version_segment1 = ''120'' and afv.version_segment3 = ''12020000'' and (afv.version_segment2 < ''141'' or (afv.version_segment2 = ''141'' and afv.version_segment4 < ''22'')) ) 
  or
  (afv.version_segment1 = ''120'' and afv.version_segment3 = ''12010000'' and (afv.version_segment2 < ''56'' or (afv.version_segment2 = ''56'' and afv.version_segment4 < ''70'')) )
    )
and subdir = ''patch/115/sql'' and afv.file_id = af.file_id AND upper(af.filename) = upper(''POXWPA1B.pls'') 

)',
      p_title                  => 'Document Approved without Authority',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The revised document is approved without any authorization because the value of Workflow Attribute AME_APPROVAL_ID is not being updated with a new value',
      p_solution               => 'Please review [1565821/KB281098] for more details on this issue and the steps to fix this problem.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: Note1565821.1');



