debug('begin add_signature: Note390023.1_case_REQ6');
   l_info('##MASK##%USER%'):= 'DISPLAY_FIRST_25_PCNT_WORD';
   l_info('##MASK##SUBJECT'):= 'DISPLAY_FIRST_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Doc ID'):= '390023.1';
  add_signature(
      p_sig_repo_id            => '1741',
      p_sig_id                 => 'Note390023.1_case_REQ6',
      p_sig_sql                => 'SELECT rh.wf_item_type, rh.wf_item_key req_wf_item_key,
           ias.notification_id notification_id,
           ias.item_key notification_item_key,
           ias.assigned_user, n.to_user, n.subject

    FROM wf_item_activity_statuses ias,
         wf_notifications n,
         po_requisition_headers_all rh
    WHERE ias.notification_id is not null
    AND   ias.notification_id = n.group_id
    AND   n.status = ''OPEN''
    AND   rh.requisition_header_id = ##$$DOCID$$##
    AND   rh.authorization_status IN (''IN PROCESS'', ''PRE-APPROVED'')
    AND   ias.item_type = ''REQAPPRV''
    AND   ias.item_key IN (
            SELECT i.item_key
            FROM wf_items i
            START WITH i.item_type = rh.wf_item_type
            AND   i.item_key = rh.wf_item_key
            CONNECT BY PRIOR i.item_type = i.parent_item_type
            AND   PRIOR i.item_key = i.parent_item_key
            AND   nvl(i.end_date, sysdate+1) >= sysdate)',
      p_title                  => 'Open Notifications for Document',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'This document has an open approval workflow notification.
     To progress this document you should process this notification
     via the application rather than resetting the document.',
      p_solution               => 'Review notification details listed and insure the responsible
     party processes the open notification for the document.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: Note390023.1_case_REQ6');



debug('begin add_signature: Note390023.1_case_REQ7');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Doc ID'):= '390023.1';
  add_signature(
      p_sig_repo_id            => '1742',
      p_sig_id                 => 'Note390023.1_case_REQ7',
      p_sig_sql                => 'SELECT ''Wrong Encumbrance Amount''
    FROM dual
    WHERE EXISTS (
            SELECT 1
            FROM po_requisition_lines_all l,
                 po_req_distributions_all d
            WHERE l.requisition_header_id = ##$$DOCID$$##
            AND   d.requisition_line_id = l.requisition_line_id
            AND   l.matching_basis = ''QUANTITY''
            AND   nvl(d.encumbered_flag, ''N'') = ''Y''
            AND   nvl(l.cancel_flag, ''N'') = ''N''
            AND   nvl(l.closed_code, ''OPEN'') <> ''FINALLY CLOSED''
            AND   nvl(d.prevent_encumbrance_flag, ''N'') = ''N''
            AND   d.budget_account_id IS NOT NULL
            AND   round(nvl(d.encumbered_amount, 0), 2) <>
                    round(l.unit_price * d.req_line_quantity +
                    nvl(d.nonrecoverable_tax, 0), 2)
            UNION
            SELECT 1
            FROM po_requisition_lines_all l,
                 po_req_distributions_all d
            WHERE l.requisition_header_id = ##$$DOCID$$##
            AND   d.requisition_line_id = l.requisition_line_id
            AND   l.matching_basis = ''AMOUNT''
            AND   nvl(d.encumbered_flag, ''N'') = ''Y''
            AND   nvl(l.cancel_flag, ''N'') = ''N''
            AND   nvl(l.closed_code, ''OPEN'') <> ''FINALLY CLOSED''
            AND   nvl(d.prevent_encumbrance_flag, ''N'') = ''N''
            AND   d.budget_account_id IS NOT NULL
            AND   round(nvl(d.encumbered_amount, 0), 2) <>
                    round(d.req_line_amount +
                    nvl(d.nonrecoverable_tax, 0), 2))',
      p_title                  => 'Encumbrance Amount Validation',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'This requisition has at least one distribution with an incorrect encumbrance amount.  
The document reset scripts cannot be run against this document.

To reset this document you would need to create a Service Request with customer support.',
      p_solution               => ' ',
      p_success_msg            => ' ',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: Note390023.1_case_REQ7');



