debug('begin add_signature: PO_WF_FILE_VERSION_POXWFPOA_WFT_12_2');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '10115',
      p_sig_id                 => 'PO_WF_FILE_VERSION_POXWFPOA_WFT_12_2',
      p_sig_sql                => 'select af.filename, av.version
     from ad_files af,
          ad_file_versions av
     where af.file_id= av.file_id
       and lower(af.filename) = ''poxwfpoa.wft''
       and af.subdir like ''%US%''
       and av.version = po_apprvl_analyzer_pkg.max_file_version(af.filename)
       AND po_apprvl_analyzer_pkg.compare_versions(po_apprvl_analyzer_pkg.max_file_version(''poxwfpoa.wft''), ''120.51.12020000.50'') < 0
UNION ALL
select af.filename, av.version
     from ad_files af,
          ad_file_versions av
     where af.file_id= av.file_id
       and lower(af.filename) = ''poxwfrqa.wft''
       and af.subdir like ''%US%''
       and av.version = po_apprvl_analyzer_pkg.max_file_version(af.filename)
       AND po_apprvl_analyzer_pkg.compare_versions(po_apprvl_analyzer_pkg.max_file_version(''poxwfrqa.wft''), ''120.38.12020000.22'') < 0
',
