debug('begin add_signature: PO_INVALIDS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1692',
      p_sig_id                 => 'PO_INVALIDS',
      p_sig_sql                => 'SELECT a.object_name "Object_Name",
           decode(a.object_type,
             ''PACKAGE'', ''Package Spec'',
             ''PACKAGE BODY'', ''Package Body'',
             a.object_type) type,
           (
             SELECT ltrim(rtrim(substr(substr(c.text, instr(c.text,''Header: '')),
               instr(substr(c.text, instr(c.text,''Header: '')), '' '', 1, 1),
               instr(substr(c.text, instr(c.text,''Header: '')), '' '', 1, 2) -
               instr(substr(c.text, instr(c.text,''Header: '')), '' '', 1, 1)
               ))) || '' - '' ||
               ltrim(rtrim(substr(substr(c.text, instr(c.text,''Header: '')),
               instr(substr(c.text, instr(c.text,''Header: '')), '' '', 1, 2),
               instr(substr(c.text, instr(c.text,''Header: '')), '' '', 1, 3) -
               instr(substr(c.text, instr(c.text,''Header: '')), '' '', 1, 2)
               )))
             FROM dba_source c
             WHERE c.owner = a.owner
             AND   c.name = a.object_name
             AND   c.type = a.object_type
             AND   c.line = 2
             AND   c.text like ''%$Header%''
           ) "File Version",
           b.text "Error Text"
    FROM dba_objects a,
         dba_errors b
    WHERE a.object_name = b.name(+)
    AND a.object_type = b.type(+)
    AND a.owner = ''APPS''
    AND (a.object_name like ''PO%'' OR
         a.object_name like ''ECX%'' OR
         a.object_name like ''XLA%'')
    AND a.status = ''INVALID''',
      p_title                  => 'Purchasing Related Invalid Objects',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There exist invalid Purchasing related objects',
      p_solution               => '<ul>
      <li>Recompile the individual objects or recompile the
          entire APPS schema with adadmin</li>
      <li>Review any error messages provided and see [1527251/KB724238]
          for details on compiling these invalid objects.</li>
   </ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: PO_INVALIDS');



debug('begin add_signature: PO_PROFILE_ICX_NUMERIC_CHARACTERS');
   l_info('##MASK##PLEVELVALUE'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '15303',
      p_sig_id                 => 'PO_PROFILE_ICX_NUMERIC_CHARACTERS',
      p_sig_sql                => 'SELECT distinct fpo.profile_option_name, fpot.user_profile_option_name,
DECODE(fpov.level_id,10001,null,10002,null,10003,fndr.responsibility_name,10004,fndu.user_name) plevelvalue,
DECODE(fpov.level_id,10001,''Site'',10002,''Application'',10003,''Responsibility'',10004,''UserID'') plevel,
fpov.profile_option_value
FROM fnd_profile_option_values fpov,
fnd_profile_options fpo,
fnd_profile_options_tl fpot,
fnd_responsibility_tl fndr,
fnd_user fndu
WHERE fpo.profile_option_id = fpov.profile_option_id AND
fpo.profile_option_name = fpot.profile_option_name AND
TRUNC(fpo.start_date_active) <= SYSDATE AND
(fpot.user_profile_option_name = ''ICX: Numeric characters''  AND
fpot.language = ''US'') AND
(
(fpov.level_id IN (10001))
or
(fpov.level_id IN (10002) and fpov.application_id = 201)
or
(fpov.level_id IN (10003) and fndr.application_id = 201 and fndr.responsibility_id = fpov.level_value)
or
(fpov.level_id IN (10004) and fndu.user_id = fpov.level_value)
)
AND
fndr.language = ''US'' and fndr.application_id = 201 -- Replace with responsibility name used for iProcurement
AND
fndu.employee_id = ##$$AGENTID$$##',
      p_title                  => 'Profile ICX: Numeric Characters',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Profile ''ICX: Numeric characters'' does not have a value set for Site, application (Purchasing), responsibility (associated to Purchasing application), or user (buyer) level',
      p_solution               => 'Review [1520871/KB746244#aref_section21] and set the profile value per the instructions and clarification provided.',
      p_success_msg            => 'Profile ''ICX: Numeric characters'' has a value set for Site, application (Purchasing), responsibility (associated to Purchasing application), or user (buyer) level',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
