debug('begin add_signature: POA_WORKFLOW_BACKGROUND_PROCESS_NOT_RUN_FOR_DEFERRED_WITHIN_LAST_12HOURS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '15967',
      p_sig_id                 => 'POA_WORKFLOW_BACKGROUND_PROCESS_NOT_RUN_FOR_DEFERRED_WITHIN_LAST_12HOURS',
      p_sig_sql                => 'SELECT fcr.request_id id
, fl.meaning
, fcpv.concurrent_program_name
, fcpv.user_concurrent_program_name rpname
, to_char(fcr.actual_start_date, ''DD-MON-RR HH24:MI:SS'') sd
, fcrf.argument_text
FROM fnd_concurrent_requests fcr
, fnd_concurrent_programs_vl fcpv
, fnd_conc_requests_form_v fcrf
, fnd_lookups fl
WHERE fl.lookup_type = ''CP_STATUS_CODE''
AND fl.lookup_code = fcr.status_code
AND fcr.concurrent_program_id = fcpv.concurrent_program_id
AND fcr.program_application_id = fcpv.application_id
AND fcr.request_id = fcrf.request_id
AND fcr.actual_start_date > sysdate - 0.5
  AND (fcrf.argument4 = ''Y'')  --Deferred = Y
  AND (fcrf.argument_text like concat(''##$$ITMTYPE$$##'',''%'') or fcrf.argument_text like '',%'')
AND fcpv.concurrent_program_name = ''FNDWFBG''
ORDER BY fcr.actual_start_date, fcr.request_id',
      p_title                  => 'Workflow Background Process Has Not Been Run for Deferred Procurement Approvals Within Last 12 Hours',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Workflow Background Process has NOT been run for Deferred Procurement Approvals within the last 12 hours.  As a result, any approvals deferred within the last 12 hours will not be progressed to the next step of approval.',
      p_solution               => 'Review [884391/KB327582] for details about Purchase Order and Requisition approval workflows affected when this process has not been run recently.  Run the background process, or setup the background process to run on a schedule as described in the above document.',
      p_success_msg            => 'The workflow background process has been run within the last 12 hours for either the Procurement approval workflow or for all workflows.  Depending when the process was last run, there may still be some documents not yet processed, but those will be processed the next time the process is run (manually or per scheduled run)',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: POA_WORKFLOW_BACKGROUND_PROCESS_NOT_RUN_FOR_DEFERRED_WITHIN_LAST_12HOURS');



