debug('begin add_signature: DATA_SINGLE_POREL4');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Bug Number'):= '14782923';
   l_info('Doc ID'):= '1379274.1';
   l_info('Script Name'):= 'poxpoaprvl.sql';
  add_signature(
      p_sig_repo_id            => '2248',
      p_sig_id                 => 'DATA_SINGLE_POREL4',
      p_sig_sql                => 'SELECT po_header_id,
           segment1 po_number,
           org_id,
           cancel_flag,
           authorization_status
    FROM po_headers_all
    WHERE po_header_id = ##$$DOCID$$##
    AND   nvl(cancel_flag, ''N'') = ''Y''
