debug('begin add_signature: EBS_MFG_PO_DIFFERENCE_BETWEEN_PLLA_QUANTITY_AND_PDA_QUANTITY_ORDERED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '25035',
      p_sig_id                 => 'EBS_MFG_PO_DIFFERENCE_BETWEEN_PLLA_QUANTITY_AND_PDA_QUANTITY_ORDERED',
      p_sig_sql                => 'SELECT
    poh.segment1 "PO Number",
    pol.line_num,
    pll.shipment_num,
    pll.org_id,
    poh.po_header_id,
    pll.po_line_id,
    pll.line_location_id,
    pll.cancel_flag,
    pll.quantity SHIP_QUANTITY,
    (pod.quantity_ordered - pod.quantity_cancelled) "DIST Qty Ordered - Cancelled", pod.quantity_ordered dist_quantity_ordered, pod.quantity_cancelled dist_quantity_cancelled
FROM
    po_line_locations_all   pll,
    po_lines_all            pol,
    po_headers_all          poh,
    (select poda.line_location_id, sum(poda.quantity_ordered) quantity_ordered, sum(poda.quantity_cancelled) quantity_cancelled 
    from po_distributions_all poda 
    where poda.po_line_id like NVL(''##$$LINEID$$##'',''%'') and poda.po_header_id = ##$$DOCID$$## group by poda.line_location_id)    pod
WHERE
    nvl(poh.cancel_flag, ''N'') = ''N''
    AND     pll.quantity <> ( pod.quantity_ordered - pod.quantity_cancelled )
    AND     pod.line_location_id = pll.line_location_id
    AND     pll.po_line_id = pol.po_line_id
    AND pll.po_header_id = poh.po_header_id
    AND poh.authorization_status in (''IN PROCESS'', ''REQUIRES REAPPROVAL'')
    AND poh.approved_flag in (''N'',''R'')
    AND pll.approved_flag <> ''Y''
and poh.po_header_id = ##$$DOCID$$##
and pol.po_line_id like NVL(''##$$LINEID$$##'',''%'')
',
      p_title                  => 'Differences in QUANTITY and QUANTITY_ORDER between PO_LINE_LOCATIONS_ALL AND PO_DISTRIBUTIONS_ALL',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Analyzer identified that following error :
  Error: Line # quantity (xx) does not match shipment quantity (yy).
  Error: Line # Shipment # quantity (yy) does not match distribution quantity (xx).

can occur when PO is submitted for approval, because of the differences in PO_LINE_LOCATIONS_ALL.QUANTITY and PO_DISTRIBUTIONS_ALL.QUANTITY_ORDER, when there is no cancelled quantity neither on PO shipments nor on PO distributions

This is mentioned also in below documentation :
Error: Shipment #1 Quantity Does Not Match Distribution Quantity [2817472/KB694683]',
      p_solution               => 'Please raise a Service Request with Oracle Support for obtaining a datafix that will correct this issue.

Following documentation outlines the solution :
Error: Shipment #1 Quantity Does Not Match Distribution Quantity [2817472/KB694683]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_PO_DIFFERENCE_BETWEEN_PLLA_QUANTITY_AND_PDA_QUANTITY_ORDERED');



