---------------------------------
-- MAIN ENTRY POINT
---------------------------------
PROCEDURE main(
            p_analysis_mode                IN VARCHAR2    DEFAULT NULL
           ,p_org_id                       IN NUMBER      DEFAULT NULL
           ,p_trx_type                     IN VARCHAR2    DEFAULT NULL
           ,p_trx_num                      IN VARCHAR2    DEFAULT NULL
           ,p_release_num                  IN NUMBER      DEFAULT NULL
           ,p_from_date                    IN DATE        DEFAULT NULL
           ,p_max_output_rows              IN NUMBER      DEFAULT 20
           ,p_debug_mode                   IN VARCHAR2    DEFAULT 'Y')

 IS

  l_sql_result VARCHAR2(1);
  l_step       VARCHAR2(5);
  --l_analyzer_end_time   TIMESTAMP;

BEGIN

  l_step := '1';
  initialize_globals;

  -- Workaround for handling debugging before file init
  g_debug_mode := nvl(p_debug_mode, 'Y');
  g_params_string := '';



  l_step := '10';
  initialize_files;

  analyzer_title := 'Procurement Approval Analyzer';
  analyzer_title := regexp_replace('EBS ' || analyzer_title, '(\S+\s)\1', '\1', 1, 0, 'i');  -- EBSAF-243

  l_step := '15';
   validate_parameters(
     p_analysis_mode                => p_analysis_mode
    ,p_org_id                       => p_org_id
    ,p_trx_type                     => nvl(p_trx_type,'ANY')
    ,p_trx_num                      => p_trx_num
    ,p_release_num                  => p_release_num
    ,p_from_date                    => p_from_date
    ,p_max_output_rows              => p_max_output_rows
    ,p_debug_mode                   => p_debug_mode
  );


  l_step := '20';
  set_cloud_flag;

  l_step := '23';
  set_snap_days;

  l_step := '25';
  print_page_header;

  l_step := '30';
  print_rep_header(analyzer_title);
  --print_execdetails;
  print_feedback;
  print_parameters;
  print_whatsnew;

  l_step := '40';
  load_signatures;

  l_step := '45';
  create_hyperlink_table;

  l_step := '50';
  initialize_hidden_xml;

  -- Start of Sections and signatures
  l_step := '60';
  debug('begin section: Main Section');
  -- Print the menu of the section screen
  start_main_section;

debug('begin section: SINGLE_DOC_DETAILS');
IF p_trx_num is not null THEN
   start_section('Single Document Details', 'SINGLE_DOC_DETAILS');
      IF p_trx_num is not null AND g_app_method = 'POSITION' THEN
         set_item_result(run_stored_sig('DOC_DETAIL_DOC_TYPE'));
      END IF;
      IF p_trx_num is not null AND (g_app_method <> 'POSITION' OR g_app_path_id is null) THEN
         set_item_result(run_stored_sig('EBS_MFG_PO_APPRVL_DOC_TYPE_NO_POS_HIERARCHY'));
      END IF;
      set_item_result(run_stored_sig('DOC_DETAIL_DOC_TYPE_INCOMPLETE_PO_AME_SETUP'));
      set_item_result(run_stored_sig('AME_LOCAL_BPA_NOT_SUPPORTED'));
      IF p_trx_type IN ('PO','PA') THEN
         IF g_pre_12_1_3 THEN
            set_item_result(run_stored_sig('DOC_DETAIL_PO_HEADER_NO_AME_APP_ID'));
         END IF;
         IF NOT g_pre_12_1_3 THEN
            set_item_result(run_stored_sig('DOC_DETAIL_PO_HEADER'));
            set_item_result(run_stored_sig('DOC_DETAIL_PO_HEADER_ARCHIVE'));
         END IF;
         set_item_result(run_stored_sig('EBS_MFG_PO_APPRVL_MAX_ARCHIVE_REV_GREATER_THAN_CURRENT_REV'));
         set_item_result(run_stored_sig('DOC_DETAIL_PO_LINES'));
         set_item_result(run_stored_sig('DOC_DETAIL_PO_LINES_ARCHIVE'));
         set_item_result(run_stored_sig('DOC_DETAIL_PO_LINE_LOCATIONS'));
         set_item_result(run_stored_sig('DOC_DETAIL_PO_LINE_LOCATIONS_ARCHIVE'));
         set_item_result(run_stored_sig('DOC_DETAIL_PO_DISTS'));
         set_item_result(run_stored_sig('DOC_DETAIL_PO_DISTS_ARCHIVE'));
         set_item_result(run_stored_sig('EBS_MFG_PO_APPRVL_CHARGEABLE_FLAG_FOR_TASK_ID'));
         set_item_result(run_stored_sig('EBS_MFG_PO_DOC_ATTACHMENTS'));
         set_item_result(run_stored_sig('NOTE390023.1_CASE_PO10'));
         set_item_result(run_stored_sig('PO_RELATED_REQ_DISTRIBUTIONS'));
         IF g_include_clm THEN
            set_item_result(run_stored_sig('PO_RELATED_REQ_LINES_WITH_CLM'));
         END IF;
         IF NOT g_include_clm THEN
            set_item_result(run_stored_sig('PO_RELATED_REQ_LINES'));
         END IF;
         set_item_result(run_stored_sig('EBS_MFG_PO_APPRVL_PO_RELATED_REQ_LINES_SOURCE_DOCS'));
         IF g_notify_req_flag = 'Column available' THEN
            set_item_result(run_stored_sig('EBS_MFG_PO_APPRVL_PO_RELATED_REQ_HEADER_V2'));
         END IF;
         IF g_notify_req_flag = 'Column not available' THEN
            set_item_result(run_stored_sig('PO_RELATED_REQ_HEADER'));
         END IF;
         IF substr(g_sql_tokens('##$$REL$$##'),1,4) = '12.1' THEN
            set_item_result(run_stored_sig('Note1565821.1'));
            set_item_result(run_stored_sig('WFSTAT_NOTE2054356.1_12.1'));
         END IF;
         set_item_result(run_stored_sig('DOC_DETAIL_STYLE'));
         set_item_result(run_stored_sig('DOC_DETAIL_DOC_STYLE_INCOMPLETE_PO_AME_SETUP'));
         IF substr(g_sql_tokens('##$$REL$$##'),1,4) = '12.2' THEN
            set_item_result(run_stored_sig('Note1565821.1'));
            set_item_result(run_stored_sig('WFSTAT_NOTE2054356.1_12.2'));
            set_item_result(run_stored_sig('WF_APPROVAL_PROCESS_PO_DOC_STYLE_HEADERS_COMPLEX_PO'));
         END IF;
         set_item_result(run_stored_sig('PO_ALL_DOC_STYLE_LINES'));
         set_item_result(run_stored_sig('VERIFY BLANKET AGREEMENT IF GLOBAL'));
         set_item_result(run_stored_sig('EBS_MFG_APPRVL_PO_SUPPLIER_DOES_NOT_HAVE_A_SUPPLIER_SITE_SPECIFIED'));
         set_item_result(run_stored_sig('PO - AP_SUPPLIERS'));
         set_item_result(run_stored_sig('PO - AP_SUPPLIER_SITES'));
         set_item_result(run_stored_sig('PO - AP_SUPPLIER_CONTACTS'));
         set_item_result(run_stored_sig('EBS_MFG_PO_APPRVL_EDI_ECX_INFO'));
         set_item_result(run_stored_sig('EBS_MFG_PO_APPRVL_EDI_ECX_DOCLOGS'));
         set_item_result(run_stored_sig('PO - PO_AGENTS_ALL'));
         set_item_result(run_stored_sig('TERMINATE_BUYER_IN_SPECIFIC_PO'));
         set_item_result(run_stored_sig('EBS_MFG_PO_APPRVL_AUTHORIZATION_STATUS_VS_APPROVED_FLAG'));
      END IF;
      IF p_trx_type = 'REQUISITION' THEN
         IF g_notify_req_flag = 'Column available' THEN
            set_item_result(run_stored_sig('EBS_MFG_PO_APPRVL_DOC_DETAIL_REQ_HEADER_V2'));
         END IF;
         IF g_notify_req_flag = 'Column not available' THEN
            set_item_result(run_stored_sig('DOC_DETAIL_REQ_HEADER'));
         END IF;
         IF g_include_clm THEN
            set_item_result(run_stored_sig('DOC_DETAIL_REQ_LINES_WITH_CLM'));
         END IF;
         IF NOT g_include_clm THEN
            set_item_result(run_stored_sig('DOC_DETAIL_REQ_LINES'));
         END IF;
